export const ARTICLE_SERVER_RENDERED_PAYLOAD: Record<string, ArticleServerPayload> = {
  "deutsche-sprache-geschichte": {
    "content": "\n\n<!-- ════════════════════ HERO ════════════════════ -->\n<header class=\"hero\">\n  <p class=\"hero-eyebrow\">Sprachgeschichte · Von der Urzeit bis zur Gegenwart</p>\n  <h1>Die Geschichte<br>der <em>deutschen Sprache</em></h1>\n  <p class=\"hero-sub\">Von den rekonstruierten indogermanischen Wurzeln über Althochdeutsch und Luthers Bibel bis zur modernen Standardsprache — zentrale Entwicklungslinien mit bewusst gerundeten Datierungen.</p>\n\n  <div class=\"era-strip\">\n    <span class=\"era-pill pill-indg\">Indogermanisch</span>\n    <span class=\"era-pill pill-germ\">Germanisch</span>\n    <span class=\"era-pill pill-ahd\">Althochdeutsch</span>\n    <span class=\"era-pill pill-mhd\">Mittelhochdeutsch</span>\n    <span class=\"era-pill pill-fnhd\">Frühneuhochdeutsch</span>\n    <span class=\"era-pill pill-nhd\">Neuhochdeutsch</span>\n    <span class=\"era-pill pill-mod\">Gegenwart</span>\n  </div>\n  <p class=\"era-sublabel\">ca. 2500 v. Chr. · bis heute</p>\n</header>\n\n<!-- ════════════════════ TIMELINE BAR ════════════════════ -->\n<div class=\"container\" style=\"max-width:880px; padding-bottom:0;\">\n  <div class=\"timeline-bar-wrap\">\n    <div class=\"timeline-bar\">\n      <div class=\"tb-seg tb-indg\"></div>\n      <div class=\"tb-seg tb-germ\"></div>\n      <div class=\"tb-seg tb-ahd\"></div>\n      <div class=\"tb-seg tb-mhd\"></div>\n      <div class=\"tb-seg tb-fnhd\"></div>\n      <div class=\"tb-seg tb-nhd\"></div>\n      <div class=\"tb-seg tb-mod\"></div>\n    </div>\n    <div class=\"timeline-labels\">\n      <span>~2500 v. Chr.</span>\n      <span>~500 v. Chr.</span>\n      <span>750 n. Chr.</span>\n      <span>1050</span>\n      <span>1350</span>\n      <span>1650</span>\n      <span>1900–heute</span>\n    </div>\n  </div>\n</div>\n\n<!-- ════════════════════ MAIN ════════════════════ -->\n<div class=\"container\">\n\n  <div class=\"section-header\"><h2>Sprachstufen im Detail</h2></div>\n\n  <!-- ─── INDOGERMANISCH ─── -->\n  <div class=\"era-card lv-indg\" id=\"era-indg\">\n    <div class=\"era-card-header\" onclick=\"toggleEra('era-indg')\">\n      <div class=\"era-year-block\">\n        <span class=\"era-abbr\">Urg.</span>\n        <span class=\"era-date\">~4000–500 v. Chr.</span>\n      </div>\n      <div>\n        <p class=\"era-title\">Indogermanisch & Germanisch</p>\n        <p class=\"era-subtitle\">Die Wurzeln — lange vor dem Deutschen</p>\n      </div>\n      <div class=\"era-toggle\">▾</div>\n    </div>\n    <div class=\"era-body\">\n      <p class=\"era-description lv-indg\">\n        Das Deutsche gehört zur Sprachfamilie des <strong>Indogermanischen</strong> (auch Indoeuropäisch), einer rekonstruierten Protosprache, die vor mehreren Jahrtausenden auf dem eurasischen Kontinent gesprochen wurde. Aus dieser gemeinsamen Wurzel entwickelten sich im Laufe von Jahrtausenden zahlreiche Sprachzweige — darunter auch das <strong>Germanische</strong>, die direkte Vorfahrensprache des Deutschen. Das Indogermanische selbst ist nicht schriftlich überliefert; Linguisten haben es durch systematischen Vergleich verwandter Sprachen <em>rekonstruiert</em>. Wörter wie <em>*pṓds</em> (Fuß), <em>*mātér</em> (Mutter) oder <em>*nókʷts</em> (Nacht) lassen sich in Dutzenden europäischer und asiatischer Sprachen wiedererkennen.\n      </p>\n\n      <div class=\"fact-box\">\n        <strong>Was ist Sprachrekonstruktion?</strong> Sprachwissenschaftler erschließen die Ursprache durch das Vergleichende Methode (comparative method): Wenn viele nicht miteinander in Kontakt stehende Sprachen dasselbe Wort in ähnlicher Form kennen, lässt sich die ursprüngliche Form rückschließen. Das rekonstruierte Wort wird mit einem Sternchen (*) markiert.\n      </div>\n\n      <div class=\"era-grid\">\n        <div class=\"era-block\">\n          <h4>Indogermanische Sprachfamilien (Auswahl)</h4>\n          <ul>\n            <li><strong>Germanisch:</strong> Deutsch, Englisch, Niederländisch, Schwedisch, Norwegisch, Isländisch</li>\n            <li><strong>Romanisch:</strong> Latein → Französisch, Spanisch, Portugiesisch, Italienisch, Rumänisch</li>\n            <li><strong>Slawisch:</strong> Russisch, Polnisch, Ukrainisch, Tschechisch, Serbisch</li>\n            <li><strong>Indoiranisch:</strong> Sanskrit → Hindi, Urdu, Persisch</li>\n            <li><strong>Baltisch:</strong> Litauisch, Lettisch</li>\n            <li><strong>Griechisch, Keltisch, Albanisch, Armenisch</strong></li>\n          </ul>\n        </div>\n        <div class=\"era-block\">\n          <h4>Gemeinsame Wurzelwörter (Beispiele)</h4>\n          <ul>\n            <li><strong>Mutter:</strong> dt. <em>Mutter</em> · engl. <em>mother</em> · lat. <em>mater</em> · skr. <em>mātā</em></li>\n            <li><strong>Nacht:</strong> dt. <em>Nacht</em> · engl. <em>night</em> · lat. <em>nox</em> · griech. <em>nyx</em></li>\n            <li><strong>Drei:</strong> dt. <em>drei</em> · engl. <em>three</em> · lat. <em>tres</em> · russ. <em>tri</em></li>\n            <li><strong>Wasser:</strong> dt. <em>Wasser</em> · engl. <em>water</em> · russ. <em>voda</em></li>\n            <li><strong>Feuer:</strong> dt. <em>Feuer</em> · griech. <em>pyr</em> · engl. <em>fire</em></li>\n          </ul>\n        </div>\n        <div class=\"era-block card-block-full\">\n          <h4>Vom Germanischen zum Deutschen — drei Hauptzweige</h4>\n          <div class=\"feature-tags\">\n            <span class=\"feature-tag\">Nordgermanisch → Skandinavische Sprachen</span>\n            <span class=\"feature-tag\">Ostgermanisch → Gotisch (ausgestorben)</span>\n            <span class=\"feature-tag\">Westgermanisch → Deutsch, Englisch, Niederländisch, Friesisch</span>\n            <span class=\"feature-tag\">Urgermanisch ca. 500 v. Chr. – 200 n. Chr.</span>\n            <span class=\"feature-tag\">Erste Lautverschiebung (Grimmsches Gesetz) trennt Germanisch von anderen</span>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"family-grid\">\n        <div class=\"fg-cell\">\n          <div class=\"fg-icon\">🌍</div>\n          <div class=\"fg-label\">Nordgermanisch</div>\n          <div class=\"fg-langs\">Schwedisch, Dänisch,<br>Norwegisch, Isländisch,<br>Färöisch</div>\n        </div>\n        <div class=\"fg-cell\">\n          <div class=\"fg-icon\">📜</div>\n          <div class=\"fg-label\">Ostgermanisch</div>\n          <div class=\"fg-langs\">Gotisch (†), Vandalisch (†),<br>Burgundisch (†)<br><em>— heute ausgestorben —</em></div>\n        </div>\n        <div class=\"fg-cell\">\n          <div class=\"fg-icon\">🇩🇪</div>\n          <div class=\"fg-label\">Westgermanisch</div>\n          <div class=\"fg-langs\">Deutsch, Englisch,<br>Niederländisch, Friesisch,<br>Luxemburgisch, Jiddisch</div>\n        </div>\n      </div>\n\n    </div>\n  </div>\n\n  <!-- ─── ERSTE LAUTVERSCHIEBUNG / GRIMM ─── -->\n  <div class=\"era-card lv-germ\" id=\"era-germ\">\n    <div class=\"era-card-header\" onclick=\"toggleEra('era-germ')\">\n      <div class=\"era-year-block\">\n        <span class=\"era-abbr\" style=\"font-size:1.1rem;\">1. LS</span>\n        <span class=\"era-date\">~500 v. Chr.</span>\n      </div>\n      <div>\n        <p class=\"era-title\">Die Erste Lautverschiebung</p>\n        <p class=\"era-subtitle\">Grimmsches Gesetz — Germanisch trennt sich vom Rest</p>\n      </div>\n      <div class=\"era-toggle\">▾</div>\n    </div>\n    <div class=\"era-body\">\n      <p class=\"era-description lv-germ\">\n        Bevor wir zum Deutschen selbst kommen, ist die <strong>Erste (Germanische) Lautverschiebung</strong> wichtig, die Jacob Grimm im 19. Jahrhundert systematisch beschrieb. Der Ausdruck bezeichnet mehrere regelhafte Konsonantenveränderungen im frühen Germanischen; ihre genaue Datierung ist in der Forschung nur näherungsweise möglich. Sie grenzt die germanischen Sprachen von anderen indogermanischen Zweigen ab. Unterschiede zwischen heutigen deutschen, englischen und lateinischen Wörtern haben daneben weitere lautliche, lexikalische und historische Ursachen.\n      </p>\n      <div class=\"era-grid\">\n        <div class=\"era-block era-block-full\">\n          <h4>Beispiele: Indogermanisch / Latein → Germanisch / Deutsch</h4>\n          <div class=\"laut-grid\">\n            <div class=\"laut-cell\">\n              <div class=\"laut-from\">p</div>\n              <div class=\"laut-arrow\">↓</div>\n              <div class=\"laut-to\">f / ff</div>\n              <div class=\"laut-ex\">lat. <em>pater</em> → dt. <em>Vater</em></div>\n            </div>\n            <div class=\"laut-cell\">\n              <div class=\"laut-from\">t</div>\n              <div class=\"laut-arrow\">↓</div>\n              <div class=\"laut-to\">ð / d</div>\n              <div class=\"laut-ex\">lat. <em>tres</em> → engl. <em>three</em></div>\n            </div>\n            <div class=\"laut-cell\">\n              <div class=\"laut-from\">k</div>\n              <div class=\"laut-arrow\">↓</div>\n              <div class=\"laut-to\">h / x</div>\n              <div class=\"laut-ex\">lat. <em>canis</em> → engl. <em>hound</em></div>\n            </div>\n            <div class=\"laut-cell\">\n              <div class=\"laut-from\">d</div>\n              <div class=\"laut-arrow\">↓</div>\n              <div class=\"laut-to\">t</div>\n              <div class=\"laut-ex\">lat. <em>decem</em> → engl. <em>ten</em></div>\n            </div>\n          </div>\n        </div>\n        <div class=\"era-block\">\n          <h4>Was bedeutet das für uns heute?</h4>\n          <ul>\n            <li>Englisch und Deutsch klingen ähnlich, weil beide westgermanisch sind</li>\n            <li>Deutsch und Latein haben oft gleiche Wortwurzeln — aber verschiedene Laute</li>\n            <li>Jacob Grimm (1785–1863) beschrieb das Gesetz 1822 — derselbe Grimm, der Märchen sammelte</li>\n            <li>Das Gesetz gilt als Geburtsstunde der modernen Sprachwissenschaft</li>\n          </ul>\n        </div>\n        <div class=\"era-block\">\n          <h4>Verwandtschaft: Deutsch ↔ Englisch ↔ Latein</h4>\n          <ul>\n            <li><em>Wasser</em> / <em>water</em> / lat. <em>aqua</em> — unterschiedliche Stämme</li>\n            <li><em>Fuß</em> / <em>foot</em> / lat. <em>pes/pedis</em> — alle verwandt</li>\n            <li><em>Herz</em> / <em>heart</em> / lat. <em>cor/cordis</em> — alle verwandt</li>\n            <li><em>Fisch</em> / <em>fish</em> / lat. <em>piscis</em> — p→f sichtbar</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- ─── ZWEITE LAUTVERSCHIEBUNG ─── -->\n  <div class=\"era-card lv-ahd\" id=\"era-2ls\">\n    <div class=\"era-card-header\" onclick=\"toggleEra('era-2ls')\">\n      <div class=\"era-year-block\">\n        <span class=\"era-abbr\" style=\"font-size:1.1rem;\">2. LS</span>\n        <span class=\"era-date\">ca. 500–800 n. Chr.</span>\n      </div>\n      <div>\n        <p class=\"era-title\">Die Zweite Lautverschiebung</p>\n        <p class=\"era-subtitle\">Hochdeutsch trennt sich von Niederländisch und Englisch</p>\n      </div>\n      <div class=\"era-toggle\">▾</div>\n    </div>\n    <div class=\"era-body\">\n      <p class=\"era-description lv-ahd\">\n        Die <strong>Zweite (Hochdeutsche) Lautverschiebung</strong> ist ein Bündel von Konsonantenveränderungen, das traditionell zwischen dem 5. und 8. Jahrhundert angesetzt wird. Ihre Ergebnisse unterscheiden hochdeutsche Dialekte von niederdeutschen und anderen westgermanischen Varietäten, allerdings geografisch gestaffelt und nicht überall gleich vollständig. Die <strong>Benrather Linie</strong> markiert mit dem Gegensatz <em>maken/machen</em> eine wichtige Isoglosse; sie ist nicht die Grenze jedes einzelnen Merkmals der Lautverschiebung.\n      </p>\n\n      <div class=\"fact-box\">\n        <strong>Die Benrather Linie</strong> ist eine isoglosse (Sprachgrenzlinie), die ungefähr durch Düsseldorf/Benrath verläuft. Nördlich: <em>ik make</em> (Niederdeutsch). Südlich: <em>ich mache</em> (Hochdeutsch). Diese Linie ist bis heute in deutschen Dialekten spürbar.\n      </div>\n\n      <div class=\"era-grid\">\n        <div class=\"era-block era-block-full\">\n          <h4>Die wichtigsten Lautveränderungen — mit Beispielen</h4>\n          <div class=\"laut-grid\">\n            <div class=\"laut-cell\">\n              <div class=\"laut-from\">p</div>\n              <div class=\"laut-arrow\">↓</div>\n              <div class=\"laut-to\">pf / ff</div>\n              <div class=\"laut-ex\">engl. <em>pepper</em> → dt. <em>Pfeffer</em><br>engl. <em>open</em> → dt. <em>offen</em></div>\n            </div>\n            <div class=\"laut-cell\">\n              <div class=\"laut-from\">t</div>\n              <div class=\"laut-arrow\">↓</div>\n              <div class=\"laut-to\">z / ss / ß</div>\n              <div class=\"laut-ex\">engl. <em>ten</em> → dt. <em>zehn</em><br>engl. <em>water</em> → dt. <em>Wasser</em></div>\n            </div>\n            <div class=\"laut-cell\">\n              <div class=\"laut-from\">d</div>\n              <div class=\"laut-arrow\">↓</div>\n              <div class=\"laut-to\">t</div>\n              <div class=\"laut-ex\">engl. <em>day</em> → dt. <em>Tag</em><br>engl. <em>door</em> → dt. <em>Tür</em></div>\n            </div>\n            <div class=\"laut-cell\">\n              <div class=\"laut-from\">k</div>\n              <div class=\"laut-arrow\">↓</div>\n              <div class=\"laut-to\">ch / ck</div>\n              <div class=\"laut-ex\">engl. <em>make</em> → dt. <em>machen</em><br>engl. <em>book</em> → dt. <em>Buch</em></div>\n            </div>\n          </div>\n        </div>\n        <div class=\"era-block\">\n          <h4>Warum fand die Verschiebung nur im Süden statt?</h4>\n          <ul>\n            <li>Die Ausbreitung wird in der Forschung mit verschiedenen phonologischen und sprachgeografischen Modellen erklärt</li>\n            <li>Beginn und Richtung der Ausbreitung werden traditionell im südlichen Sprachraum verortet</li>\n            <li>Kontakt- und Siedlungsgeschichte können regionale Entwicklungen beeinflusst haben</li>\n            <li>Eine einzelne, abschließend belegte Ursache gibt es nicht</li>\n          </ul>\n        </div>\n        <div class=\"era-block\">\n          <h4>Auswirkungen bis heute</h4>\n          <ul>\n            <li>Niederländisch und Englisch haben die Verschiebung <em>nicht</em> mitgemacht</li>\n            <li>„Hochdeutsch\" bedeutet ursprünglich „Sprache der Hochlande (Süden)\" — nicht „vornehm\"</li>\n            <li>Die heutigen deutschen Dialekte spiegeln noch immer diese historische Grenzlinie wider</li>\n            <li>Sie erklärt viele systematische Unterschiede wie <em>water/Wasser</em> oder <em>make/machen</em></li>\n          </ul>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- ─── ALTHOCHDEUTSCH ─── -->\n  <div class=\"era-card lv-ahd\" id=\"era-ahd\">\n    <div class=\"era-card-header\" onclick=\"toggleEra('era-ahd')\">\n      <div class=\"era-year-block\">\n        <span class=\"era-abbr\">Ahd.</span>\n        <span class=\"era-date\">ca. 750–1050</span>\n      </div>\n      <div>\n        <p class=\"era-title\">Althochdeutsch</p>\n        <p class=\"era-subtitle\">„Die ersten großen Texte\" — Deutsch im karolingischen Zeitalter</p>\n      </div>\n      <div class=\"era-toggle\">▾</div>\n    </div>\n    <div class=\"era-body\">\n      <p class=\"era-description lv-ahd\">\n        Als <strong>Althochdeutsch</strong> bezeichnet man die älteste Stufe des Deutschen, die in schriftlichen Quellen fassbar ist — grob zwischen 750 und 1050 n. Chr. Diese Periode entspricht dem Zeitalter Karls des Großen und der karolingischen Renaissance. Die Sprache war noch kein einheitliches System: Es gab eine Vielzahl regionaler Schreibtraditionen und Dialekte (Bairisch, Alemannisch, Fränkisch). Gemeinsam ist ihnen, dass sie die Auswirkungen der Zweiten Lautverschiebung zeigen und damit klar als „hochdeutsch\" erkennbar sind. Das meiste schriftliche Material stammt aus kirchlichen und klösterlichen Kontexten — Latein war weiterhin die dominante Schriftsprache.\n      </p>\n\n      <div class=\"notice\">\n        <strong>⚠️ Wichtiger Hinweis:</strong> Althochdeutsch ist für heutige Leser praktisch <em>unverständlich</em> — es ist kein „altes Deutsch mit seltsamer Rechtschreibung\", sondern eine eigenständige Sprachstufe, die sich in Grammatik, Wortschatz und Lautstand grundlegend vom heutigen Deutsch unterscheidet.\n      </div>\n\n      <div class=\"era-grid\">\n        <div class=\"era-block\">\n          <h4>Merkmale der Sprache</h4>\n          <ul>\n            <li>Reiches Kasussystem mit vier Fällen (wie heute) plus Instrumental</li>\n            <li>Sehr stark flektierende Sprache — viele Endungen und Formen</li>\n            <li>Kein einheitlicher Standard: regionale Dialekte bestimmen die Schrift</li>\n            <li>Starke Präsenz des Lateins als Bildungssprache neben dem Deutschen</li>\n            <li>Viele Lehnwörter aus dem Lateinischen und vereinzelt aus dem Griechischen</li>\n          </ul>\n        </div>\n        <div class=\"era-block\">\n          <h4>Wichtige Texte und Quellen</h4>\n          <ul>\n            <li><strong>Hildebrandslied</strong> (ca. 830) — ältestes Zeugnis weltlicher Heldendichtung in dt. Sprache</li>\n            <li><strong>Mersebur­ger Zaubersprüche</strong> (10. Jh.) — heidnische Spruchdichtung</li>\n            <li><strong>Tatian</strong> (ca. 830) — ahd. Übersetzung eines Evangelienharmoniums</li>\n            <li><strong>Notker von St. Gallen</strong> (gest. 1022) — bedeutender Übersetzer phil. Texte ins Althochdeutsche</li>\n            <li>Otfrids <strong>Evangelienbuch</strong> (ca. 863–871) — erstes bekanntes Reimgedicht auf Dt.</li>\n          </ul>\n        </div>\n        <div class=\"era-block era-block-full\">\n          <h4>Sprachvergleich: Althochdeutsch → Neuhochdeutsch</h4>\n          <div class=\"text-example lv-ahd\">\n            <div class=\"original\">„Ik gihorta dat seggen, dat sih urhettun ænon muotin, Hiltibrant enti Hadubrant untar heriun tuem.\"</div>\n            <div class=\"translation\">„Ich hörte das sagen, dass sich zwei Einzelkämpfer trafen, Hildebrand und Hadubrand, zwischen zwei Heeren.\"</div>\n            <div class=\"source\">HILDEBRANDSLIED · ca. 830 n. Chr. · Kloster Fulda</div>\n          </div>\n          <div class=\"text-example lv-ahd\">\n            <div class=\"original\">„In gotes namen faro ih, gotes geleit ih habe. Nu wil ih mih beuuergen, thaz mih nioman kiruoche.\"</div>\n            <div class=\"translation\">„In Gottes Namen fahre ich, Gottes Geleit habe ich. Nun will ich mich schützen, dass mich niemand angreife.\"</div>\n            <div class=\"source\">WEISSENBUR­GER KATECHISMUS · ca. 790 n. Chr.</div>\n          </div>\n        </div>\n        <div class=\"era-block\">\n          <h4>Historischer Kontext</h4>\n          <ul>\n            <li>Karl der Große (reg. 768–814) fördert Schriftlichkeit und Bildung</li>\n            <li>Klöster (Fulda, St. Gallen, Reichenau) sind Zentren der Schriftkultur</li>\n            <li>Missionierung germanischer Stämme verbreitet den Schriftgebrauch</li>\n            <li>Latein dominiert Verwaltung, Kirche, Wissenschaft</li>\n          </ul>\n        </div>\n        <div class=\"era-block\">\n          <h4>Merksatz für die Schule</h4>\n          <ul>\n            <li>Althochdeutsch ≠ modernes Deutsch — fast eine Fremdsprache für uns</li>\n            <li>Kein Standard, viele Dialekte, viel Latein daneben</li>\n            <li>Schreiben noch eine Seltenheit — gehörte zu Klerus und Gelehrten</li>\n            <li>Zweite Lautverschiebung ist bereits vollzogen und sichtbar</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- ─── MITTELHOCHDEUTSCH ─── -->\n  <div class=\"era-card lv-mhd\" id=\"era-mhd\">\n    <div class=\"era-card-header\" onclick=\"toggleEra('era-mhd')\">\n      <div class=\"era-year-block\">\n        <span class=\"era-abbr\">Mhd.</span>\n        <span class=\"era-date\">ca. 1050–1350</span>\n      </div>\n      <div>\n        <p class=\"era-title\">Mittelhochdeutsch</p>\n        <p class=\"era-subtitle\">„Ritter, Minnesang und Blütezeit der Literatur\"</p>\n      </div>\n      <div class=\"era-toggle\">▾</div>\n    </div>\n    <div class=\"era-body\">\n      <p class=\"era-description lv-mhd\">\n        Das <strong>Mittelhochdeutsche</strong> ist die Sprache der höfischen Ritterkultur und des Stauferzeitzeitalters (12./13. Jahrhundert). Es ist die erste Sprachstufe, bei der sich eine gewisse überregionale literarische Schreibtradition herausbildet — ausgelöst durch die Blüte der <em>höfischen Epik</em> und des <em>Minnesangs</em>. Der bekannteste Text der Epoche ist das Nibelungenlied. Im Vergleich zum Althochdeutschen hat das Mittelhochdeutsche bereits stärker reduzierte Endungen, die Sprache klingt dadurch etwas „leichter\". Dennoch: Ein einheitlicher Schriftstandard existiert noch immer nicht.\n      </p>\n      <div class=\"era-grid\">\n        <div class=\"era-block\">\n          <h4>Merkmale der Sprache</h4>\n          <ul>\n            <li>Abschwächung der vollen Endvokale zu Schwa (ə): <em>-a, -o, -u</em> → <em>-e</em></li>\n            <li>Beginn des Umlauts als grammatisches Mittel (Plural-Bildung)</li>\n            <li>Stärkere Annäherung der regionalen Schreibsprachen in der höfischen Literatur</li>\n            <li>Kein einheitlicher Standard — immer noch dialektbasiert</li>\n            <li>Viele Lehnwörter aus dem Altfranzösischen (Ritterkultur): <em>Turnier, Palast, Preis</em></li>\n          </ul>\n        </div>\n        <div class=\"era-block\">\n          <h4>Bedeutende Texte und Autoren</h4>\n          <ul>\n            <li><strong>Nibelungenlied</strong> (ca. 1200) — nationales Heldenepos, Siegfried und Brünhild</li>\n            <li><strong>Wolfram von Eschenbach</strong> — <em>Parzival</em> (ca. 1200–1210)</li>\n            <li><strong>Hartmann von Aue</strong> — <em>Erec</em>, <em>Iwein</em></li>\n            <li><strong>Walther von der Vogelweide</strong> (ca. 1170–1230) — bedeutendster Minnesänger</li>\n            <li><strong>Gottfried von Straßburg</strong> — <em>Tristan</em> (ca. 1210)</li>\n          </ul>\n        </div>\n        <div class=\"era-block era-block-full\">\n          <h4>Sprachbeispiele: Mittelhochdeutsch → Neuhochdeutsch</h4>\n          <div class=\"text-example lv-mhd\">\n            <div class=\"original\">„Uns ist in alten mæren wunders vil geseit von helden lobebæren, von grôzer arebeit…\"</div>\n            <div class=\"translation\">„Uns wird in alten Erzählungen Wunderbares viel berichtet von rühmlichen Helden, von großer Mühsal…\"</div>\n            <div class=\"source\">NIBELUNGENLIED · Erste Strophe · ca. 1200 n. Chr.</div>\n          </div>\n          <div class=\"text-example lv-mhd\">\n            <div class=\"original\">„Under der linden an der heide, dâ unser zweier bette was, dâ mugt ir vinden schône beide gebrochen bluomen unde gras.\"</div>\n            <div class=\"translation\">„Unter der Linde auf der Heide, wo unser beider Lager war, da könnt ihr schön beide finden: zerbrochene Blumen und Gras.\"</div>\n            <div class=\"source\">WALTHER VON DER VOGELWEIDE · Lied L.39,11 · ca. 1200</div>\n          </div>\n        </div>\n        <div class=\"era-block\">\n          <h4>Historischer Kontext</h4>\n          <ul>\n            <li>Staufische Kaiser (Friedrich I. Barbarossa, Friedrich II.) fördern Kultur und Literatur</li>\n            <li>Kreuzzüge bringen Kontakte mit arabischer, byzantinischer Kultur</li>\n            <li>Städtewachstum beginnt — Bürgertum entsteht</li>\n            <li>Pest (1347–1351) beendet die mittelhochdeutsche Blütezeit</li>\n          </ul>\n        </div>\n        <div class=\"era-block\">\n          <h4>Lehnwörter aus dem Altfranzösischen</h4>\n          <div class=\"feature-tags\">\n            <span class=\"feature-tag\">Turnier ← fr. tournoi</span>\n            <span class=\"feature-tag\">Palast ← fr. palais</span>\n            <span class=\"feature-tag\">Preis ← fr. prix</span>\n            <span class=\"feature-tag\">Abenteuer ← fr. aventure</span>\n            <span class=\"feature-tag\">Tanz ← fr. danse</span>\n            <span class=\"feature-tag\">Bastei ← fr. bastion</span>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- ─── FRÜHNEUHOCHDEUTSCH ─── -->\n  <div class=\"era-card lv-fnhd\" id=\"era-fnhd\">\n    <div class=\"era-card-header\" onclick=\"toggleEra('era-fnhd')\">\n      <div class=\"era-year-block\">\n        <span class=\"era-abbr\">Frnhd.</span>\n        <span class=\"era-date\">ca. 1350–1650</span>\n      </div>\n      <div>\n        <p class=\"era-title\">Frühneuhochdeutsch</p>\n        <p class=\"era-subtitle\">„Der Weg zur gemeinsamen Schriftsprache\" — Buchdruck und Luther</p>\n      </div>\n      <div class=\"era-toggle\">▾</div>\n    </div>\n    <div class=\"era-body\">\n      <p class=\"era-description lv-fnhd\">\n        Das <strong>Frühneuhochdeutsche</strong> ist eine entscheidende Übergangsphase in der Geschichte der deutschen Sprache. In dieser Zeit — grob zwischen 1350 und 1650 — gewinnen überregionale deutsche Schreibtraditionen an Reichweite. Treibende Kräfte sind das Wachstum der Städte, Handel und Verwaltung, die Entstehung von <strong>Kanzleisprachen</strong>, die Ausbreitung des Buchdrucks mit beweglichen Metalllettern in Europa — eng verbunden mit Johannes Gutenberg um 1450 — und Luthers Bibelübersetzung (Neues Testament 1522, Vollbibel 1534). Diese Entwicklungen schaffen wichtige Grundlagen für das heutige Standarddeutsch.\n      </p>\n\n      <div class=\"notice\">\n        <strong>⚠️ Häufiges Missverständnis über Luther:</strong> Martin Luther hat die deutsche Sprache <em>nicht erfunden</em> und auch nicht allein geschaffen. Er hat eine bereits vorhandene überregionale Schreibtradition aufgegriffen, gepflegt und durch die massenhafte Verbreitung seiner Texte — dank des Buchdrucks — enorm populär gemacht. Der Einfluss war real und bedeutend, aber er war Teil einer längeren Entwicklung, nicht deren Anfang.\n      </div>\n\n      <div class=\"era-grid\">\n        <div class=\"era-block\">\n          <h4>Die drei großen Kräfte dieser Epoche</h4>\n          <ul>\n            <li><strong>Kanzleisprachen:</strong> Verwaltungssprachen der Fürstentümer und Städte streben nach Überregionalität — besonders die <em>Kaiserliche Kanzlei</em> unter Maximilian I. und die <em>Sächsische Kanzlei</em> gelten als besonders einflussreich</li>\n            <li><strong>Buchdruck (ab Mitte des 15. Jh.):</strong> Gutenbergs Technik mit beweglichen Metalllettern beschleunigt die Textverbreitung in Europa und begünstigt überregionale Schreibkonventionen</li>\n            <li><strong>Luthers Übersetzung (1522/1534):</strong> Enorm weit verbreitet, von vielen Menschen gelesen — stabilisiert bestimmte Formen und Wendungen</li>\n          </ul>\n        </div>\n        <div class=\"era-block\">\n          <h4>Sprachliche Veränderungen</h4>\n          <ul>\n            <li>Entstehung der <em>neuhochdeutschen Diphthongierung</em>: mhd. <em>mîn</em> → nhd. <em>mein</em></li>\n            <li>Entstehung der <em>neuhochdeutschen Monophthongierung</em>: mhd. <em>guot</em> → nhd. <em>gut</em></li>\n            <li>Vereinheitlichung der Schreibweisen nimmt zu</li>\n            <li>Wortschatz expandiert durch Humanismus und Wissenschaft</li>\n            <li>Erste Grammatiken des Deutschen (Fabian Frangk, 1531)</li>\n          </ul>\n        </div>\n        <div class=\"era-block era-block-full\">\n          <h4>Sprachbeispiele: Frühneuhochdeutsch → Neuhochdeutsch</h4>\n          <div class=\"text-example lv-fnhd\">\n            <div class=\"original\">„Am anfang schuff Gott Himel und Erden. Und die Erde war wüst und leer, und es war finster auff der Tieffe…\"</div>\n            <div class=\"translation\">„Am Anfang schuf Gott Himmel und Erde. Und die Erde war wüst und leer, und es war finster auf der Tiefe…\" — bereits für heutige Leser gut verständlich!</div>\n            <div class=\"source\">MARTIN LUTHER · Bibelübersetzung (Genesis 1,1–2) · 1534</div>\n          </div>\n          <div class=\"text-example lv-fnhd\">\n            <div class=\"original\">„Ich hab die gemeyne Man auff dem marckt, die Mutter im haus, die Kinder auff der gassen angesehen und denselbigen auff das Maul geschaut…\"</div>\n            <div class=\"translation\">„Ich habe den gemeinen Mann auf dem Markt, die Mutter im Haus, die Kinder auf der Gasse angeschaut und denselben auf den Mund geschaut…\"</div>\n            <div class=\"source\">MARTIN LUTHER · Sendbrief vom Dolmetschen · 1530</div>\n          </div>\n        </div>\n        <div class=\"era-block\">\n          <h4>Luthers eigene Worte zum Übersetzen</h4>\n          <ul>\n            <li>Luther schrieb 1530: Er wolle „dem Volk aufs Maul schauen\" — also die Volkssprache nutzen</li>\n            <li>Er orientierte sich bewusst an der gesprochenen Sprache der einfachen Leute</li>\n            <li>Seine Bibelübersetzung prägte Hunderte von Wörtern und Phrasen, die wir heute noch kennen</li>\n            <li>Viele Wörter und Wendungen wurden durch Luthers Texte stark verbreitet; nicht alle ihm zugeschriebenen Ausdrücke hat er selbst neu gebildet</li>\n          </ul>\n        </div>\n        <div class=\"era-block\">\n          <h4>Historischer Kontext</h4>\n          <ul>\n            <li>Humanismus und Renaissance erreichen Deutschland</li>\n            <li>Reformation (ab 1517) — Religion als Massenthema, Sprache als Medium</li>\n            <li>Dreißigjähriger Krieg (1618–1648) — Einfluss von Fremdwörtern, besonders Französisch</li>\n            <li>Erste Sprachgesellschaften entstehen (Fruchtbringende Gesellschaft, 1617)</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- ─── NEUHOCHDEUTSCH ─── -->\n  <div class=\"era-card lv-nhd\" id=\"era-nhd\">\n    <div class=\"era-card-header\" onclick=\"toggleEra('era-nhd')\">\n      <div class=\"era-year-block\">\n        <span class=\"era-abbr\">Nhd.</span>\n        <span class=\"era-date\">ca. 1650–1900</span>\n      </div>\n      <div>\n        <p class=\"era-title\">Neuhochdeutsch</p>\n        <p class=\"era-subtitle\">„Standardisierung und Normierung\" — Grammatiken, Wörterbücher, Schulsprache</p>\n      </div>\n      <div class=\"era-toggle\">▾</div>\n    </div>\n    <div class=\"era-body\">\n      <p class=\"era-description lv-nhd\">\n        Ab ca. 1650 spricht man traditionell von <strong>Neuhochdeutsch</strong>. Texte aus der frühen Phase sind heutigen Leser*innen deutlich näher als mittel- oder althochdeutsche Texte, können aber in Wortschatz, Satzbau und Schreibweise weiterhin anspruchsvoll sein. Im 17. bis 19. Jahrhundert verdichten sich Prozesse der <strong>Standardisierung und Kodifizierung</strong>: Grammatiken, Wörterbücher, Schule, Verwaltung und Druckwesen fördern überregionale Normen. Eine staatlich vereinheitlichte Orthografie entsteht jedoch erst mit den Beschlüssen der Orthographischen Konferenz von 1901 und ihrer amtlichen Umsetzung ab 1902.\n      </p>\n      <div class=\"era-grid\">\n        <div class=\"era-block\">\n          <h4>Wichtige Meilensteine</h4>\n          <ul>\n            <li><strong>1663:</strong> Justus Georg Schottelius — <em>Ausführliche Arbeit von der teutschen HaubtSprache</em>, erste systematische Grammatik</li>\n            <li><strong>1748:</strong> Johann Christoph Gottsched — normative Grammatik des Hochdeutschen</li>\n            <li><strong>Spätes 18./frühes 19. Jh.:</strong> Goethe, Schiller und weitere Autor*innen prägen literarische Stile und den öffentlichen Sprachgebrauch</li>\n            <li><strong>1852–1961:</strong> Jacob und Wilhelm Grimm beginnen das <em>Deutsche Wörterbuch</em> — das größte historische Wörterbuch der deutschen Sprache (erst 1961 fertiggestellt)</li>\n            <li><strong>1880:</strong> Konrad Duden — <em>Vollständiges Orthographisches Wörterbuch der deutschen Sprache</em></li>\n            <li><strong>1901/1902:</strong> Orthographische Konferenz und amtliche Umsetzung vereinheitlichen die Rechtschreibung</li>\n          </ul>\n        </div>\n        <div class=\"era-block\">\n          <h4>Die Brüder Grimm — mehr als Märchen</h4>\n          <ul>\n            <li>Jacob Grimm (1785–1863) und Wilhelm Grimm (1786–1859) waren neben ihrer Sammeltätigkeit bedeutende Sprach- und Literaturwissenschaftler</li>\n            <li>Jacob Grimms <em>Deutsche Grammatik</em> (1819–1837) ist ein Grundlagenwerk der Germanistik</li>\n            <li>Das <em>Deutsche Wörterbuch</em> (DWB) dokumentiert erstmals historisch den deutschen Wortschatz</li>\n            <li>Ihre Märchensammlungen und sprachwissenschaftlichen Arbeiten gehören zu unterschiedlichen, miteinander verbundenen Teilen ihres Werks</li>\n            <li>Jacob Grimm beschrieb auch das Grimm'sche Gesetz (Erste Lautverschiebung)</li>\n          </ul>\n        </div>\n        <div class=\"era-block era-block-full\">\n          <h4>Sprachbeispiele: Neuhochdeutsch (17.–19. Jh.)</h4>\n          <div class=\"text-example lv-nhd\">\n            <div class=\"original\">„Zwei Seelen wohnen, ach! in meiner Brust, die eine will sich von der andern trennen; die eine hält, in derber Liebeslust, sich an die Welt mit klammernden Organen…\"</div>\n            <div class=\"translation\">Für heutige Leser problemlos verständlich — die Sprache ist im Wesentlichen modern.</div>\n            <div class=\"source\">JOHANN WOLFGANG VON GOETHE · Faust I, 1112–1115 · 1808</div>\n          </div>\n        </div>\n        <div class=\"era-block\">\n          <h4>Sprachpflege und Purismus</h4>\n          <ul>\n            <li>Im 17./18. Jh. starke Gegenbewegung zu Fremdwörtern (bes. Französisch)</li>\n            <li>Fruchtbringende Gesellschaft (1617) — erste dt. Sprachgesellschaft zur Sprachpflege</li>\n            <li>Joachim Heinrich Campe ersetzt Fremdwörter: <em>Zeitung</em> statt <em>Journal</em>, <em>Briefwechsel</em> statt <em>Korrespondenz</em></li>\n            <li>Viele dieser Ersatzwörter haben sich durchgesetzt und sind heute selbstverständlich</li>\n          </ul>\n        </div>\n        <div class=\"era-block\">\n          <h4>Neue Wörter durch Geschichte</h4>\n          <div class=\"feature-tags\">\n            <span class=\"feature-tag\">Demokratie (Griech.)</span>\n            <span class=\"feature-tag\">Lokomotive (Lat./Engl.)</span>\n            <span class=\"feature-tag\">Elektrizität (Griech.)</span>\n            <span class=\"feature-tag\">Nation (Lat.)</span>\n            <span class=\"feature-tag\">Revolution (Lat.)</span>\n            <span class=\"feature-tag\">Industrie (Lat.)</span>\n            <span class=\"feature-tag\">Zeitung (dt. Neuschöpfung)</span>\n            <span class=\"feature-tag\">Briefwechsel (dt. Neuschöpfung)</span>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- ─── MODERNE ─── -->\n  <div class=\"era-card lv-mod\" id=\"era-mod\">\n    <div class=\"era-card-header\" onclick=\"toggleEra('era-mod')\">\n      <div class=\"era-year-block\">\n        <span class=\"era-abbr\">Mod.</span>\n        <span class=\"era-date\">1900–heute</span>\n      </div>\n      <div>\n        <p class=\"era-title\">Modernes Deutsch</p>\n        <p class=\"era-subtitle\">„Normen, Wandel und Globalisierung\" — von der Rechtschreibreform bis zum Internet</p>\n      </div>\n      <div class=\"era-toggle\">▾</div>\n    </div>\n    <div class=\"era-body\">\n      <p class=\"era-description lv-mod\">\n        Das <strong>heutige Standarddeutsch</strong> ist das Ergebnis aller vorangegangenen Entwicklungen — geformt durch Jahrhunderte Lautwandel, Standardisierung und kulturellen Austausch. Es ist plurizentrisch: Deutschland, Österreich und die deutschsprachige Schweiz gelten als drei zentrale nationale Standardzentren; auch in Liechtenstein, Luxemburg, Ostbelgien und Südtirol gibt es standardsprachliche Variation. Wortschatz, Aussprache und teilweise Grammatik unterscheiden sich regional, ohne dass eine nationale Standardvarietät pauschal „richtiger“ wäre.\n      </p>\n      <div class=\"era-grid\">\n        <div class=\"era-block\">\n          <h4>Rechtschreibreform 1996</h4>\n          <ul>\n            <li>1996 von Deutschland, Österreich, der Schweiz, Liechtenstein und weiteren deutschsprachigen Staaten bzw. Gemeinschaften vereinbart</li>\n            <li>Vereinfachung der ss/ß-Regel: nach kurzem Vokal <em>ss</em>, nach langem <em>ß</em> (Straße, aber Fluss)</li>\n            <li>Getrennt-/Zusammenschreibung und Groß-/Kleinschreibung teilweise neu geregelt</li>\n            <li>Umstrittene Reform — viele Verlage, Redaktionen und Personen lehnten sie zunächst ab</li>\n            <li>Die amtliche Norm gilt in den beteiligten Staaten für Schule und Verwaltung; 2004 und 2006 wurden Regeln überarbeitet</li>\n            <li>Hüter der Norm: <strong>Rat für deutsche Rechtschreibung</strong> (gegründet 2004)</li>\n          </ul>\n        </div>\n        <div class=\"era-block\">\n          <h4>Deutsch als plurizentrische Sprache</h4>\n          <ul>\n            <li><strong>Deutsch in Deutschland:</strong> eigene nationale und regionale Standardvarianten</li>\n            <li><strong>Österreichisches Deutsch:</strong> eigenes Standardwörterbuch (ÖWB), viele österreichische Standardausdrücke (<em>Jänner</em> statt <em>Januar</em>, <em>heuer</em> statt <em>dieses Jahr</em>)</li>\n            <li><strong>Schweizer Standarddeutsch:</strong> kein ß (nur ss), eigene Ausdrücke (<em>Velo</em> statt <em>Fahrrad</em>), Einfluss des Französischen</li>\n            <li>Alle drei Varietäten gelten als gleichwertig korrekt</li>\n          </ul>\n        </div>\n        <div class=\"era-block\">\n          <h4>Neue Wörter im 20./21. Jahrhundert</h4>\n          <div class=\"feature-tags\">\n            <span class=\"feature-tag\">Handy (engl. Ursprung, dt. Bedeutung)</span>\n            <span class=\"feature-tag\">googeln (Verb vom Markennamen)</span>\n            <span class=\"feature-tag\">liken, posten, streamen</span>\n            <span class=\"feature-tag\">Homeoffice, Lockdown</span>\n            <span class=\"feature-tag\">Nachhaltigkeit (dt. Aufwertung)</span>\n            <span class=\"feature-tag\">Klimawandel (Neuprägun)</span>\n            <span class=\"feature-tag\">Gendern (neue Bedeutung)</span>\n            <span class=\"feature-tag\">Corona-Wortschatz: Impfgipfel, Inzidenz</span>\n          </div>\n        </div>\n        <div class=\"era-block\">\n          <h4>Aktuelle Themen und Debatten</h4>\n          <ul>\n            <li><strong>Gendern:</strong> Verwendung gendergerechter Sprache (Lehrer*innen, Lehrkräfte, das Lehrende) — gesellschaftlich intensiv diskutiert</li>\n            <li><strong>Anglizismen:</strong> Englische Lehnwörter fluten den Alltag — Einige werden integriert, andere verdrängen dt. Wörter</li>\n            <li><strong>Sprachverfall?</strong> Jugendsprache und Chatsprache werden oft als „Verfall\" wahrgenommen — Linguisten sehen es als natürlichen Wandel</li>\n            <li><strong>Einfache Sprache:</strong> Wachsendes Bewusstsein für barrierefreie Kommunikation</li>\n          </ul>\n        </div>\n        <div class=\"era-block era-block-full\">\n          <h4>Deutsch in Zahlen heute</h4>\n          <div class=\"laut-grid\" style=\"grid-template-columns: repeat(4,1fr);\">\n            <div class=\"laut-cell\">\n              <div class=\"laut-from\" style=\"color:var(--mod); font-size:1.5rem;\">~100 Mio.</div>\n              <div class=\"laut-ex\" style=\"margin-top:6px;\">Muttersprachler weltweit</div>\n            </div>\n            <div class=\"laut-cell\">\n              <div class=\"laut-from\" style=\"color:var(--mod); font-size:1.5rem;\">~80 Mio.</div>\n              <div class=\"laut-ex\" style=\"margin-top:6px;\">Lernende weltweit (DaF/DaZ)</div>\n            </div>\n            <div class=\"laut-cell\">\n              <div class=\"laut-from\" style=\"color:var(--mod); font-size:1.5rem;\">3</div>\n              <div class=\"laut-ex\" style=\"margin-top:6px;\">offizielle Standardvarietäten (DE/AT/CH)</div>\n            </div>\n            <div class=\"laut-cell\">\n              <div class=\"laut-from\" style=\"color:var(--mod); font-size:1.5rem;\">5,3 Mio.</div>\n              <div class=\"laut-ex\" style=\"margin-top:6px;\">Einträge im Deutschen Wörterbuch (DWB)</div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- ════════════════════ VERGLEICHSTABELLE ════════════════════ -->\n  <div class=\"section-header\"><h2>Sprachstufen im Vergleich</h2></div>\n\n  <p style=\"color:var(--muted); margin-bottom:20px; font-size:0.95rem; line-height:1.75;\">\n    So entwickelte sich dasselbe Wort über die Jahrhunderte — gut zu sehen: Wortschatz und Lautstand ändern sich, aber Kern-Wörter bleiben erkennbar verwandt.\n  </p>\n\n  <table class=\"compare-table\">\n    <thead>\n      <tr>\n        <th>Sprachstufe</th>\n        <th>„machen\"</th>\n        <th>„ich\"</th>\n        <th>„Tag\"</th>\n        <th>„gut\"</th>\n        <th>„Haus\"</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr>\n        <td style=\"color:var(--germ)\">Germanisch</td>\n        <td><em>*makōną</em></td>\n        <td><em>*ek</em></td>\n        <td><em>*dagaz</em></td>\n        <td><em>*gōdaz</em></td>\n        <td><em>*hūsą</em></td>\n      </tr>\n      <tr>\n        <td style=\"color:var(--ahd)\">Althochdeutsch</td>\n        <td><em>mahhōn</em></td>\n        <td><em>ih</em></td>\n        <td><em>tag</em></td>\n        <td><em>guot</em></td>\n        <td><em>hūs</em></td>\n      </tr>\n      <tr>\n        <td style=\"color:var(--mhd)\">Mittelhochdeutsch</td>\n        <td><em>machen</em></td>\n        <td><em>ich</em></td>\n        <td><em>tac</em></td>\n        <td><em>guot</em></td>\n        <td><em>hûs</em></td>\n      </tr>\n      <tr>\n        <td style=\"color:var(--fnhd)\">Frühneuhochdeutsch</td>\n        <td><em>machen</em></td>\n        <td><em>ich</em></td>\n        <td><em>Tag</em></td>\n        <td><em>gut</em></td>\n        <td><em>Haus</em></td>\n      </tr>\n      <tr>\n        <td style=\"color:var(--nhd)\">Neuhochdeutsch</td>\n        <td><strong>machen</strong></td>\n        <td><strong>ich</strong></td>\n        <td><strong>Tag</strong></td>\n        <td><strong>gut</strong></td>\n        <td><strong>Haus</strong></td>\n      </tr>\n      <tr>\n        <td>Englisch (Vgl.)</td>\n        <td><em>make</em></td>\n        <td><em>I</em></td>\n        <td><em>day</em></td>\n        <td><em>good</em></td>\n        <td><em>house</em></td>\n      </tr>\n      <tr>\n        <td>Niederländisch (Vgl.)</td>\n        <td><em>maken</em></td>\n        <td><em>ik</em></td>\n        <td><em>dag</em></td>\n        <td><em>goed</em></td>\n        <td><em>huis</em></td>\n      </tr>\n    </tbody>\n  </table>\n\n  <!-- ════════════════════ SCHLÜSSEL-TAKEAWAYS ════════════════════ -->\n  <div class=\"section-header\"><h2>Das Wichtigste im Überblick</h2></div>\n\n  <div class=\"keyfact-grid\">\n    <div class=\"keyfact-card\">\n      <div class=\"keyfact-icon\">🌱</div>\n      <div class=\"keyfact-title\">Deutsch ist schrittweise gewachsen</div>\n      <div class=\"keyfact-desc\">Die Sprache ist nicht plötzlich entstanden, sondern über viele Jahrhunderte in Stufen gewachsen — von indogermanischen Wurzeln über germanische Dialekte bis zur modernen Standardsprache.</div>\n    </div>\n    <div class=\"keyfact-card\">\n      <div class=\"keyfact-icon\">🔄</div>\n      <div class=\"keyfact-title\">Zwei Lautverschiebungen sind entscheidend</div>\n      <div class=\"keyfact-desc\">Die Erste Lautverschiebung (Grimmsches Gesetz) trennte Germanisch vom Rest der indogermanischen Familie. Die Zweite trennte Hochdeutsch von Englisch und Niederländisch.</div>\n    </div>\n    <div class=\"keyfact-card\">\n      <div class=\"keyfact-icon\">📜</div>\n      <div class=\"keyfact-title\">Luther hat Deutsch nicht erfunden</div>\n      <div class=\"keyfact-desc\">Luther hat eine bereits vorhandene überregionale Schreibtradition durch die Massenverbreitung seiner Bibelübersetzung enorm gestärkt — aber nicht aus dem Nichts erschaffen.</div>\n    </div>\n    <div class=\"keyfact-card\">\n      <div class=\"keyfact-icon\">🖨️</div>\n      <div class=\"keyfact-title\">Buchdruck als Turbo der Vereinheitlichung</div>\n      <div class=\"keyfact-desc\">Der europäische Buchdruck mit beweglichen Metalllettern verbreitete Texte schneller und begünstigte überregionale Schreibkonventionen — darunter die breite Rezeption von Luthers Texten.</div>\n    </div>\n    <div class=\"keyfact-card\">\n      <div class=\"keyfact-icon\">📖</div>\n      <div class=\"keyfact-title\">Normierung über mehrere Jahrhunderte</div>\n      <div class=\"keyfact-desc\">Grammatiken, Wörterbücher, Schule und Verwaltung förderten lange die Standardisierung. Konrad Dudens Wörterbuch erschien 1880; die amtliche Vereinheitlichung der Rechtschreibung folgte 1901/1902.</div>\n    </div>\n    <div class=\"keyfact-card\">\n      <div class=\"keyfact-icon\">🌍</div>\n      <div class=\"keyfact-title\">Deutsch lebt und verändert sich weiter</div>\n      <div class=\"keyfact-desc\">Wortschatz, Aussprache und Schreibnormen entwickeln sich weiter — durch Technologie, Globalisierung, Migration und gesellschaftlichen Wandel. Sprachverfall? Nein — Sprachwandel.</div>\n    </div>\n    <div class=\"keyfact-card\">\n      <div class=\"keyfact-icon\">🇦🇹</div>\n      <div class=\"keyfact-title\">Deutsch ist plurizentrisch</div>\n      <div class=\"keyfact-desc\">Deutschland, Österreich und die deutschsprachige Schweiz bilden drei zentrale Standardzentren; weitere deutschsprachige Regionen tragen ebenfalls zur standardsprachlichen Variation bei.</div>\n    </div>\n    <div class=\"keyfact-card\">\n      <div class=\"keyfact-icon\">🔗</div>\n      <div class=\"keyfact-title\">Verwandtschaft mit vielen Sprachen</div>\n      <div class=\"keyfact-desc\">Wer Deutsch kennt, erkennt Strukturen in Englisch, Niederländisch, Schwedisch und sogar in Griechisch oder Latein — denn alle teilen die gemeinsame indogermanische Wurzel.</div>\n    </div>\n  </div>\n\n</div>\n\n<!-- ════════════════════ FOOTER ════════════════════ -->\n<footer>\n  <p>Quellen und weiterführende Literatur: <a href=\"https://www.ids-mannheim.de\" target=\"_blank\" rel=\"noopener noreferrer\">Leibniz-Institut für Deutsche Sprache (IDS)</a> · <a href=\"https://grammis.ids-mannheim.de/korpusgrammatik/4742\" target=\"_blank\" rel=\"noopener noreferrer\">IDS: Was ist Standarddeutsch?</a> · <a href=\"https://www.rechtschreibrat.com/regeln-und-woerterverzeichnis/\" target=\"_blank\" rel=\"noopener noreferrer\">Rat für deutsche Rechtschreibung</a> · <a href=\"https://www.dwds.de\" target=\"_blank\" rel=\"noopener noreferrer\">DWDS</a></p>\n  <p style=\"margin-top:6px;\">Inhalt redaktionell geprüft: 12. August 2026 · Historische Datierungen sind Näherungswerte</p>\n  <p style=\"margin-top:6px;\">Peter von Polenz: <em>Deutsche Sprachgeschichte</em> (de Gruyter) · Wilhelm Schmidt: <em>Geschichte der deutschen Sprache</em> (Hirzel)</p>\n  <p style=\"margin-top:6px;\">Artikel erstellt 2025 · Redaktioneller Informationsartikel</p>\n  <p style=\"margin-top:6px;\"><a href=\"/impressum\">Impressum</a> · <a href=\"/privacy\">Datenschutz</a> · <a href=\"/contact\">Kontakt</a></p>\n</footer>\n\n<script>\n  function toggleEra(id) {\n    const card = document.getElementById(id);\n    card.classList.toggle('open');\n  }\n  // Open first card by default\n  document.getElementById('era-indg').classList.add('open');\n</script>\n\n",
    "styles": "\n  .dq-article-document {\n    --bg: #07111f;\n    --surface: rgba(15, 23, 42, 0.72);\n    --surface-strong: rgba(8, 15, 31, 0.88);\n    --surface-soft: rgba(15, 23, 42, 0.54);\n    --border: rgba(148, 163, 184, 0.18);\n    --text: #eaf2ff;\n    --muted: #a9b7c9;\n    --accent: #f3cf78;\n    --accent2: #8dd1e7;\n    --shadow: 0 24px 60px rgba(2, 6, 23, 0.28);\n\n    --indg:  #a07850;\n    --germ:  #7890b0;\n    --ahd:   #6878c0;\n    --mhd:   #5898a8;\n    --fnhd:  #58a870;\n    --nhd:   #c8a050;\n    --mod:   #c06860;\n\n    --indg-bg:  rgba(160,120,80,0.08);\n    --germ-bg:  rgba(120,144,176,0.08);\n    --ahd-bg:   rgba(104,120,192,0.08);\n    --mhd-bg:   rgba(88,152,168,0.08);\n    --fnhd-bg:  rgba(88,168,112,0.08);\n    --nhd-bg:   rgba(200,160,80,0.08);\n    --mod-bg:   rgba(192,104,96,0.08);\n  }\n\n  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n\n  .dq-article-document {\n    background:\n      radial-gradient(circle at top, rgba(243,207,120,0.12), transparent 28%),\n      radial-gradient(circle at 16% 24%, rgba(104,120,192,0.08), transparent 24%),\n      linear-gradient(180deg, #04101d 0%, var(--bg) 100%);\n    color: var(--text);\n    font-family: 'Source Sans 3', sans-serif;\n    font-weight: 400;\n    line-height: 1.78;\n    min-height: 100vh;\n  }\n\n  /* ── HERO ── */\n  .hero {\n    position: relative;\n    padding: 90px 24px 68px;\n    text-align: center;\n    overflow: hidden;\n  }\n  .hero::before {\n    content: '';\n    position: absolute;\n    inset: 0;\n    background:\n      radial-gradient(ellipse 80% 55% at 50% 0%, rgba(243,207,120,0.16) 0%, transparent 68%),\n      radial-gradient(ellipse 50% 40% at 15% 90%, rgba(104,120,192,0.10) 0%, transparent 60%),\n      radial-gradient(ellipse 40% 35% at 85% 70%, rgba(192,104,96,0.08) 0%, transparent 55%);\n    pointer-events: none;\n  }\n  .hero-eyebrow {\n    font-family: 'JetBrains Mono', monospace;\n    font-size: 11px;\n    letter-spacing: 0.24em;\n    text-transform: uppercase;\n    color: var(--accent);\n    margin-bottom: 18px;\n    opacity: 0;\n    animation: fadeUp 0.6s ease 0.1s forwards;\n  }\n  .hero h1 {\n    font-family: 'Playfair Display', serif;\n    font-size: clamp(2.4rem, 6vw, 4.8rem);\n    font-weight: 900;\n    line-height: 1.08;\n    margin-bottom: 22px;\n    opacity: 0;\n    animation: fadeUp 0.6s ease 0.25s forwards;\n  }\n  .hero h1 em { font-style: normal; color: var(--accent); }\n  .hero-sub {\n    max-width: 660px;\n    margin: 0 auto 44px;\n    color: var(--muted);\n    font-size: 1.08rem;\n    line-height: 1.82;\n    opacity: 0;\n    animation: fadeUp 0.6s ease 0.4s forwards;\n  }\n\n  /* ── ERA PILLS ── */\n  .era-strip {\n    display: flex;\n    justify-content: center;\n    flex-wrap: wrap;\n    gap: 7px;\n    margin-bottom: 10px;\n    opacity: 0;\n    animation: fadeUp 0.6s ease 0.55s forwards;\n  }\n  .era-pill {\n    font-family: 'JetBrains Mono', monospace;\n    font-size: 11px;\n    font-weight: 600;\n    padding: 4px 13px;\n    border-radius: 20px;\n    border: 1.5px solid currentColor;\n    white-space: nowrap;\n  }\n  .pill-indg  { color: var(--indg); }\n  .pill-germ  { color: var(--germ); }\n  .pill-ahd   { color: var(--ahd); }\n  .pill-mhd   { color: var(--mhd); }\n  .pill-fnhd  { color: var(--fnhd); }\n  .pill-nhd   { color: var(--nhd); }\n  .pill-mod   { color: var(--mod); }\n\n  .era-sublabel {\n    font-family: 'JetBrains Mono', monospace;\n    font-size: 10px;\n    letter-spacing: 0.16em;\n    color: var(--muted);\n    text-align: center;\n    margin-bottom: 38px;\n    opacity: 0;\n    animation: fadeUp 0.6s ease 0.65s forwards;\n  }\n\n  /* ── TIMELINE BAR ── */\n  .timeline-bar-wrap {\n    max-width: 880px;\n    margin: 0 auto;\n    padding: 28px 24px 0;\n    border: 1px solid var(--border);\n    border-radius: 18px;\n    background: rgba(8, 15, 31, 0.42);\n    box-shadow: var(--shadow);\n    opacity: 0;\n    animation: fadeUp 0.6s ease 0.75s forwards;\n  }\n  .timeline-bar {\n    display: flex;\n    height: 10px;\n    border-radius: 5px;\n    overflow: hidden;\n    margin-bottom: 10px;\n  }\n  .tb-seg { height: 100%; }\n  .tb-indg  { flex: 0.6; background: var(--indg); }\n  .tb-germ  { flex: 0.8; background: var(--germ); }\n  .tb-ahd   { flex: 1.2; background: var(--ahd); }\n  .tb-mhd   { flex: 1;   background: var(--mhd); }\n  .tb-fnhd  { flex: 1.2; background: var(--fnhd); }\n  .tb-nhd   { flex: 1.5; background: var(--nhd); }\n  .tb-mod   { flex: 2;   background: var(--mod); }\n  .timeline-labels {\n    display: flex;\n    justify-content: space-between;\n    font-family: 'JetBrains Mono', monospace;\n    font-size: 9px;\n    color: var(--muted);\n    gap: 2px;\n  }\n  .timeline-labels span { text-align: center; flex: 1; }\n\n  /* ── MAIN CONTAINER ── */\n  .container {\n    max-width: 880px;\n    margin: 0 auto;\n    padding: 0 24px 90px;\n  }\n\n  /* ── SECTION HEADER ── */\n  .section-header {\n    display: flex;\n    align-items: center;\n    gap: 16px;\n    margin: 62px 0 32px;\n  }\n  .section-header::after {\n    content: '';\n    flex: 1;\n    height: 1px;\n    background: var(--border);\n  }\n  .section-header h2 {\n    font-family: 'JetBrains Mono', monospace;\n    font-size: 11px;\n    letter-spacing: 0.2em;\n    text-transform: uppercase;\n    color: var(--muted);\n    white-space: nowrap;\n  }\n\n  /* ── ERA CARD ── */\n  .era-card {\n    background: linear-gradient(180deg, rgba(15, 23, 42, 0.7), rgba(8, 15, 31, 0.78));\n    border: 1px solid var(--border);\n    border-radius: 16px;\n    overflow: hidden;\n    margin-bottom: 28px;\n    box-shadow: var(--shadow);\n    backdrop-filter: blur(14px);\n    opacity: 0;\n    animation: fadeUp 0.5s ease forwards;\n    transition: border-color 0.25s;\n  }\n  .era-card:nth-child(1) { animation-delay: 0.05s; }\n  .era-card:nth-child(2) { animation-delay: 0.12s; }\n  .era-card:nth-child(3) { animation-delay: 0.19s; }\n  .era-card:nth-child(4) { animation-delay: 0.26s; }\n  .era-card:nth-child(5) { animation-delay: 0.33s; }\n  .era-card:nth-child(6) { animation-delay: 0.40s; }\n  .era-card:nth-child(7) { animation-delay: 0.47s; }\n\n  .era-card-header {\n    display: grid;\n    grid-template-columns: auto 1fr auto;\n    align-items: center;\n    gap: 20px;\n    padding: 26px 30px 22px;\n    cursor: pointer;\n    user-select: none;\n  }\n  .era-year-block {\n    text-align: center;\n    min-width: 72px;\n  }\n  .era-abbr {\n    font-family: 'Playfair Display', serif;\n    font-size: 1.6rem;\n    font-weight: 900;\n    line-height: 1;\n    display: block;\n    margin-bottom: 3px;\n  }\n  .era-date {\n    font-family: 'JetBrains Mono', monospace;\n    font-size: 9px;\n    color: var(--muted);\n    letter-spacing: 0.05em;\n    white-space: nowrap;\n  }\n  .era-title {\n    font-family: 'Playfair Display', serif;\n    font-size: 1.32rem;\n    font-weight: 700;\n    line-height: 1.2;\n    margin-bottom: 4px;\n  }\n  .era-subtitle { font-size: 0.86rem; color: var(--muted); }\n  .era-toggle {\n    font-size: 22px;\n    color: var(--muted);\n    transition: transform 0.3s;\n    line-height: 1;\n  }\n  .era-card.open .era-toggle { transform: rotate(180deg); }\n\n  .era-body {\n    padding: 0 30px;\n    max-height: 0;\n    overflow: hidden;\n    transition: max-height 0.5s ease, padding 0.3s ease;\n  }\n  .era-card.open .era-body {\n    max-height: 3500px;\n    padding-bottom: 30px;\n  }\n\n  /* ── DESCRIPTION ── */\n  .era-description {\n    font-size: 0.97rem;\n    color: var(--text);\n    margin-bottom: 24px;\n    line-height: 1.8;\n    padding: 16px 20px;\n    background: rgba(8, 15, 31, 0.78);\n    border-radius: 10px;\n    border: 1px solid var(--border);\n    border-left: 3px solid currentColor;\n  }\n\n  /* ── GRID ── */\n  .era-grid {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 20px;\n    margin-bottom: 20px;\n  }\n  @media (max-width: 640px) {\n    .era-grid { grid-template-columns: 1fr; }\n    .era-card-header { gap: 12px; padding: 20px 20px 18px; }\n    .era-body { padding: 0 20px; }\n    .era-card.open .era-body { padding-bottom: 20px; }\n  }\n\n  .era-block {\n    background: var(--surface-strong);\n    border: 1px solid var(--border);\n    border-radius: 10px;\n    padding: 18px 20px;\n  }\n  .era-block h4 {\n    font-family: 'JetBrains Mono', monospace;\n    font-size: 10px;\n    letter-spacing: 0.18em;\n    text-transform: uppercase;\n    color: #d7e2f1;\n    margin-bottom: 13px;\n  }\n  .era-block ul {\n    list-style: none;\n    display: flex;\n    flex-direction: column;\n    gap: 8px;\n  }\n  .era-block ul li {\n    font-size: 0.91rem;\n    padding-left: 20px;\n    position: relative;\n    color: var(--text);\n    line-height: 1.72;\n  }\n  .era-block ul li::before {\n    content: '→';\n    position: absolute;\n    left: 0;\n    font-size: 0.75rem;\n    top: 2px;\n  }\n  .era-block-full { grid-column: 1 / -1; }\n\n  /* ── TAGS ── */\n  .feature-tags {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 8px;\n  }\n  .feature-tag {\n    font-family: 'JetBrains Mono', monospace;\n    font-size: 11px;\n    padding: 4px 11px;\n    border-radius: 6px;\n    background: rgba(15, 23, 42, 0.84);\n    border: 1px solid var(--border);\n    color: #dde8f5;\n  }\n\n  /* ── TEXT EXAMPLES ── */\n  .text-example {\n    background: rgba(8, 15, 31, 0.82);\n    border: 1px solid var(--border);\n    border-left: 3px solid currentColor;\n    border-radius: 0 10px 10px 0;\n    padding: 14px 18px;\n    margin-bottom: 12px;\n  }\n  .text-example .original {\n    font-family: 'Playfair Display', serif;\n    font-style: italic;\n    font-size: 1rem;\n    color: var(--text);\n    margin-bottom: 6px;\n    line-height: 1.6;\n  }\n  .text-example .translation {\n    font-size: 0.82rem;\n    color: #cfdbeb;\n    line-height: 1.5;\n  }\n  .text-example .source {\n    font-family: 'JetBrains Mono', monospace;\n    font-size: 9px;\n    color: var(--muted);\n    letter-spacing: 0.1em;\n    margin-top: 6px;\n    opacity: 0.7;\n  }\n\n  /* ── ERA COLORS ── */\n  .lv-indg { color: var(--indg); border-color: rgba(160,120,80,0.22); }\n  .lv-germ { color: var(--germ); border-color: rgba(120,144,176,0.22); }\n  .lv-ahd  { color: var(--ahd);  border-color: rgba(104,120,192,0.22); }\n  .lv-mhd  { color: var(--mhd);  border-color: rgba(88,152,168,0.22); }\n  .lv-fnhd { color: var(--fnhd); border-color: rgba(88,168,112,0.22); }\n  .lv-nhd  { color: var(--nhd);  border-color: rgba(200,160,80,0.22); }\n  .lv-mod  { color: var(--mod);  border-color: rgba(192,104,96,0.22); }\n\n  .era-card.lv-indg:hover { border-color: var(--indg); }\n  .era-card.lv-germ:hover { border-color: var(--germ); }\n  .era-card.lv-ahd:hover  { border-color: var(--ahd); }\n  .era-card.lv-mhd:hover  { border-color: var(--mhd); }\n  .era-card.lv-fnhd:hover { border-color: var(--fnhd); }\n  .era-card.lv-nhd:hover  { border-color: var(--nhd); }\n  .era-card.lv-mod:hover  { border-color: var(--mod); }\n\n  .text-example.lv-ahd  { border-color: var(--ahd); }\n  .text-example.lv-mhd  { border-color: var(--mhd); }\n  .text-example.lv-fnhd { border-color: var(--fnhd); }\n  .text-example.lv-nhd  { border-color: var(--nhd); }\n  .text-example.lv-mod  { border-color: var(--mod); }\n\n  .era-description.lv-indg { border-color: var(--indg); }\n  .era-description.lv-germ { border-color: var(--germ); }\n  .era-description.lv-ahd  { border-color: var(--ahd); }\n  .era-description.lv-mhd  { border-color: var(--mhd); }\n  .era-description.lv-fnhd { border-color: var(--fnhd); }\n  .era-description.lv-nhd  { border-color: var(--nhd); }\n  .era-description.lv-mod  { border-color: var(--mod); }\n\n  /* ── NOTICE ── */\n  .notice {\n    background: rgba(243,207,120,0.1);\n    border: 1px solid rgba(243,207,120,0.22);\n    border-radius: 10px;\n    padding: 18px 22px;\n    font-size: 0.89rem;\n    color: #e7eef8;\n    margin-bottom: 26px;\n    line-height: 1.75;\n  }\n  .notice strong { color: var(--accent); }\n\n  /* ── FACT BOX ── */\n  .fact-box {\n    background: rgba(12, 32, 48, 0.7);\n    border: 1px solid rgba(141,209,231,0.22);\n    border-radius: 10px;\n    padding: 16px 20px;\n    margin-bottom: 20px;\n    font-size: 0.88rem;\n    color: #d5e3f2;\n    line-height: 1.7;\n  }\n  .fact-box strong { color: var(--accent2); }\n\n  /* ── COMPARISON TABLE ── */\n  .compare-table {\n    width: 100%;\n    border-collapse: separate;\n    border-spacing: 0;\n    margin-bottom: 28px;\n    font-size: 0.88rem;\n    border: 1px solid var(--border);\n    border-radius: 12px;\n    overflow: hidden;\n    background: rgba(8, 15, 31, 0.56);\n  }\n  .compare-table th {\n    font-family: 'JetBrains Mono', monospace;\n    font-size: 10px;\n    letter-spacing: 0.15em;\n    text-transform: uppercase;\n    color: #dbe7f5;\n    text-align: left;\n    padding: 12px 16px;\n    border-bottom: 1px solid var(--border);\n    background: rgba(15, 23, 42, 0.9);\n  }\n  .compare-table td {\n    padding: 12px 16px;\n    border-bottom: 1px solid var(--border);\n    vertical-align: top;\n    line-height: 1.65;\n    color: #d7e4f4;\n    background: rgba(8, 15, 31, 0.72);\n  }\n  .compare-table tr:last-child td { border-bottom: none; }\n  .compare-table tr:hover td { background: rgba(255,255,255,0.04); }\n  .compare-table td:first-child {\n    font-family: 'JetBrains Mono', monospace;\n    font-size: 11px;\n    color: var(--accent);\n    white-space: nowrap;\n  }\n\n  /* ── FAMILY TREE ── */\n  .family-grid {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    gap: 1px;\n    background: var(--border);\n    border: 1px solid var(--border);\n    border-radius: 12px;\n    overflow: hidden;\n    margin-bottom: 28px;\n  }\n  @media (max-width: 600px) { .family-grid { grid-template-columns: 1fr; } }\n  .fg-cell {\n    background: var(--surface-strong);\n    padding: 20px 18px;\n    text-align: center;\n  }\n  .fg-icon { font-size: 26px; margin-bottom: 8px; }\n  .fg-label {\n    font-family: 'JetBrains Mono', monospace;\n    font-size: 10px;\n    letter-spacing: 0.14em;\n    text-transform: uppercase;\n    color: var(--accent);\n    margin-bottom: 6px;\n  }\n  .fg-langs {\n    font-size: 0.84rem;\n    color: #d3dfef;\n    line-height: 1.68;\n  }\n\n  /* ── KEY FACTS GRID ── */\n  .keyfact-grid {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 16px;\n    margin-bottom: 28px;\n  }\n  @media (max-width: 600px) { .keyfact-grid { grid-template-columns: 1fr; } }\n  .keyfact-card {\n    background: var(--surface-strong);\n    border: 1px solid var(--border);\n    border-radius: 12px;\n    padding: 20px;\n    box-shadow: var(--shadow);\n  }\n  .keyfact-icon { font-size: 24px; margin-bottom: 10px; }\n  .keyfact-title {\n    font-weight: 600;\n    font-size: 0.96rem;\n    margin-bottom: 6px;\n  }\n  .keyfact-desc { font-size: 0.85rem; color: #cfdbeb; line-height: 1.72; }\n\n  /* ── FOOTER ── */\n  footer {\n    border-top: 1px solid var(--border);\n    padding: 36px 24px;\n    text-align: center;\n    color: var(--muted);\n    font-size: 0.83rem;\n    line-height: 1.8;\n  }\n  footer a { color: var(--accent); text-decoration: none; }\n  footer a:hover { text-decoration: underline; }\n\n  /* ── ANIMATIONS ── */\n  @keyframes fadeUp {\n    from { opacity: 0; transform: translateY(18px); }\n    to   { opacity: 1; transform: translateY(0); }\n  }\n\n  /* ── LAUTVS TABLE ── */\n  .laut-grid {\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 1px;\n    background: var(--border);\n    border: 1px solid var(--border);\n    border-radius: 12px;\n    overflow: hidden;\n    margin-bottom: 20px;\n  }\n  @media (max-width: 580px) { .laut-grid { grid-template-columns: 1fr 1fr; } }\n  .laut-cell {\n    background: var(--surface-strong);\n    padding: 14px 12px;\n    text-align: center;\n  }\n  .laut-from {\n    font-family: 'JetBrains Mono', monospace;\n    font-size: 15px;\n    font-weight: 600;\n    color: var(--germ);\n    margin-bottom: 4px;\n  }\n  .laut-arrow { font-size: 11px; color: var(--muted); margin-bottom: 4px; }\n  .laut-to {\n    font-family: 'JetBrains Mono', monospace;\n    font-size: 15px;\n    font-weight: 600;\n    color: var(--fnhd);\n  }\n  .laut-ex { font-size: 0.75rem; color: #cfdbeb; margin-top: 5px; line-height: 1.55; }\n"
  },
  "pruefungen-goethe-telc-testdaf": {
    "content": "\r\n\r\n<!-- ════════════════════ HERO ════════════════════ -->\r\n<header class=\"hero\">\r\n  <p class=\"hero-eyebrow\">Deutschprüfungen · Goethe · telc · ÖSD · TestDaF · DSH · DTZ</p>\r\n  <h1>Deutsche<br><em>Sprachprüfungen</em><br>A1 – C2</h1>\r\n  <p class=\"hero-sub\">Redaktionell geprüfte Orientierung zu Aufbau, Anerkennung und Vorbereitung — mit klarer Trennung der Prüfungsformate.</p>\r\n\r\n  <div class=\"provider-strip\">\r\n    <span class=\"prov-pill pill-goethe\">Goethe-Institut</span>\r\n    <span class=\"prov-pill pill-telc\">telc</span>\r\n    <span class=\"prov-pill pill-oesd\">ÖSD</span>\r\n    <span class=\"prov-pill pill-dtz\">DTZ</span>\r\n    <span class=\"prov-pill pill-testdaf\">TestDaF</span>\r\n    <span class=\"prov-pill pill-dsh\">DSH</span>\r\n  </div>\r\n  <p class=\"hero-sub2\" style=\"margin-top:10px;\">Niveau A1 · A2 · B1 · B2 · C1 · C2 nach GER/CEFR</p>\r\n</header>\n\n<!-- ════════════════════ KURZANTWORT ════════════════════ -->\n<section class=\"quick-answer\" aria-labelledby=\"pruefung-kurzantwort\">\n  <p class=\"quick-answer-label\">Kurzantwort</p>\n  <h2 id=\"pruefung-kurzantwort\">Welche Deutschprüfung brauche ich?</h2>\n  <p class=\"quick-answer-lead\">\n    Die richtige Prüfung hängt zuerst vom Zweck ab — nicht davon, welcher Anbieter bekannter ist. Für Familiennachzug oder Aufenthalt zählt die Liste der zuständigen Behörde, im Integrationskurs meist der DTZ, für ein deutschsprachiges Studium häufig TestDaF, DSH oder ein ausdrücklich akzeptiertes C1-Zertifikat. Für Ausbildung und Beruf gelten Arbeitgeber-, Kammer- oder Anerkennungsvorgaben. Prüfe deshalb immer Niveau, genaue Produktbezeichnung und akzeptierende Stelle, bevor du dich anmeldest.\n  </p>\n  <div class=\"decision-grid\" aria-label=\"Entscheidungshilfe nach Prüfungszweck\">\n    <article class=\"decision-card\">\n      <h3>Visum oder Aufenthalt</h3>\n      <p>Zuerst die Vorgabe der Auslandsvertretung oder Behörde prüfen; ein beliebiges Zertifikat desselben Niveaus ist nicht automatisch austauschbar.</p>\n    </article>\n    <article class=\"decision-card\">\n      <h3>Integrationskurs</h3>\n      <p>Am Kursende ist der Deutsch-Test für Zuwanderer (DTZ) das typische Format mit einem Ergebnis auf A2 oder B1.</p>\n    </article>\n    <article class=\"decision-card\">\n      <h3>Universität</h3>\n      <p>Häufig relevant sind TestDaF, eine registrierte DSH oder ein von der konkreten Hochschule akzeptierter C1-Nachweis.</p>\n    </article>\n    <article class=\"decision-card\">\n      <h3>Beruf oder Ausbildung</h3>\n      <p>Anforderung bei Arbeitgeber, Berufsschule, Kammer oder Anerkennungsstelle klären; reglementierte Berufe können Fachsprache verlangen.</p>\n    </article>\n  </div>\n  <div class=\"quick-answer-question\" id=\"goethe-oder-telc\">\n    <h3>Goethe oder telc – welche Prüfung passt besser?</h3>\n    <p>Wenn beide Zertifikate akzeptiert werden, vergleiche das exakte Prüfungsformat, verfügbare Termine, Wiederholungsregeln und die Aufgaben, mit denen du besser zurechtkommst. Die Anerkennung hat Vorrang vor persönlicher Präferenz.</p>\n  </div>\n  <a class=\"quick-answer-cta\" data-article-quiz-cta href=\"__ARTICLE_QUIZ_BOT_URL__\" target=\"_blank\" rel=\"noopener noreferrer\">Prüfungsvorbereitung im Quiz-Bot testen →</a>\n  <p class=\"quick-answer-note\">Der Quiz-Bot ersetzt keine verbindliche Auskunft der zuständigen Behörde, Hochschule oder Kammer.</p>\n</section>\n\n<!-- ════════════════════ 4 SKILLS BAR ════════════════════ -->\n<div class=\"container\" style=\"max-width:880px; padding-bottom:0;\">\r\n  <div class=\"skill-overview\">\r\n    <div class=\"skill-bar-row\">\r\n      <div class=\"skill-cell\">\r\n        <div class=\"skill-icon\">🎧</div>\r\n        <div class=\"skill-name s-listen\">Hören</div>\r\n        <div class=\"skill-desc\">Hörverstehen — gesprochene Texte, Dialoge, Nachrichten, Ansagen verstehen</div>\r\n      </div>\r\n      <div class=\"skill-cell\">\r\n        <div class=\"skill-icon\">📖</div>\r\n        <div class=\"skill-name s-read\">Lesen</div>\r\n        <div class=\"skill-desc\">Leseverstehen — Texte, Artikel, Formulare, E-Mails verstehen und auswerten</div>\r\n      </div>\r\n      <div class=\"skill-cell\">\r\n        <div class=\"skill-icon\">✍️</div>\r\n        <div class=\"skill-name s-write\">Schreiben</div>\r\n        <div class=\"skill-desc\">Schriftlicher Ausdruck — Briefe, E-Mails, Berichte, Stellungnahmen, Essays verfassen</div>\r\n      </div>\r\n      <div class=\"skill-cell\">\r\n        <div class=\"skill-icon\">🗣️</div>\r\n        <div class=\"skill-name s-speak\">Sprechen</div>\r\n        <div class=\"skill-desc\">Mündlicher Ausdruck — Monolog, Dialog, Diskussion, Präsentation, Reaktion</div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<!-- ════════════════════ PRÜFUNGSANBIETER ════════════════════ -->\r\n<div class=\"container\">\r\n\r\n  <div class=\"section-header\"><h2>Prüfungsanbieter im Detail</h2></div>\r\n\r\n  <!-- ─── GOETHE ─── -->\r\n  <div class=\"prov-card lv-goethe\" id=\"prov-goethe\">\r\n    <div class=\"prov-header\" onclick=\"toggleCard('prov-goethe')\">\r\n      <div class=\"prov-logo\">Goethe</div>\r\n      <div>\r\n        <p class=\"prov-title\">Goethe-Institut — Goethe-Zertifikat</p>\r\n        <p class=\"prov-subtitle\">A1–C2 · B1–C2 modular · Weltweites Prüfungsnetz</p>\r\n      </div>\r\n      <div class=\"prov-toggle\">▾</div>\r\n    </div>\r\n    <div class=\"prov-body\">\r\n      <p class=\"prov-description lv-goethe\">\r\n        Das Goethe-Institut bietet Deutschprüfungen für Erwachsene und Jugendliche auf allen GER-Niveaus von A1 bis C2 an. <strong>Modular sind die Goethe-Zertifikate B1, B2, C1 und C2:</strong> Die Module Lesen, Hören, Schreiben und Sprechen können einzeln oder in Kombination abgelegt und zertifiziert werden. A1 und A2 bestehen ebenfalls aus vier Fertigkeiten, werden bei den hier beschriebenen Erwachsenenprüfungen aber als Gesamtprüfung bewertet.\r\n      </p>\r\n\r\n      <div class=\"notice\"><strong>Anerkennung:</strong> Goethe-Zertifikate werden international als Sprachnachweis genutzt. Ob ein bestimmtes Zertifikat und Prüfungsdatum für Visum, Einbürgerung, Studium oder Beruf akzeptiert wird, entscheidet jedoch die zuständige Behörde, Hochschule oder Anerkennungsstelle.</div>\r\n\r\n      <!-- Niveau-Übersicht -->\r\n      <div class=\"p-block p-block-full\" style=\"margin-bottom:18px;\">\r\n        <h4>Prüfungsaufbau nach Niveau — Goethe-Zertifikat</h4>\r\n        <table class=\"level-table\">\r\n          <thead><tr>\r\n            <th>Niveau</th><th>Hören</th><th>Lesen</th><th>Schreiben</th><th>Sprechen</th><th>Gesamt</th>\r\n          </tr></thead>\r\n          <tbody>\r\n            <tr>\r\n              <td><strong style=\"color:var(--a1c)\">A1</strong></td>\r\n              <td>ca. 20 Min.</td><td>ca. 25 Min.</td><td>ca. 20 Min.</td><td>ca. 15 Min.</td>\r\n              <td>ca. 80 Min.</td>\r\n            </tr>\r\n            <tr>\r\n              <td><strong style=\"color:var(--a2c)\">A2</strong></td>\r\n              <td>ca. 30 Min.</td><td>ca. 30 Min.</td><td>ca. 30 Min.</td><td>ca. 15 Min.</td>\r\n              <td>ca. 105 Min.</td>\r\n            </tr>\r\n            <tr>\r\n              <td><strong style=\"color:var(--b1c)\">B1</strong></td>\r\n              <td>ca. 40 Min.</td><td>ca. 65 Min.</td><td>ca. 60 Min.</td><td>ca. 15 Min.</td>\r\n              <td>ca. 180 Min.</td>\r\n            </tr>\r\n            <tr>\r\n              <td><strong style=\"color:var(--b2c)\">B2</strong></td>\r\n              <td>ca. 40 Min.</td><td>ca. 65 Min.</td><td>ca. 75 Min.</td><td>ca. 15 Min.</td>\r\n              <td>ca. 195 Min.</td>\r\n            </tr>\r\n            <tr>\r\n              <td><strong style=\"color:var(--c1c)\">C1</strong></td>\r\n              <td>ca. 40 Min.</td><td>ca. 65 Min.</td><td>ca. 75 Min.</td><td>ca. 20 Min.</td>\r\n              <td>ca. 200 Min.</td>\r\n            </tr>\r\n            <tr>\r\n              <td><strong style=\"color:var(--c2c)\">C2</strong></td>\r\n              <td>ca. 35 Min.</td><td>ca. 80 Min.</td><td>ca. 80 Min.</td><td>ca. 15 Min.</td>\r\n              <td>ca. 210 Min.</td>\r\n            </tr>\r\n          </tbody>\r\n        </table>\r\n      </div>\r\n\r\n      <div class=\"prov-grid\">\r\n        <div class=\"p-block\">\r\n          <h4>Aufgabentypen — Lesen &amp; Hören</h4>\r\n          <ul>\r\n            <li>Zuordnungsaufgaben (Welche Aussage passt zu welchem Text?)</li>\r\n            <li>Multiple Choice (eine oder mehrere richtige Antworten)</li>\r\n            <li>Richtig / Falsch / Nicht im Text</li>\r\n            <li>Lückentexte (passendes Wort einsetzen)</li>\r\n            <li>Reihenfolge-Aufgaben (Aussagen in Reihenfolge bringen)</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"p-block\">\r\n          <h4>Aufgabentypen — Schreiben &amp; Sprechen</h4>\r\n          <ul>\r\n            <li>Schreiben: kurze Mitteilung, E-Mail oder Brief auf A1–B1</li>\r\n            <li>Schreiben: argumentierende und adressatengerechte Texte auf B2–C2</li>\r\n            <li>Sprechen A1/A2: Vorstellen, einfacher Dialog, Bildkarte</li>\r\n            <li>Sprechen B1+: Meinung äußern, Partner-Diskussion, Präsentation</li>\r\n            <li>Sprechen je nach Niveau als Gruppen-, Paar- oder Einzelprüfung</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"p-block\">\r\n          <h4>Bewertung &amp; Bestehen</h4>\r\n          <ul>\r\n            <li>B1–C2: Jedes Modul umfasst maximal 100 Punkte und ist ab 60 Punkten bestanden</li>\r\n            <li>B1–C2: Module können einzeln abgelegt und nicht bestandene Module wiederholt werden</li>\r\n            <li>A1 Start Deutsch 1: Gesamtprüfung mit 100 Punkten; bestanden ab 60 Punkten, wenn alle Teile abgelegt wurden</li>\r\n            <li>A2 Erwachsene: mindestens 60 Punkte insgesamt sowie mindestens 45 schriftlich und 15 mündlich</li>\r\n            <li>Jugendversionen können andere Bewertungsregeln haben; Durchführungsbestimmungen prüfen</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"p-block\">\r\n          <h4>Anmeldung &amp; Prüfungsablauf</h4>\r\n          <ul>\r\n            <li>Anmeldung beim lokalen Goethe-Institut oder autorisierten Prüfungszentrum</li>\r\n            <li>Gültiger Lichtbildausweis (Reisepass oder Personalausweis) erforderlich</li>\r\n            <li>Schriftliche und mündliche Teile können je nach Zentrum am selben oder an verschiedenen Tagen stattfinden</li>\r\n            <li>Termine, Ergebnisfristen und verfügbare digitale Formate beim Prüfungszentrum prüfen</li>\r\n            <li>Goethe-Zertifikate verfallen grundsätzlich nicht; anerkennende Stellen können aber einen aktuellen Nachweis verlangen</li>\r\n          </ul>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"warn-box\"><strong>Wichtig für A1:</strong> Das Goethe-Zertifikat A1: Start Deutsch 1 wird als Nachweis für das Visum zum Ehegattennachzug anerkannt. Es ist nicht der einzig mögliche Nachweis. Für Kinder und Jugendliche gibt es <em>Fit in Deutsch 1</em> mit eigener Prüfungs- und Bewertungsordnung.</div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- ─── TELC ─── -->\r\n  <div class=\"prov-card lv-telc\" id=\"prov-telc\">\r\n    <div class=\"prov-header\" onclick=\"toggleCard('prov-telc')\">\r\n      <div class=\"prov-logo\">telc</div>\r\n      <div>\r\n        <p class=\"prov-title\">telc — The European Language Certificates</p>\r\n        <p class=\"prov-subtitle\">A1–C2 · Allgemein- und berufssprachliche Formate</p>\r\n      </div>\r\n      <div class=\"prov-toggle\">▾</div>\r\n    </div>\r\n    <div class=\"prov-body\">\r\n      <p class=\"prov-description lv-telc\">\r\n        <strong>telc</strong> bietet Deutschprüfungen auf allen GER-Stufen von A1 bis C2 sowie Dual-Level- und berufsbezogene Formate an. Aufbau, Punkte, Teilprüfungsregeln und Anerkennung unterscheiden sich je nach Produkt. Allgemeinsprachliche Prüfungen bestehen typischerweise aus einem schriftlichen und einem mündlichen Teil; Sprachbausteine kommen in mehreren, aber nicht in allen telc-Formaten vor.\r\n      </p>\r\n\r\n      <div class=\"prov-grid\">\r\n        <div class=\"p-block\">\r\n          <h4>Aufbau telc Deutsch B1 (Beispiel)</h4>\r\n          <ul>\r\n            <li><strong>Schriftliche Prüfung (ca. 150 Min.):</strong></li>\r\n            <li>Lesen + Sprachbausteine: zusammen 90 Min.</li>\r\n            <li>Hören: ca. 30 Min.</li>\r\n            <li>Schreiben: 30 Min.</li>\r\n            <li><strong>Mündliche Prüfung (~15 Min.):</strong></li>\r\n            <li>Kontaktaufnahme, Gespräch über ein Thema, gemeinsame Planung</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"p-block\">\r\n          <h4>Besonderheit: Sprachbausteine</h4>\r\n          <ul>\r\n            <li>Viele klassische telc-Formate enthalten „Sprachbausteine\" als eigenen Subtest</li>\r\n            <li>Lückentexte, bei denen Grammatik und Wortschatz direkt getestet werden</li>\r\n            <li>Teil 1: offene Lücken (Wort selbst einsetzen)</li>\r\n            <li>Teil 2: Multiple Choice aus drei Optionen</li>\r\n            <li>Aufgabentyp und Gewichtung unterscheiden sich je nach telc-Prüfung</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"p-block\">\r\n          <h4>telc-Prüfungen — Übersicht Niveaus</h4>\r\n          <ul>\r\n            <li><strong style=\"color:var(--a1c)\">A1</strong> telc Deutsch A1</li>\r\n            <li><strong style=\"color:var(--a2c)\">A2</strong> telc Deutsch A2 / A2 Schule / A2+ Beruf</li>\r\n            <li><strong style=\"color:var(--b1c)\">B1</strong> telc Deutsch B1 / B1 Schule / B1·B2 Beruf</li>\r\n            <li><strong style=\"color:var(--b2c)\">B2</strong> telc Deutsch B2 / B2+ Beruf / B1·B2 Pflege / B2·C1 Medizin</li>\r\n            <li><strong style=\"color:var(--c1c)\">C1</strong> telc Deutsch C1 / C1 Hochschule / B2·C1 Medizin</li>\r\n            <li><strong style=\"color:var(--c2c)\">C2</strong> telc Deutsch C2</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"p-block\">\r\n          <h4>Bewertung &amp; Bestehen</h4>\r\n          <ul>\r\n            <li>Punkteskala und Gewichtung sind prüfungsspezifisch</li>\r\n            <li>Bei telc Deutsch B1 müssen schriftlicher und mündlicher Teil jeweils 60 % erreichen</li>\r\n            <li>Andere telc-Produkte können Teilprüfungen oder skalierte Ergebnisse vorsehen</li>\r\n            <li>Für die eigene Prüfung immer Übungstest und Prüfungsordnung derselben Produktbezeichnung verwenden</li>\r\n          </ul>\r\n        </div>\r\n      </div>\r\n      <div class=\"notice\"><strong>Berufsbezogene Prüfungen:</strong> telc bietet unter anderem Formate für Pflege, Medizin und Beruf an. Ein telc-Zertifikat ersetzt nicht automatisch eine behördliche Fachsprachprüfung; maßgeblich ist die Vorgabe der zuständigen Kammer oder Anerkennungsstelle.</div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- ─── ÖSD ─── -->\r\n  <div class=\"prov-card lv-oesd\" id=\"prov-oesd\">\r\n    <div class=\"prov-header\" onclick=\"toggleCard('prov-oesd')\">\r\n      <div class=\"prov-logo\">ÖSD</div>\r\n      <div>\r\n        <p class=\"prov-title\">ÖSD — Österreichisches Sprachdiplom Deutsch</p>\r\n        <p class=\"prov-subtitle\">A1–C2 · Je nach Prüfung zwei oder vier Module</p>\r\n      </div>\r\n      <div class=\"prov-toggle\">▾</div>\r\n    </div>\r\n    <div class=\"prov-body\">\r\n      <p class=\"prov-description lv-oesd\">\r\n        Das <strong>ÖSD</strong> bietet GER-orientierte Deutschprüfungen von A1 bis C2 an. Seit 2019 werden die regulären ÖSD-Prüfungen modular angeboten: Die meisten Formate haben zwei Module — schriftliche Prüfung und mündliche Prüfung. <strong>ÖSD Zertifikat B1 und ÖSD Zertifikat C2</strong> bestehen dagegen aus vier einzeln ablegbaren Modulen Lesen, Hören, Schreiben und Sprechen. Welche Prüfung für einen bestimmten Aufenthalts-, Studien- oder Berufszweck anerkannt wird, ist landes- und verfahrensabhängig.\r\n      </p>\r\n      <div class=\"prov-grid\">\r\n        <div class=\"p-block\">\r\n          <h4>Aufbau ÖSD B2 (Beispiel)</h4>\r\n          <ul>\r\n            <li><strong>Schriftliches Modul (~165 Min.):</strong></li>\r\n            <li>Leseverstehen: 3–4 Aufgaben, ca. 60 Min.</li>\r\n            <li>Hörverstehen: 3–4 Aufgaben, ca. 30 Min.</li>\r\n            <li>Schriftlicher Ausdruck: Stellungnahme oder Brief, ca. 75 Min.</li>\r\n            <li><strong>Mündliches Modul (~20 Min. pro Person):</strong></li>\r\n            <li>Monologischer Teil + Interaktion mit Partner</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"p-block\">\r\n          <h4>Besonderheiten ÖSD</h4>\r\n          <ul>\r\n            <li>Reguläre Prüfungen werden modular angeboten; je nach Prüfung gibt es zwei oder vier Module</li>\r\n            <li>B1 und C2: vier Module; die übrigen regulären Prüfungen: schriftliches und mündliches Modul</li>\r\n            <li>Texte und Hörmaterial berücksichtigen die plurizentrische Vielfalt des Deutschen</li>\r\n            <li>Anerkennung für österreichische Aufenthaltstitel hängt von Titel, Niveau und Prüfungsvariante ab</li>\r\n            <li>Auch spezifische Prüfungen für Jugendliche (KID = Kindersprachdiplom)</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"p-block\">\r\n          <h4>Niveaus und Bezeichnungen</h4>\r\n          <ul>\r\n            <li><strong style=\"color:var(--a1c)\">A1</strong> ÖSD Zertifikat A1</li>\r\n            <li><strong style=\"color:var(--a2c)\">A2</strong> ÖSD Zertifikat A2</li>\r\n            <li><strong style=\"color:var(--b1c)\">B1</strong> ÖSD Zertifikat B1</li>\r\n            <li><strong style=\"color:var(--b2c)\">B2</strong> ÖSD Zertifikat B2</li>\r\n            <li><strong style=\"color:var(--c1c)\">C1</strong> ÖSD Zertifikat C1</li>\r\n            <li><strong style=\"color:var(--c2c)\">C2</strong> ÖSD Zertifikat C2</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"p-block\">\r\n          <h4>Bewertung ÖSD</h4>\r\n          <ul>\r\n            <li>Bewertung und Punkteverteilung sind prüfungsspezifisch</li>\r\n            <li>Jedes Modul muss nach den Regeln der gewählten Prüfung bestanden werden</li>\r\n            <li>Bewertungskriterien für Schreiben und Sprechen stehen im jeweiligen Modellsatz</li>\r\n            <li>Für ein Gesamtzertifikat gelten Fristen und Kombinationsregeln der konkreten Prüfung</li>\r\n          </ul>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- ─── DTZ ─── -->\r\n  <div class=\"prov-card lv-dtz\" id=\"prov-dtz\">\r\n    <div class=\"prov-header\" onclick=\"toggleCard('prov-dtz')\">\r\n      <div class=\"prov-logo\">DTZ</div>\r\n      <div>\r\n        <p class=\"prov-title\">DTZ — Deutsch-Test für Zuwanderer</p>\r\n        <p class=\"prov-subtitle\">A2–B1 · BAMF-Integrationskurs · Aufenthaltsrecht</p>\r\n      </div>\r\n      <div class=\"prov-toggle\">▾</div>\r\n    </div>\r\n    <div class=\"prov-body\">\r\n      <p class=\"prov-description lv-dtz\">\r\n        Der <strong>DTZ</strong> (Deutsch-Test für Zuwanderer) ist die skalierte Sprachprüfung am Ende des Sprachkurses eines BAMF-Integrationskurses. Er weist im Gesamtergebnis <strong>A2 oder B1</strong> aus; unter A2 gibt es eine Ergebnismitteilung statt eines Zertifikats. Seit 2023 organisiert g.a.s.t. den DTZ im Auftrag des BAMF. Für das „Zertifikat Integrationskurs“ sind B1 im DTZ und ein bestandener Test „Leben in Deutschland“ erforderlich.\r\n      </p>\r\n\r\n      <div class=\"warn-box\"><strong>Aufenthaltsrechtliche Relevanz:</strong> B1 ist grundsätzlich eine Voraussetzung der allgemeinen Niederlassungserlaubnis nach § 9 AufenthG; je nach Rechtsgrundlage gelten jedoch Ausnahmen oder andere Niveaus. Das DTZ-Ergebnis allein entscheidet nicht über einen Aufenthaltstitel.</div>\r\n\r\n      <div class=\"prov-grid\">\r\n        <div class=\"p-block\">\r\n          <h4>Aufbau DTZ — Schriftliche Prüfung</h4>\r\n          <ul>\r\n            <li>Gesamtdauer schriftlich: ca. 100 Minuten</li>\r\n            <li><strong>Hören:</strong> 3 Teile, Alltagsdialoge und Ansagen, ca. 25 Min.</li>\r\n            <li><strong>Lesen:</strong> 3 Teile, Formulare, Nachrichten, kurze Texte, ca. 45 Min.</li>\r\n            <li><strong>Schreiben:</strong> 1 Aufgabe — formelle Nachricht (Termin, Anfrage, Problem), ca. 30 Min.</li>\r\n            <li>Hören und Lesen werden zusammengezählt (gemeinsame Punktgrenze)</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"p-block\">\r\n          <h4>Aufbau DTZ — Mündliche Prüfung</h4>\r\n          <ul>\r\n            <li>Dauer: ca. 15 Minuten pro Person</li>\r\n            <li>Teil 1: Vorstellen (Name, Herkunft, Beruf, Familie)</li>\r\n            <li>Teil 2: Über Erfahrungen sprechen, meist mit einem Bild als Impuls</li>\r\n            <li>Teil 3: Gemeinsam mit einer anderen Person etwas planen</li>\r\n            <li>Bewertet wird: Kommunikative Effizienz, nicht sprachliche Perfektion</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"p-block\">\r\n          <h4>Typische Themen im DTZ</h4>\r\n          <ul>\r\n            <li>Arbeit und Beruf (Bewerbung, Arbeitsvertrag, Kollegen)</li>\r\n            <li>Wohnen und Nachbarn (Mietvertrag, Hausordnung)</li>\r\n            <li>Gesundheit und Arztbesuche</li>\r\n            <li>Ämter und Behörden (Anträge, Formulare)</li>\r\n            <li>Schule und Kindergarten (für Kinder)</li>\r\n            <li>Öffentlicher Nahverkehr, Einkaufen</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"p-block\">\r\n          <h4>Bewertung &amp; Ergebnisse</h4>\r\n          <ul>\r\n            <li>Ergebnis: <strong>B1</strong> (höchstes), <strong>A2</strong>, oder <strong>unter A2</strong></li>\r\n            <li>Schreiben wird separat bewertet</li>\r\n            <li>Sprechen wird separat bewertet</li>\r\n            <li>Kein klassisches Notensystem — Einstufung nach Sprachniveau</li>\r\n            <li>Wiederholung möglich, wenn Ergebnis nicht ausreicht</li>\r\n          </ul>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- ─── TestDaF ─── -->\r\n  <div class=\"prov-card lv-testdaf\" id=\"prov-testdaf\">\r\n    <div class=\"prov-header\" onclick=\"toggleCard('prov-testdaf')\">\r\n      <div class=\"prov-logo\">TDaF</div>\r\n      <div>\r\n        <p class=\"prov-title\">TestDaF — Test Deutsch als Fremdsprache</p>\r\n        <p class=\"prov-subtitle\">B2–C1 · Hochschulzugang · TDN-Stufensystem</p>\r\n      </div>\r\n      <div class=\"prov-toggle\">▾</div>\r\n    </div>\r\n    <div class=\"prov-body\">\r\n      <p class=\"prov-description lv-testdaf\">\r\n        Der <strong>TestDaF</strong> ist eine Hochschulzugangsprüfung für internationale Studienbewerber*innen. Für jeden der vier Prüfungsteile wird getrennt TDN 3, TDN 4 oder TDN 5 ausgewiesen; ein Gesamtergebnis gibt es nicht. TDN 4 in allen vier Teilen gilt nach der Rahmenordnung als Nachweis für die uneingeschränkte Zulassung zu allen Studiengängen. Hochschulen dürfen für einzelne Studiengänge differenzierte Anforderungen festlegen. TestDaF wird papierbasiert und digital angeboten.\r\n      </p>\r\n\r\n      <div class=\"p-block p-block-full\" style=\"margin-bottom:18px;\">\r\n        <h4>Das TDN-Stufensystem — Bedeutung der Stufen</h4>\r\n        <table class=\"level-table\">\r\n          <thead><tr><th>TDN-Stufe</th><th>Ungefähres CEFR-Niveau</th><th>Bedeutung</th><th>Hochschule</th></tr></thead>\r\n          <tbody>\r\n            <tr>\r\n              <td><strong style=\"color:var(--b2c)\">TDN 3</strong></td>\r\n              <td>B2 (unteres)</td>\r\n              <td>Grundlegende Kompetenz für akademische Kommunikation</td>\r\n              <td>Meist nicht ausreichend — von manchen HS akzeptiert</td>\r\n            </tr>\r\n            <tr>\r\n              <td><strong style=\"color:var(--c1c)\">TDN 4</strong></td>\r\n              <td>B2+ / C1 (unteres)</td>\r\n              <td>Gute Kompetenz — akademisch arbeitsfähig</td>\r\n              <td>Standard-Anforderung der meisten deutschen Hochschulen</td>\r\n            </tr>\r\n            <tr>\r\n              <td><strong style=\"color:var(--c2c)\">TDN 5</strong></td>\r\n              <td>C1 (oberes)</td>\r\n              <td>Sehr hohe Kompetenz im jeweiligen Prüfungsteil</td>\r\n              <td>Liegt in diesem Teil über der regulären Zulassungsschwelle</td>\r\n            </tr>\r\n          </tbody>\r\n        </table>\r\n      </div>\r\n\r\n      <div class=\"prov-grid\">\r\n        <div class=\"p-block\">\r\n          <h4>Papierbasierter TestDaF — 4 Teile</h4>\r\n          <ul>\r\n            <li><strong>Leseverstehen:</strong> 3 Aufgaben, ca. 60 Min. — akademische Texte, Tabellen, Schaubilder</li>\r\n            <li><strong>Hörverstehen:</strong> 3 Aufgaben, ca. 40 Min. — Vorlesung, Interview, Gespräch</li>\r\n            <li><strong>Schriftlicher Ausdruck:</strong> 1 Aufgabe, ca. 60 Min. — Diagramm beschreiben + Stellungnahme</li>\r\n            <li><strong>Mündlicher Ausdruck:</strong> 7 Aufgaben, ca. 35 Min. — als Tonaufnahme, kein Prüfer anwesend</li>\r\n            <li>Gesamtdauer: ca. 3 Stunden 15 Minuten (ohne Pausen)</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"p-block\">\r\n          <h4>Besonderheit: Mündlicher Ausdruck ohne Prüfer</h4>\r\n          <ul>\r\n            <li>Der mündliche Teil wird <em>als Tonaufnahme</em> abgelegt — kein Gespräch mit Prüfer</li>\r\n            <li>7 Aufgaben zu akademischen Themen (Uni-Alltag, Graphiken, Diskussionen)</li>\r\n            <li>Vorbereitung: kurze Vorbereitungszeit pro Aufgabe (15–30 Sek.)</li>\r\n            <li>Sprechen: ca. 30–90 Sekunden pro Aufgabe</li>\r\n            <li>Bewertung durch geschulte Bewerter nach festen Kriterien</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"p-block\">\r\n          <h4>Typische akademische Themen</h4>\r\n          <div class=\"tags\" style=\"margin-top:0;\">\r\n            <span class=\"tag\">Studium und Hochschule</span>\r\n            <span class=\"tag\">Umwelt und Klimawandel</span>\r\n            <span class=\"tag\">Gesellschaft und Politik</span>\r\n            <span class=\"tag\">Wirtschaft und Globalisierung</span>\r\n            <span class=\"tag\">Medizin und Gesundheit</span>\r\n            <span class=\"tag\">Technik und Innovation</span>\r\n            <span class=\"tag\">Statistiken und Diagramme</span>\r\n            <span class=\"tag\">Demografischer Wandel</span>\r\n          </div>\r\n        </div>\r\n        <div class=\"p-block\">\r\n          <h4>Vorbereitung TestDaF</h4>\r\n          <ul>\r\n            <li>Akademischen Wortschatz systematisch aufbauen (Definitionen, Ursache-Wirkung)</li>\r\n            <li>Diagramme beschreiben trainieren (Anstieg, Rückgang, Plateau)</li>\r\n            <li>Schnelles Lesen — Kernaussagen in langen Texten identifizieren</li>\r\n            <li>Mündliche Aufnahmen üben: strukturiert, ohne Zögern sprechen</li>\r\n            <li>Offizielle Beispielaufgaben für genau das gebuchte Format auf testdaf.de üben</li>\r\n          </ul>\r\n        </div>\r\n      </div>\r\n      <div class=\"notice\"><strong>Digital oder Papier?</strong> Beide Versionen prüfen Lesen, Hören, Schreiben und Sprechen, verwenden aber unterschiedliche Aufgabenportfolios. Der digitale TestDaF wird seit 2020 am Computer durchgeführt und kombiniert teilweise mehrere Fertigkeiten. Bereite dich ausschließlich mit Material für das gebuchte Format vor.</div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- ─── DSH ─── -->\r\n  <div class=\"prov-card lv-dsh\" id=\"prov-dsh\">\r\n    <div class=\"prov-header\" onclick=\"toggleCard('prov-dsh')\">\r\n      <div class=\"prov-logo\">DSH</div>\r\n      <div>\r\n        <p class=\"prov-title\">DSH — Deutsche Sprachprüfung für den Hochschulzugang</p>\r\n        <p class=\"prov-subtitle\">DSH-1 bis DSH-3 · Hochschulprüfung · Registrierte Prüfungsordnungen</p>\r\n      </div>\r\n      <div class=\"prov-toggle\">▾</div>\r\n    </div>\r\n    <div class=\"prov-body\">\r\n      <p class=\"prov-description lv-dsh\">\r\n        Die <strong>DSH</strong> (Deutsche Sprachprüfung für den Hochschulzugang) wird von Hochschulen auf Grundlage einer registrierten Prüfungsordnung durchgeführt. Aufgaben und Termine sind örtlich organisiert, die Registrierung nach der Rahmenordnung sichert aber Vergleichbarkeit und gegenseitige Anerkennung. Das Ergebnis lautet <strong>DSH-1</strong>, <strong>DSH-2</strong> oder <strong>DSH-3</strong>; für die reguläre Zulassung wird meist DSH-2 verlangt.\r\n      </p>\r\n\r\n      <div class=\"p-block p-block-full\" style=\"margin-bottom:18px;\">\r\n        <h4>DSH-Stufen — Bedeutung und Anforderungen</h4>\r\n        <table class=\"level-table\">\r\n          <thead><tr><th>DSH-Stufe</th><th>Prozentuales Ergebnis</th><th>CEFR (ungefähr)</th><th>Studiumszulassung</th></tr></thead>\r\n          <tbody>\r\n            <tr>\r\n              <td><strong style=\"color:var(--b2c)\">DSH-1</strong></td>\r\n              <td>57 % – 66 %</td>\r\n              <td>ca. B2</td>\r\n              <td>Eingeschränkt — manche HS akzeptieren es mit Auflagen</td>\r\n            </tr>\r\n            <tr>\r\n              <td><strong style=\"color:var(--c1c)\">DSH-2</strong></td>\r\n              <td>67 % – 81 %</td>\r\n              <td>ca. C1</td>\r\n              <td>Reguläre Zulassung nach Rahmenordnung; Studiengangsvorgaben prüfen</td>\r\n            </tr>\r\n            <tr>\r\n              <td><strong style=\"color:var(--c2c)\">DSH-3</strong></td>\r\n              <td>82 % und mehr</td>\r\n              <td>ca. C1–C2</td>\r\n              <td>Höchste DSH-Stufe; besondere sprachliche Anforderungen abgedeckt</td>\r\n            </tr>\r\n          </tbody>\r\n        </table>\r\n      </div>\r\n\r\n      <div class=\"prov-grid\">\r\n        <div class=\"p-block\">\r\n          <h4>Schriftlicher Teil — typische Inhalte</h4>\r\n          <ul>\r\n            <li><strong>Hörverstehen:</strong> Vorlesung oder Vortrag (20–30 Min.), Notizen machen, dann Aufgaben lösen</li>\r\n            <li><strong>Leseverstehen:</strong> Wissenschaftlicher Text (800–1200 Wörter), Verstehens- und Transferaufgaben</li>\r\n            <li><strong>Wissenschaftliche Strukturen:</strong> Grammatik, Satzbau, Konnektoren in wissenschaftlichem Kontext</li>\r\n            <li><strong>Textproduktion:</strong> Zusammenfassung + argumentativer Text (~300–400 Wörter), ca. 60–70 Min.</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"p-block\">\r\n          <h4>Mündlicher Teil</h4>\r\n          <ul>\r\n            <li>Dauer: ca. 20–30 Minuten (je nach Hochschule)</li>\r\n            <li>Kurzpräsentation zu einem Thema (5–10 Min. Vorbereitung)</li>\r\n            <li>Fachgespräch auf Basis des Präsentationsthemas</li>\r\n            <li>Zusammensetzung der Prüfungskommission richtet sich nach der örtlichen Prüfungsordnung</li>\r\n            <li>Zur mündlichen Prüfung wird zugelassen, wer den schriftlichen Teil nach der örtlichen Ordnung bestanden hat</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"p-block\">\r\n          <h4>Wichtige Unterschiede zu TestDaF</h4>\r\n          <ul>\r\n            <li>DSH: Dezentral durchgeführt; registrierte DSH-Prüfungen werden von anderen Hochschulen anerkannt</li>\r\n            <li>TestDaF: Zentral entwickelt und von allen deutschen Hochschulen anerkannt</li>\r\n            <li>DSH: Zulassung zur Prüfung und Termine regelt die jeweilige Hochschule</li>\r\n            <li>DSH: Format und Schwierigkeit variieren je nach Hochschule</li>\r\n            <li>TestDaF: Einheitlich — gleicher Standard weltweit</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"p-block\">\r\n          <h4>Vorbereitung DSH</h4>\r\n          <ul>\r\n            <li>Wissenschaftssprache intensiv üben (Definitionen, Kausalität, Schlussfolgerungen)</li>\r\n            <li>Vorlesungen hören und Notizen strukturiert mitschreiben</li>\r\n            <li>Zusammenfassungen schreiben — sachlich, in eigenen Worten</li>\r\n            <li>Grammatik Niveau C1: Partizipialkonstruktionen, Passiv, Nominalisierungen</li>\r\n            <li>Probeprüfungen der Ziel-Hochschule herunterladen und üben</li>\r\n          </ul>\r\n        </div>\r\n      </div>\r\n      <div class=\"warn-box\"><strong>Anerkennung:</strong> Prüfe, ob die DSH-Prüfungsordnung registriert ist. Die Registrierung bestätigt die Übereinstimmung mit der Rahmenordnung und dient der gegenseitigen Anerkennung durch Hochschulen. Zusätzliche fach- oder studiengangsspezifische Anforderungen bleiben möglich.</div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- ════════════════════ PRÜFUNGSTAG ════════════════════ -->\r\n  <div class=\"section-header\"><h2>So läuft ein Prüfungstag ab</h2></div>\r\n\r\n  <p style=\"color:var(--muted); margin-bottom:24px; font-size:0.95rem; line-height:1.75;\">\r\n    Der genaue Ablauf hängt von Anbieter, Niveau, Format und Prüfungszentrum ab. Die folgenden Stationen sind eine typische Orientierung; verbindlich sind Einladung, Prüfungsordnung und Hinweise des Zentrums.\r\n  </p>\r\n\r\n  <div class=\"day-timeline\" style=\"max-width:640px;\">\r\n    <div class=\"dt-step\">\r\n      <div class=\"dt-left\"><div class=\"dt-dot\"></div><div class=\"dt-line\"></div></div>\r\n      <div class=\"dt-content\">\r\n        <div class=\"dt-time\">Schritt 1 · Anmeldung</div>\r\n        <div class=\"dt-title\">Einlass und Identitätsprüfung</div>\r\n        <div class=\"dt-desc\">Anmeldung am Empfang des Prüfungszentrums. Gültiger Reisepass oder Personalausweis vorzeigen (kein Führerschein bei manchen Anbietern). Sitzplatznummer in Empfang nehmen. Keine Handys, Smartwatches oder Notizen erlaubt — alles abgeben oder ausschalten.</div>\r\n      </div>\r\n    </div>\r\n    <div class=\"dt-step\">\r\n      <div class=\"dt-left\"><div class=\"dt-dot\"></div><div class=\"dt-line\"></div></div>\r\n      <div class=\"dt-content\">\r\n        <div class=\"dt-time\">Schritt 2 · Einweisung</div>\r\n        <div class=\"dt-title\">Regeln und Ablauf erklären</div>\r\n        <div class=\"dt-desc\">Die Prüfungsleitung erklärt die Regeln: Kein Sprechen, kein Wörterbuch, kein Handy. Aufgabenhefte werden ausgeteilt, aber noch nicht geöffnet. Ruhig bleiben — auch wenn andere Kandidaten nervös wirken.</div>\r\n      </div>\r\n    </div>\r\n    <div class=\"dt-step\">\r\n      <div class=\"dt-left\"><div class=\"dt-dot\"></div><div class=\"dt-line\"></div></div>\r\n      <div class=\"dt-content\">\r\n        <div class=\"dt-time\">Schritt 3 · Hören</div>\r\n        <div class=\"dt-title\">Hörverstehen (meistens zuerst)</div>\r\n        <div class=\"dt-desc\">Die Zahl der Hördurchgänge und die erlaubte Notizform hängen von der Prüfung und Aufgabe ab. Lies die Anweisung genau und trainiere vorher mit dem offiziellen Modellsatz deines Formats.</div>\r\n      </div>\r\n    </div>\r\n    <div class=\"dt-step\">\r\n      <div class=\"dt-left\"><div class=\"dt-dot\"></div><div class=\"dt-line\"></div></div>\r\n      <div class=\"dt-content\">\r\n        <div class=\"dt-time\">Schritt 4 · Lesen</div>\r\n        <div class=\"dt-title\">Leseverstehen</div>\r\n        <div class=\"dt-desc\">Texte lesen und Aufgaben lösen. Strategie: erst Fragen lesen, dann gezielt im Text suchen. Nicht zu viel Zeit bei einer Aufgabe verbringen — weitergehen und zurückkehren. Zeit ist knapp kalkuliert.</div>\r\n      </div>\r\n    </div>\r\n    <div class=\"dt-step\">\r\n      <div class=\"dt-left\"><div class=\"dt-dot\"></div><div class=\"dt-line\"></div></div>\r\n      <div class=\"dt-content\">\r\n        <div class=\"dt-time\">Schritt 5 · Schreiben</div>\r\n        <div class=\"dt-title\">Schriftlicher Ausdruck</div>\r\n        <div class=\"dt-desc\">Einen Text verfassen — Brief, E-Mail, Stellungnahme oder Essay je nach Niveau. Immer: Aufgabe sorgfältig lesen, Struktur planen (2–3 Min.), dann schreiben. Am Ende nochmals korrigieren (5 Min. einplanen). Handschrift muss lesbar sein.</div>\r\n      </div>\r\n    </div>\r\n    <div class=\"dt-step\">\r\n      <div class=\"dt-left\"><div class=\"dt-dot\"></div><div class=\"dt-line\"></div></div>\r\n      <div class=\"dt-content\">\r\n        <div class=\"dt-time\">Schritt 6 · Pause</div>\r\n        <div class=\"dt-title\">Kurze Pause (je nach Zentrum)</div>\r\n        <div class=\"dt-desc\">15–30 Minuten Pause zwischen schriftlichem und mündlichem Teil (oder zwischen Tagen). Wasser trinken, durchatmen. Nicht mit anderen Kandidaten über Aufgaben sprechen — das erzeugt zusätzliche Nervosität.</div>\r\n      </div>\r\n    </div>\r\n    <div class=\"dt-step\">\r\n      <div class=\"dt-left\"><div class=\"dt-dot\"></div><div class=\"dt-line\"></div></div>\r\n      <div class=\"dt-content\">\r\n        <div class=\"dt-time\">Schritt 7 · Sprechen</div>\r\n        <div class=\"dt-title\">Mündliche Prüfung</div>\r\n        <div class=\"dt-desc\">Meist als Paarprüfung (zwei Kandidaten + zwei Prüfer) oder Einzelprüfung. Kurze Vorbereitungszeit auf das Thema (~5 Min.). Dann: Monolog, Dialog, Diskussion — je nach Niveau. Ruhig und strukturiert sprechen. Fehler sind erlaubt — Kommunikation zählt.</div>\r\n      </div>\r\n    </div>\r\n    <div class=\"dt-step\">\r\n      <div class=\"dt-left\"><div class=\"dt-dot\" style=\"border-color:var(--accent2);\"></div></div>\r\n      <div class=\"dt-content\">\r\n        <div class=\"dt-time\" style=\"color:var(--accent2);\">Schritt 8 · Ergebnis</div>\r\n        <div class=\"dt-title\">Warten auf das Ergebnis</div>\r\n        <div class=\"dt-desc\">Ergebnisfristen und Ausgabeform unterscheiden sich nach Anbieter, Format und Prüfungszentrum. Beim TestDaF werden digitale Ergebnisse laut Anbieter meist schneller bereitgestellt als papierbasierte. Verbindlich ist die beim Termin veröffentlichte Frist.</div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- ════════════════════ PRÜFUNGSTAKTIK ════════════════════ -->\r\n  <div class=\"section-header\"><h2>Prüfungstaktik nach Fertigkeit</h2></div>\r\n\r\n  <div class=\"training-grid\">\r\n    <div class=\"tr-card s-listen\">\r\n      <div class=\"tr-icon\">🎧</div>\r\n      <div class=\"tr-title\">Hören — Strategie &amp; Training</div>\r\n      <div class=\"tr-body\">\r\n        <ul>\r\n          <li>Fragen <em>vor</em> dem Hören lesen — wissen, worauf man achten muss</li>\r\n          <li>Stichpunkte machen: Zahlen, Namen, Orte, Gründe, Daten</li>\r\n          <li>Beim zweiten Hören (wenn vorhanden) Lücken schließen und überprüfen</li>\r\n          <li>„Prüfungstempo\" trainieren — nicht nur langsame Podcasts hören</li>\r\n          <li>Bei unbekannten Wörtern: Kontext nutzen, nicht abbrechen</li>\r\n          <li>Typische Quellen: Deutsche Welle, Deutschlandfunk, ZDF Mediathek</li>\r\n        </ul>\r\n      </div>\r\n    </div>\r\n    <div class=\"tr-card s-read\">\r\n      <div class=\"tr-icon\">📖</div>\r\n      <div class=\"tr-title\">Lesen — Strategie &amp; Training</div>\r\n      <div class=\"tr-body\">\r\n        <ul>\r\n          <li>Zuerst Fragen lesen, dann gezielt im Text suchen (nicht alles gleich intensiv lesen)</li>\r\n          <li>Überschriften und erste Sätze jedes Absatzes für Struktur nutzen</li>\r\n          <li>Typische Aufgaben kennen: Richtig/Falsch, MC, Zuordnung, Lücken</li>\r\n          <li>Zeit einteilen: pro Aufgabe max. Zeit vorher schätzen, nicht hängen bleiben</li>\r\n          <li>Unbekannte Wörter aus Kontext erschließen — kein Wörterbuch</li>\r\n          <li>Zeitungen lesen: Zeit Online, Der Standard, Neue Zürcher Zeitung</li>\r\n        </ul>\r\n      </div>\r\n    </div>\r\n    <div class=\"tr-card s-write\">\r\n      <div class=\"tr-icon\">✍️</div>\r\n      <div class=\"tr-title\">Schreiben — Struktur &amp; Training</div>\r\n      <div class=\"tr-body\">\r\n        <ul>\r\n          <li><strong>A1–B1:</strong> Anrede → Zweck → 2–3 Infopunkte → Bitte/Frage → Gruß + Name</li>\r\n          <li><strong>B2–C2:</strong> Einleitung (These) → Hauptteil (Argumente, Beispiele) → Schluss</li>\r\n          <li>Immer: Aufgabe genau lesen — alle Punkte müssen behandelt werden</li>\r\n          <li>Konnektoren verwenden: <em>außerdem, allerdings, dennoch, einerseits…andererseits</em></li>\r\n          <li>Letzte 5 Minuten: Korrektur auf Rechtschreibung, Grammatik, Vollständigkeit</li>\r\n          <li>Schreibtraining: täglich 1 kurzen Text (E-Mail, Meinung, Zusammenfassung)</li>\r\n        </ul>\r\n      </div>\r\n    </div>\r\n    <div class=\"tr-card s-speak\">\r\n      <div class=\"tr-icon\">🗣️</div>\r\n      <div class=\"tr-title\">Sprechen — Technik &amp; Training</div>\r\n      <div class=\"tr-body\">\r\n        <ul>\r\n          <li>20–40 Redemittel auswendig lernen — diese ersetzen das Zögern</li>\r\n          <li>Zeitgefühl trainieren: 1 Min., 2 Min., 3 Min. sprechen (mit Stoppuhr)</li>\r\n          <li>Paarprüfung: aktiv reagieren — <em>„Da stimme ich zu…\", „Ich sehe das etwas anders…\"</em></li>\r\n          <li>Fehler nicht unterbrechen — weiter sprechen, am Ende korrigieren</li>\r\n          <li>Struktur: These → Begründung → Beispiel → Schluss (auch mündlich)</li>\r\n          <li>Laut sprechen üben — Handy aufnehmen und selbst zuhören</li>\r\n        </ul>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- ════════════════════ REDEMITTEL ════════════════════ -->\r\n  <div class=\"section-header\"><h2>Wichtige Redemittel für die mündliche Prüfung</h2></div>\r\n\r\n  <div class=\"redemittel-grid\">\r\n    <div class=\"rd-card\">\r\n      <div class=\"rd-title\">Meinung äußern</div>\r\n      <div class=\"rd-phrase\">„Ich bin der Meinung, dass …\"</div>\r\n      <div class=\"rd-phrase\">„Meiner Ansicht nach …\"</div>\r\n      <div class=\"rd-phrase\">„Ich finde / halte es für wichtig, dass …\"</div>\r\n      <div class=\"rd-phrase\">„Ich bin davon überzeugt, dass …\"</div>\r\n      <div class=\"rd-phrase\">„Aus meiner Sicht …\"</div>\r\n    </div>\r\n    <div class=\"rd-card\">\r\n      <div class=\"rd-title\">Zustimmen &amp; Widersprechen</div>\r\n      <div class=\"rd-phrase\">„Da stimme ich Ihnen / dir zu.\"</div>\r\n      <div class=\"rd-phrase\">„Das sehe ich genauso.\"</div>\r\n      <div class=\"rd-phrase\">„Da bin ich anderer Meinung.\"</div>\r\n      <div class=\"rd-phrase\">„Das stimmt zwar, aber …\"</div>\r\n      <div class=\"rd-phrase\">„Ich würde das etwas differenzierter sehen.\"</div>\r\n    </div>\r\n    <div class=\"rd-card\">\r\n      <div class=\"rd-title\">Begründen &amp; Argumentieren</div>\r\n      <div class=\"rd-phrase\">„Das liegt daran, dass …\"</div>\r\n      <div class=\"rd-phrase\">„Ein Grund dafür ist …\"</div>\r\n      <div class=\"rd-phrase\">„Außerdem / Darüber hinaus …\"</div>\r\n      <div class=\"rd-phrase\">„Einerseits … andererseits …\"</div>\r\n      <div class=\"rd-phrase\">„Zum Beispiel … / Ein Beispiel dafür ist …\"</div>\r\n    </div>\r\n    <div class=\"rd-card\">\r\n      <div class=\"rd-title\">Abschließen &amp; Zusammenfassen</div>\r\n      <div class=\"rd-phrase\">„Zusammenfassend lässt sich sagen, dass …\"</div>\r\n      <div class=\"rd-phrase\">„Alles in allem bin ich der Meinung …\"</div>\r\n      <div class=\"rd-phrase\">„Abschließend möchte ich betonen …\"</div>\r\n      <div class=\"rd-phrase\">„Das Wichtigste ist meiner Meinung nach …\"</div>\r\n      <div class=\"rd-phrase\">„Ich komme daher zu dem Schluss, dass …\"</div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- ════════════════════ GROSSE VERGLEICHSTABELLE ════════════════════ -->\r\n  <div class=\"section-header\"><h2>Alle Prüfungen im Vergleich</h2></div>\r\n\r\n  <table class=\"big-table\">\r\n    <thead>\r\n      <tr>\r\n        <th>Prüfung</th>\r\n        <th>Niveaus</th>\r\n        <th>Dauer gesamt</th>\r\n        <th>Besonderheit</th>\r\n        <th>Wofür anerkannt</th>\r\n      </tr>\r\n    </thead>\r\n    <tbody>\r\n      <tr>\r\n        <td><strong style=\"color:var(--goethe)\">Goethe-Zertifikat</strong></td>\r\n        <td>A1 – C2</td>\r\n        <td>80–210 Min. je nach Niveau</td>\r\n        <td>B1–C2 modular; A1/A2 als Gesamtprüfung</td>\r\n        <td>Je nach Niveau und Verfahren für Visum, Aufenthalt, Studium oder Beruf; Stelle vorab fragen</td>\r\n      </tr>\r\n      <tr>\r\n        <td><strong style=\"color:var(--telc)\">telc Deutsch</strong></td>\r\n        <td>A1–C2</td>\r\n        <td>Prüfungsspezifisch</td>\r\n        <td>Allgemein-, dual-level- und berufssprachliche Formate</td>\r\n        <td>Verfahrensabhängig; Produktbezeichnung und zuständige Stelle abgleichen</td>\r\n      </tr>\r\n      <tr>\r\n        <td><strong style=\"color:var(--oesd)\">ÖSD Zertifikat</strong></td>\r\n        <td>A1 – C2</td>\r\n        <td>100 – 185 Min. je nach Niveau</td>\r\n        <td>Modular; je nach Prüfung zwei oder vier Module; plurizentrischer Ansatz</td>\r\n        <td>Je nach Niveau und Prüfungsvariante für Aufenthalt oder Studium anerkannt</td>\r\n      </tr>\r\n      <tr>\r\n        <td><strong style=\"color:var(--dtz)\">DTZ</strong></td>\r\n        <td>A2 – B1</td>\r\n        <td>ca. 115 Min.</td>\r\n        <td>Nur im Rahmen des BAMF-Integrationskurses; Ergebnis: A2 oder B1</td>\r\n        <td>Teil des Integrationskurs-Abschlusses; B1 kann als Sprachnachweis in Verfahren dienen</td>\r\n      </tr>\r\n      <tr>\r\n        <td><strong style=\"color:var(--testdaf)\">TestDaF</strong></td>\r\n        <td>B2 – C1 (TDN 3–5)</td>\r\n        <td>ca. 3 Std. 15 Min.</td>\r\n        <td>Papier- und Digitalformat mit verschiedenen Aufgaben; Sprechen wird aufgenommen</td>\r\n        <td>Alle deutschen Hochschulen; TDN 4 in allen Teilen für uneingeschränkte Zulassung</td>\r\n      </tr>\r\n      <tr>\r\n        <td><strong style=\"color:var(--dsh)\">DSH</strong></td>\r\n        <td>DSH-1 bis DSH-3</td>\r\n        <td>ca. 3–4 Std. (schriftlich + mündlich)</td>\r\n        <td>Dezentral durchgeführt; Prüfungsordnung sollte registriert sein</td>\r\n        <td>Registrierte DSH wird hochschulübergreifend anerkannt; meist DSH-2 verlangt</td>\r\n      </tr>\r\n    </tbody>\r\n  </table>\r\n\r\n  <!-- ════════════════════ CHECKLISTE ════════════════════ -->\r\n  <div class=\"section-header\"><h2>Bin ich prüfungsbereit? — Checkliste</h2></div>\r\n\r\n  <div class=\"checklist-grid\">\r\n    <div class=\"cl-item\"><div class=\"cl-check\"></div><span>Ich kann Aufgaben im Lesen innerhalb der vorgesehenen Zeit lösen — nicht nur verstehen, sondern auch unter Zeitdruck arbeiten.</span></div>\r\n    <div class=\"cl-item\"><div class=\"cl-check\"></div><span>Ich kann beim Hören Hauptaussage und wichtige Details zuverlässig erfassen und in Stichworten notieren.</span></div>\r\n    <div class=\"cl-item\"><div class=\"cl-check\"></div><span>Ich kann die Textsorte meines Niveaus strukturiert und vollständig schreiben (Brief, E-Mail, Stellungnahme…).</span></div>\r\n    <div class=\"cl-item\"><div class=\"cl-check\"></div><span>Ich kann 2–3 Minuten fließend zu einem Thema sprechen und auf Fragen oder Kommentare reagieren.</span></div>\r\n    <div class=\"cl-item\"><div class=\"cl-check\"></div><span>Ich kenne den genauen Aufbau meiner Prüfung (Teile, Reihenfolge, Zeiten) — keine Überraschungen am Prüfungstag.</span></div>\r\n    <div class=\"cl-item\"><div class=\"cl-check\"></div><span>Ich habe mindestens 2–3 vollständige Probeprüfungen unter echten Bedingungen (Zeitdruck, ohne Hilfsmittel) absolviert.</span></div>\r\n    <div class=\"cl-item\"><div class=\"cl-check\"></div><span>Ich habe 20–30 Redemittel für das Sprechen automatisiert — sie kommen ohne Zögern.</span></div>\r\n    <div class=\"cl-item\"><div class=\"cl-check\"></div><span>Ich kenne die Bestehensregeln meiner Prüfung: welche Mindestpunktzahl pro Teil, was passiert bei Nicht-Bestehen.</span></div>\r\n  </div>\r\n\r\n</div>\r\n\r\n<!-- FOOTER -->\r\n<footer>\r\n  <p>Offizielle Quellen:\r\n    <a href=\"https://www.goethe.de/de/spr/prf.html\" target=\"_blank\" rel=\"noopener noreferrer\">Goethe-Institut Prüfungen</a> ·\r\n    <a href=\"https://www.telc.net/sprachpruefungen/zertifikatspruefung/deutsch/\" target=\"_blank\" rel=\"noopener noreferrer\">telc Deutsch-Prüfungen</a> ·\r\n    <a href=\"https://www.osd.at/die-pruefungen/osd-prufungen/\" target=\"_blank\" rel=\"noopener noreferrer\">ÖSD-Prüfungen</a> ·\r\n    <a href=\"https://www.testdaf.de/de/teilnehmende/\" target=\"_blank\" rel=\"noopener noreferrer\">TestDaF</a> ·\r\n    <a href=\"https://www.bamf.de/DE/Themen/Integration/ZugewanderteTeilnehmende/Integrationskurse/Abschlusspruefung/abschlusspruefung-node.html\" target=\"_blank\" rel=\"noopener noreferrer\">BAMF (DTZ)</a> ·\r\n    <a href=\"https://www.hrk.de/mitglieder/arbeitsmaterialien/registrierung-von-dsh-pruefungsordnungen/\" target=\"_blank\" rel=\"noopener noreferrer\">HRK (DSH)</a>\r\n  </p>\r\n  <p style=\"margin-top:6px;\">Inhalt redaktionell geprüft: 13. August 2026 · Formate und Anerkennungsregeln können sich ändern</p>\n  <p style=\"margin-top:6px;\"><a href=\"/impressum\">Impressum</a> · <a href=\"/privacy\">Datenschutz</a> · <a href=\"/contact\">Kontakt</a></p>\r\n</footer>\r\n\r\n<script>\r\n  function toggleCard(id) {\r\n    const card = document.getElementById(id);\r\n    card.classList.toggle('open');\r\n  }\r\n  document.getElementById('prov-goethe').classList.add('open');\r\n</script>\r\n\r\n",
    "styles": "\r\n  .dq-article-document {\r\n    --bg: #0f0f13;\r\n    --surface: #17171e;\r\n    --border: #2a2a38;\r\n    --text: #e8e6f0;\r\n    --muted: #8a8aa0;\r\n    --accent: #5eb8a0;\r\n    --accent2: #e0a04a;\r\n\r\n    --goethe: #5eb8a0;\r\n    --telc:   #6898d8;\r\n    --oesd:   #c87050;\r\n    --dtz:    #a870c8;\r\n    --testdaf:#58a8c0;\r\n    --dsh:    #d8784a;\r\n\r\n    --a1c:  #6ec6e0;\r\n    --a2c:  #4db8a8;\r\n    --b1c:  #7ec86e;\r\n    --b2c:  #c8b84e;\r\n    --c1c:  #e07848;\r\n    --c2c:  #d04870;\r\n\r\n    --skill-listen:  #6898d8;\r\n    --skill-read:    #58b890;\r\n    --skill-write:   #c8a050;\r\n    --skill-speak:   #d06878;\r\n  }\r\n\r\n  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\r\n\r\n  .dq-article-document {\r\n    background: var(--bg);\r\n    color: var(--text);\r\n    font-family: 'Source Sans 3', sans-serif;\r\n    font-weight: 300;\r\n    line-height: 1.78;\r\n    min-height: 100vh;\r\n  }\r\n\r\n  /* ── HERO ── */\r\n  .hero {\r\n    position: relative;\r\n    padding: 88px 24px 64px;\r\n    text-align: center;\r\n    overflow: hidden;\r\n  }\r\n  .hero::before {\r\n    content: '';\r\n    position: absolute;\r\n    inset: 0;\r\n    background:\r\n      radial-gradient(ellipse 75% 55% at 50% 0%, rgba(94,184,160,0.13) 0%, transparent 68%),\r\n      radial-gradient(ellipse 45% 38% at 85% 75%, rgba(104,152,216,0.09) 0%, transparent 58%),\r\n      radial-gradient(ellipse 40% 30% at 12% 85%, rgba(208,72,120,0.07) 0%, transparent 55%);\r\n    pointer-events: none;\r\n  }\r\n  .hero-eyebrow {\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 11px;\r\n    letter-spacing: 0.24em;\r\n    text-transform: uppercase;\r\n    color: var(--accent);\r\n    margin-bottom: 18px;\r\n    opacity: 0;\r\n    animation: fadeUp 0.6s ease 0.1s forwards;\r\n  }\r\n  .hero h1 {\r\n    font-family: 'Playfair Display', serif;\r\n    font-size: clamp(2.3rem, 5.5vw, 4.6rem);\r\n    font-weight: 900;\r\n    line-height: 1.08;\r\n    margin-bottom: 22px;\r\n    opacity: 0;\r\n    animation: fadeUp 0.6s ease 0.25s forwards;\r\n  }\r\n  .hero h1 em { font-style: normal; color: var(--accent); }\r\n  .hero-sub {\r\n    max-width: 660px;\r\n    margin: 0 auto 44px;\r\n    color: var(--muted);\r\n    font-size: 1.06rem;\r\n    opacity: 0;\r\n    animation: fadeUp 0.6s ease 0.4s forwards;\r\n  }\r\n\r\n  /* ── PROVIDER PILLS ── */\r\n  .provider-strip {\r\n    display: flex;\r\n    justify-content: center;\r\n    flex-wrap: wrap;\r\n    gap: 7px;\r\n    margin-bottom: 10px;\r\n    opacity: 0;\r\n    animation: fadeUp 0.6s ease 0.55s forwards;\r\n  }\r\n  .prov-pill {\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 11px;\r\n    font-weight: 600;\r\n    padding: 4px 13px;\r\n    border-radius: 20px;\r\n    border: 1.5px solid currentColor;\r\n  }\r\n  .pill-goethe  { color: var(--goethe); }\r\n  .pill-telc    { color: var(--telc); }\r\n  .pill-oesd    { color: var(--oesd); }\r\n  .pill-dtz     { color: var(--dtz); }\r\n  .pill-testdaf { color: var(--testdaf); }\r\n  .pill-dsh     { color: var(--dsh); }\r\n\r\n  .hero-sub2 {\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 10px;\r\n    letter-spacing: 0.16em;\r\n    color: var(--muted);\r\n    text-align: center;\r\n    margin-bottom: 0;\r\n    opacity: 0;\r\n    animation: fadeUp 0.6s ease 0.65s forwards;\r\n  }\r\n\r\n  /* ── 4-SKILL BAR ── */\r\n  .skill-overview {\r\n    max-width: 880px;\r\n    margin: 0 auto;\r\n    padding: 36px 24px 0;\r\n    opacity: 0;\r\n    animation: fadeUp 0.6s ease 0.75s forwards;\r\n  }\r\n  .skill-bar-row {\r\n    display: grid;\r\n    grid-template-columns: repeat(4, 1fr);\r\n    gap: 1px;\r\n    background: var(--border);\r\n    border: 1px solid var(--border);\r\n    border-radius: 14px;\r\n    overflow: hidden;\r\n    margin-bottom: 52px;\r\n  }\r\n  @media (max-width: 580px) { .skill-bar-row { grid-template-columns: 1fr 1fr; } }\r\n  .skill-cell {\r\n    background: var(--surface);\r\n    padding: 22px 16px;\r\n    text-align: center;\r\n  }\r\n  .skill-icon { font-size: 28px; margin-bottom: 8px; }\r\n  .skill-name {\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 10px;\r\n    letter-spacing: 0.15em;\r\n    text-transform: uppercase;\r\n    margin-bottom: 5px;\r\n  }\r\n  .skill-name.s-listen { color: var(--skill-listen); }\r\n  .skill-name.s-read   { color: var(--skill-read); }\r\n  .skill-name.s-write  { color: var(--skill-write); }\r\n  .skill-name.s-speak  { color: var(--skill-speak); }\r\n  .skill-desc { font-size: 0.82rem; color: var(--muted); line-height: 1.5; }\r\n\r\n  /* ── MAIN CONTAINER ── */\r\n  .container {\r\n    max-width: 900px;\r\n    margin: 0 auto;\r\n    padding: 0 24px 88px;\r\n  }\r\n\r\n  /* ── SECTION HEADER ── */\r\n  .section-header {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 16px;\r\n    margin: 60px 0 30px;\r\n  }\r\n  .section-header::after {\r\n    content: '';\r\n    flex: 1;\r\n    height: 1px;\r\n    background: var(--border);\r\n  }\r\n  .section-header h2 {\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 11px;\r\n    letter-spacing: 0.2em;\r\n    text-transform: uppercase;\r\n    color: var(--muted);\r\n    white-space: nowrap;\r\n  }\r\n\r\n  /* ── PROVIDER CARD ── */\r\n  .prov-card {\r\n    border: 1px solid var(--border);\r\n    border-radius: 16px;\r\n    overflow: hidden;\r\n    margin-bottom: 24px;\r\n    opacity: 0;\r\n    animation: fadeUp 0.5s ease forwards;\r\n    transition: border-color 0.25s;\r\n  }\r\n  .prov-card:nth-child(1) { animation-delay: 0.05s; }\r\n  .prov-card:nth-child(2) { animation-delay: 0.12s; }\r\n  .prov-card:nth-child(3) { animation-delay: 0.19s; }\r\n  .prov-card:nth-child(4) { animation-delay: 0.26s; }\r\n  .prov-card:nth-child(5) { animation-delay: 0.33s; }\r\n  .prov-card:nth-child(6) { animation-delay: 0.40s; }\r\n\r\n  .prov-header {\r\n    display: grid;\r\n    grid-template-columns: auto 1fr auto;\r\n    align-items: center;\r\n    gap: 20px;\r\n    padding: 24px 28px 20px;\r\n    cursor: pointer;\r\n    user-select: none;\r\n  }\r\n  .prov-logo {\r\n    font-family: 'Playfair Display', serif;\r\n    font-size: 1.5rem;\r\n    font-weight: 900;\r\n    width: 64px;\r\n    text-align: center;\r\n    line-height: 1;\r\n  }\r\n  .prov-title {\r\n    font-family: 'Playfair Display', serif;\r\n    font-size: 1.28rem;\r\n    font-weight: 700;\r\n    line-height: 1.2;\r\n    margin-bottom: 4px;\r\n  }\r\n  .prov-subtitle { font-size: 0.86rem; color: var(--muted); }\r\n  .prov-toggle {\r\n    font-size: 22px;\r\n    color: var(--muted);\r\n    transition: transform 0.3s;\r\n    line-height: 1;\r\n  }\r\n  .prov-card.open .prov-toggle { transform: rotate(180deg); }\r\n\r\n  .prov-body {\r\n    padding: 0 28px;\r\n    max-height: 0;\r\n    overflow: hidden;\r\n    transition: max-height 0.5s ease, padding 0.3s ease;\r\n  }\r\n  .prov-card.open .prov-body {\r\n    max-height: 4000px;\r\n    padding-bottom: 28px;\r\n  }\r\n\r\n  /* ── DESCRIPTION ── */\r\n  .prov-description {\r\n    font-size: 0.96rem;\r\n    color: var(--muted);\r\n    margin-bottom: 22px;\r\n    line-height: 1.82;\r\n    padding: 15px 18px;\r\n    background: rgba(255,255,255,0.025);\r\n    border-radius: 10px;\r\n    border-left: 3px solid currentColor;\r\n  }\r\n\r\n  /* ── GRID ── */\r\n  .prov-grid {\r\n    display: grid;\r\n    grid-template-columns: 1fr 1fr;\r\n    gap: 18px;\r\n    margin-bottom: 18px;\r\n  }\r\n  @media (max-width: 640px) {\r\n    .prov-grid { grid-template-columns: 1fr; }\r\n    .prov-header { gap: 12px; padding: 20px 20px 18px; }\r\n    .prov-body { padding: 0 20px; }\r\n    .prov-card.open .prov-body { padding-bottom: 20px; }\r\n  }\r\n\r\n  .p-block {\r\n    background: var(--surface);\r\n    border-radius: 10px;\r\n    padding: 16px 18px;\r\n  }\r\n  .p-block h4 {\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 10px;\r\n    letter-spacing: 0.18em;\r\n    text-transform: uppercase;\r\n    color: var(--muted);\r\n    margin-bottom: 12px;\r\n  }\r\n  .p-block ul {\r\n    list-style: none;\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 7px;\r\n  }\r\n  .p-block ul li {\r\n    font-size: 0.9rem;\r\n    padding-left: 18px;\r\n    position: relative;\r\n    color: var(--text);\r\n    line-height: 1.6;\r\n  }\r\n  .p-block ul li::before {\r\n    content: '→';\r\n    position: absolute;\r\n    left: 0;\r\n    font-size: 0.75rem;\r\n    top: 2px;\r\n  }\r\n  .p-block-full { grid-column: 1 / -1; }\r\n\r\n  /* ── LEVEL TABLE ── */\r\n  .level-table {\r\n    width: 100%;\r\n    border-collapse: collapse;\r\n    font-size: 0.86rem;\r\n  }\r\n  .level-table th {\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 9.5px;\r\n    letter-spacing: 0.14em;\r\n    text-transform: uppercase;\r\n    color: var(--muted);\r\n    text-align: left;\r\n    padding: 10px 12px;\r\n    border-bottom: 1px solid var(--border);\r\n    background: rgba(255,255,255,0.02);\r\n  }\r\n  .level-table td {\r\n    padding: 10px 12px;\r\n    border-bottom: 1px solid var(--border);\r\n    vertical-align: top;\r\n    line-height: 1.5;\r\n  }\r\n  .level-table tr:last-child td { border-bottom: none; }\r\n  .level-table tr:hover td { background: rgba(255,255,255,0.02); }\r\n\r\n  /* ── EXAM STRUCTURE BOX ── */\r\n  .exam-structure {\r\n    background: var(--surface);\r\n    border-radius: 12px;\r\n    overflow: hidden;\r\n    margin-bottom: 18px;\r\n  }\r\n  .exam-structure-title {\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 10px;\r\n    letter-spacing: 0.18em;\r\n    text-transform: uppercase;\r\n    color: var(--muted);\r\n    padding: 12px 18px 10px;\r\n    border-bottom: 1px solid var(--border);\r\n  }\r\n  .exam-parts {\r\n    display: grid;\r\n    grid-template-columns: repeat(4, 1fr);\r\n    gap: 1px;\r\n    background: var(--border);\r\n  }\r\n  @media (max-width: 560px) { .exam-parts { grid-template-columns: 1fr 1fr; } }\r\n  .exam-part {\r\n    background: var(--surface);\r\n    padding: 14px 12px;\r\n    text-align: center;\r\n  }\r\n  .ep-name {\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 10px;\r\n    letter-spacing: 0.12em;\r\n    text-transform: uppercase;\r\n    margin-bottom: 5px;\r\n  }\r\n  .ep-time {\r\n    font-size: 1.15rem;\r\n    font-family: 'Playfair Display', serif;\r\n    font-weight: 700;\r\n    margin-bottom: 3px;\r\n  }\r\n  .ep-detail { font-size: 0.76rem; color: var(--muted); line-height: 1.45; }\r\n\r\n  /* ── TAGS ── */\r\n  .tags {\r\n    display: flex;\r\n    flex-wrap: wrap;\r\n    gap: 7px;\r\n  }\r\n  .tag {\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 11px;\r\n    padding: 3px 10px;\r\n    border-radius: 6px;\r\n    background: rgba(255,255,255,0.05);\r\n    border: 1px solid var(--border);\r\n    color: var(--muted);\r\n  }\r\n\r\n  /* ── NOTICE / FACT ── */\r\n  .notice {\r\n    background: rgba(94,184,160,0.07);\r\n    border: 1px solid rgba(94,184,160,0.2);\r\n    border-radius: 10px;\r\n    padding: 15px 20px;\r\n    font-size: 0.88rem;\r\n    color: var(--muted);\r\n    margin-bottom: 18px;\r\n    line-height: 1.72;\r\n  }\r\n  .notice strong { color: var(--accent); }\r\n\r\n  .warn-box {\r\n    background: rgba(224,160,74,0.07);\r\n    border: 1px solid rgba(224,160,74,0.2);\r\n    border-radius: 10px;\r\n    padding: 15px 20px;\r\n    font-size: 0.88rem;\r\n    color: var(--muted);\r\n    margin-bottom: 18px;\r\n    line-height: 1.72;\r\n  }\r\n  .warn-box strong { color: var(--accent2); }\r\n\r\n  /* ── PROVIDER COLORS ── */\r\n  .lv-goethe  { color: var(--goethe); border-color: rgba(94,184,160,0.22); }\r\n  .lv-telc    { color: var(--telc);   border-color: rgba(104,152,216,0.22); }\r\n  .lv-oesd    { color: var(--oesd);   border-color: rgba(200,112,80,0.22); }\r\n  .lv-dtz     { color: var(--dtz);    border-color: rgba(168,112,200,0.22); }\r\n  .lv-testdaf { color: var(--testdaf);border-color: rgba(88,168,192,0.22); }\r\n  .lv-dsh     { color: var(--dsh);    border-color: rgba(216,120,74,0.22); }\r\n\r\n  .prov-card.lv-goethe:hover  { border-color: var(--goethe); }\r\n  .prov-card.lv-telc:hover    { border-color: var(--telc); }\r\n  .prov-card.lv-oesd:hover    { border-color: var(--oesd); }\r\n  .prov-card.lv-dtz:hover     { border-color: var(--dtz); }\r\n  .prov-card.lv-testdaf:hover { border-color: var(--testdaf); }\r\n  .prov-card.lv-dsh:hover     { border-color: var(--dsh); }\r\n\r\n  .prov-description.lv-goethe  { border-color: var(--goethe); }\r\n  .prov-description.lv-telc    { border-color: var(--telc); }\r\n  .prov-description.lv-oesd    { border-color: var(--oesd); }\r\n  .prov-description.lv-dtz     { border-color: var(--dtz); }\r\n  .prov-description.lv-testdaf { border-color: var(--testdaf); }\r\n  .prov-description.lv-dsh     { border-color: var(--dsh); }\r\n\r\n  /* ── EXAM DAY TIMELINE ── */\r\n  .day-timeline {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 0;\r\n    margin-bottom: 18px;\r\n  }\r\n  .dt-step {\r\n    display: grid;\r\n    grid-template-columns: 52px 1fr;\r\n    gap: 16px;\r\n    align-items: stretch;\r\n  }\r\n  .dt-left {\r\n    display: flex;\r\n    flex-direction: column;\r\n    align-items: center;\r\n  }\r\n  .dt-dot {\r\n    width: 14px;\r\n    height: 14px;\r\n    border-radius: 50%;\r\n    border: 2px solid var(--accent);\r\n    background: var(--bg);\r\n    flex-shrink: 0;\r\n    margin-top: 4px;\r\n  }\r\n  .dt-line {\r\n    width: 2px;\r\n    flex: 1;\r\n    background: var(--border);\r\n    margin: 4px 0;\r\n    min-height: 20px;\r\n  }\r\n  .dt-step:last-child .dt-line { display: none; }\r\n  .dt-content {\r\n    padding-bottom: 18px;\r\n  }\r\n  .dt-time {\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 10px;\r\n    letter-spacing: 0.12em;\r\n    color: var(--accent);\r\n    margin-bottom: 3px;\r\n    text-transform: uppercase;\r\n  }\r\n  .dt-title {\r\n    font-weight: 600;\r\n    font-size: 0.95rem;\r\n    margin-bottom: 4px;\r\n  }\r\n  .dt-desc { font-size: 0.86rem; color: var(--muted); line-height: 1.6; }\r\n\r\n  /* ── SKILL TRAINING CARDS ── */\r\n  .training-grid {\r\n    display: grid;\r\n    grid-template-columns: 1fr 1fr;\r\n    gap: 16px;\r\n    margin-bottom: 24px;\r\n  }\r\n  @media (max-width: 600px) { .training-grid { grid-template-columns: 1fr; } }\r\n  .tr-card {\r\n    background: var(--surface);\r\n    border: 1px solid var(--border);\r\n    border-radius: 12px;\r\n    padding: 20px;\r\n    border-top: 3px solid currentColor;\r\n  }\r\n  .tr-card.s-listen { color: var(--skill-listen); }\r\n  .tr-card.s-read   { color: var(--skill-read); }\r\n  .tr-card.s-write  { color: var(--skill-write); }\r\n  .tr-card.s-speak  { color: var(--skill-speak); }\r\n  .tr-icon { font-size: 22px; margin-bottom: 8px; }\r\n  .tr-title {\r\n    font-family: 'Source Sans 3', sans-serif;\r\n    font-weight: 600;\r\n    font-size: 0.97rem;\r\n    color: var(--text);\r\n    margin-bottom: 8px;\r\n  }\r\n  .tr-body { font-size: 0.86rem; color: var(--muted); line-height: 1.65; }\r\n  .tr-body ul { list-style: none; padding: 0; }\r\n  .tr-body ul li {\r\n    padding-left: 16px;\r\n    position: relative;\r\n    margin-bottom: 5px;\r\n  }\r\n  .tr-body ul li::before {\r\n    content: '·';\r\n    position: absolute;\r\n    left: 4px;\r\n  }\r\n\r\n  /* ── CHECKLIST ── */\r\n  .checklist-grid {\r\n    display: grid;\r\n    grid-template-columns: 1fr 1fr;\r\n    gap: 12px;\r\n    margin-bottom: 24px;\r\n  }\r\n  @media (max-width: 580px) { .checklist-grid { grid-template-columns: 1fr; } }\r\n  .cl-item {\r\n    display: flex;\r\n    align-items: flex-start;\r\n    gap: 12px;\r\n    background: var(--surface);\r\n    border: 1px solid var(--border);\r\n    border-radius: 10px;\r\n    padding: 14px 16px;\r\n    font-size: 0.88rem;\r\n    line-height: 1.55;\r\n    color: var(--text);\r\n  }\r\n  .cl-check {\r\n    width: 22px;\r\n    height: 22px;\r\n    border: 1.5px solid var(--border);\r\n    border-radius: 5px;\r\n    flex-shrink: 0;\r\n    margin-top: 1px;\r\n  }\r\n\r\n  /* ── COMPARISON TABLE (BIG) ── */\r\n  .big-table {\r\n    width: 100%;\r\n    border-collapse: collapse;\r\n    font-size: 0.85rem;\r\n    margin-bottom: 28px;\r\n  }\r\n  .big-table th {\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 10px;\r\n    letter-spacing: 0.14em;\r\n    text-transform: uppercase;\r\n    color: var(--muted);\r\n    text-align: left;\r\n    padding: 12px 14px;\r\n    border-bottom: 1px solid var(--border);\r\n    background: var(--surface);\r\n    white-space: nowrap;\r\n  }\r\n  .big-table td {\r\n    padding: 11px 14px;\r\n    border-bottom: 1px solid var(--border);\r\n    vertical-align: top;\r\n    line-height: 1.5;\r\n  }\r\n  .big-table tr:last-child td { border-bottom: none; }\r\n  .big-table tr:hover td { background: rgba(255,255,255,0.02); }\r\n\r\n  /* ── REDEMITTEL BOX ── */\r\n  .redemittel-grid {\r\n    display: grid;\r\n    grid-template-columns: 1fr 1fr;\r\n    gap: 16px;\r\n    margin-bottom: 24px;\r\n  }\r\n  @media (max-width: 580px) { .redemittel-grid { grid-template-columns: 1fr; } }\r\n  .rd-card {\r\n    background: var(--surface);\r\n    border: 1px solid var(--border);\r\n    border-radius: 10px;\r\n    padding: 16px 18px;\r\n  }\r\n  .rd-title {\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 10px;\r\n    letter-spacing: 0.14em;\r\n    text-transform: uppercase;\r\n    color: var(--accent);\r\n    margin-bottom: 10px;\r\n  }\r\n  .rd-phrase {\r\n    font-family: 'Playfair Display', serif;\r\n    font-style: italic;\r\n    font-size: 0.9rem;\r\n    color: var(--text);\r\n    padding: 5px 0;\r\n    border-bottom: 1px solid var(--border);\r\n    line-height: 1.55;\r\n  }\r\n  .rd-phrase:last-child { border-bottom: none; }\n\n  /* ── QUICK ANSWER ── */\n  .quick-answer {\n    max-width: 900px;\n    margin: 0 auto 52px;\n    padding: 30px;\n    border: 1px solid rgba(94,184,160,0.28);\n    border-radius: 18px;\n    background: linear-gradient(145deg, rgba(94,184,160,0.11), rgba(23,23,30,0.96));\n    box-shadow: 0 22px 55px rgba(0,0,0,0.22);\n  }\n  .quick-answer-label {\n    margin-bottom: 8px;\n    font-family: 'JetBrains Mono', monospace;\n    font-size: 10px;\n    font-weight: 700;\n    letter-spacing: 0.18em;\n    text-transform: uppercase;\n    color: var(--accent);\n  }\n  .quick-answer h2 {\n    margin-bottom: 12px;\n    font-family: 'Playfair Display', serif;\n    font-size: clamp(1.65rem, 4vw, 2.35rem);\n    line-height: 1.2;\n  }\n  .quick-answer-lead { color: var(--text); font-size: 1rem; line-height: 1.75; }\n  .decision-grid {\n    display: grid;\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n    gap: 12px;\n    margin-top: 22px;\n  }\n  .decision-card {\n    padding: 16px;\n    border: 1px solid var(--border);\n    border-radius: 12px;\n    background: rgba(15,15,19,0.62);\n  }\n  .decision-card h3 { margin-bottom: 6px; color: var(--accent); font-size: 0.96rem; }\n  .decision-card p { color: var(--muted); font-size: 0.9rem; line-height: 1.6; }\n  .quick-answer-question { margin-top: 20px; }\n  .quick-answer-question h3 { margin-bottom: 6px; font-size: 1.05rem; }\n  .quick-answer-question p { color: var(--muted); font-size: 0.92rem; line-height: 1.65; }\n  .quick-answer-cta {\n    display: inline-flex;\n    min-height: 44px;\n    align-items: center;\n    justify-content: center;\n    margin-top: 22px;\n    padding: 11px 20px;\n    border-radius: 999px;\n    background: #2aabee;\n    color: #fff;\n    font-weight: 700;\n    text-decoration: none;\n  }\n  .quick-answer-cta:hover { background: #169bdc; }\n  .quick-answer-note { margin-top: 10px; color: var(--muted); font-size: 0.78rem; }\n  @media (max-width: 640px) {\n    .quick-answer { margin-inline: 16px; padding: 22px 18px; }\n    .decision-grid { grid-template-columns: 1fr; }\n  }\n\n  /* ── FOOTER ── */\n  footer {\r\n    border-top: 1px solid var(--border);\r\n    padding: 34px 24px;\r\n    text-align: center;\r\n    color: var(--muted);\r\n    font-size: 0.83rem;\r\n    line-height: 1.8;\r\n  }\r\n  footer a { color: var(--accent); text-decoration: none; }\r\n  footer a:hover { text-decoration: underline; }\r\n\r\n  /* ── ANIMATIONS ── */\r\n  @keyframes fadeUp {\r\n    from { opacity: 0; transform: translateY(18px); }\r\n    to   { opacity: 1; transform: translateY(0); }\r\n  }\r\n\r\n  /* ── SCORE BAR ── */\r\n  .score-row {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 12px;\r\n    margin-bottom: 8px;\r\n    font-size: 0.86rem;\r\n  }\r\n  .score-label {\r\n    width: 90px;\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 10px;\r\n    color: var(--muted);\r\n    flex-shrink: 0;\r\n  }\r\n  .score-track {\r\n    flex: 1;\r\n    height: 6px;\r\n    background: var(--border);\r\n    border-radius: 3px;\r\n    overflow: hidden;\r\n  }\r\n  .score-fill {\r\n    height: 100%;\r\n    border-radius: 3px;\r\n    background: var(--accent);\r\n  }\r\n  .score-val {\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 11px;\r\n    color: var(--muted);\r\n    width: 40px;\r\n    text-align: right;\r\n    flex-shrink: 0;\r\n  }\r\n"
  },
  "sprachniveaus-a0-c2": {
    "content": "\r\n\r\n<!-- ════════════════════ HERO ════════════════════ -->\r\n<header class=\"hero\">\r\n  <p class=\"hero-eyebrow\">GER / CEFR · Gemeinsamer Europäischer Referenzrahmen</p>\r\n  <h1>Lernweg Deutsch:<br><em>A0 bis C2</em></h1>\r\n  <p class=\"hero-sub\">Orientierung von Pre-A1 bis C2 — mit GER-Kompetenzen, Lernzielen, Zeitkorridoren und passenden Prüfungen.</p>\r\n\r\n  <div class=\"level-strip\">\r\n    <span class=\"level-pill pill-a0\">A0</span>\r\n    <span class=\"level-pill pill-a1\">A1</span>\r\n    <span class=\"level-pill pill-a2\">A2</span>\r\n    <span class=\"level-pill pill-b1\">B1</span>\r\n    <span class=\"level-pill pill-b2\">B2</span>\r\n    <span class=\"level-pill pill-c1\">C1</span>\r\n    <span class=\"level-pill pill-c2\">C2</span>\r\n  </div>\r\n  <p class=\"group-label\">Elementar · Selbstständig · Kompetent</p>\r\n</header>\n\n<!-- ════════════════════ KURZANTWORT ════════════════════ -->\n<section class=\"quick-answer\" aria-labelledby=\"b2-kurzantwort\">\n  <p class=\"quick-answer-label\">Kurzantwort</p>\n  <h2 id=\"b2-kurzantwort\">Wie lange dauert es, Deutsch B2 zu erreichen?</h2>\n  <p class=\"quick-answer-lead\">\n    Als grobe Orientierung kannst du von null bis B2 mit insgesamt etwa 600–800 Unterrichtseinheiten à 45 Minuten rechnen. Das ist keine feste Dauer: Vorkenntnisse, Lernintensität, Unterrichtsqualität, Selbststudium und die vier Fertigkeiten verändern den Weg deutlich. Bei zehn Unterrichtseinheiten pro Woche entsprechen 600–800 Einheiten rechnerisch etwa 60–80 Kurswochen; Ferien, Pausen und zusätzliche Übungszeit kommen dazu.\n  </p>\n  <div class=\"quick-answer-table-wrap\">\n    <table class=\"quick-answer-table\">\n      <thead><tr><th>Startpunkt</th><th>Sinnvolle Orientierung</th><th>Nächster Schritt</th></tr></thead>\n      <tbody>\n        <tr><td>Neu / Pre-A1</td><td>600–800 UE bis B2 als grober Gesamtkorridor</td><td>Lernplan in Etappen A1, A2, B1 und B2 aufteilen</td></tr>\n        <tr><td>A2</td><td>Nicht einfach Stunden vom Gesamtkorridor abziehen</td><td>Hören, Lesen, Schreiben und Sprechen getrennt einstufen</td></tr>\n        <tr><td>B1</td><td>Dauer hängt besonders von aktiven Lücken und Prüfungsziel ab</td><td>B2-Diagnosetest und Probeaufgaben des Zielanbieters nutzen</td></tr>\n        <tr><td>Niveau unbekannt</td><td>Eine Zeitprognose wäre ohne Einstufung unzuverlässig</td><td>Zuerst Einstufungstest, danach Wochenplan festlegen</td></tr>\n      </tbody>\n    </table>\n  </div>\n  <div class=\"quick-answer-question\">\n    <h3>Was bedeuten A1, A2, B1, B2, C1 und C2?</h3>\n    <p>A-Stufen beschreiben elementare, B-Stufen selbstständige und C-Stufen kompetente Sprachverwendung. Entscheidend sind konkrete Fähigkeiten in Hören, Lesen, Schreiben und Sprechen — nicht nur die Zahl absolvierter Kursstunden.</p>\n  </div>\n  <a class=\"quick-answer-cta\" data-article-quiz-cta href=\"__ARTICLE_QUIZ_BOT_URL__\" target=\"_blank\" rel=\"noopener noreferrer\">Deutsch-Niveau im Quiz-Bot testen →</a>\n  <p class=\"quick-answer-note\">Das Quiz liefert Lernorientierung und ersetzt keine offizielle Sprachprüfung oder verbindliche Einstufung.</p>\n</section>\n\n<!-- ════════════════════ CEFR OVERVIEW ════════════════════ -->\n<div class=\"container\" style=\"max-width:860px; padding-bottom:0;\">\r\n  <div class=\"cefr-bar\">\r\n    <div class=\"cefr-group elementary\">\r\n      <p class=\"cefr-group-label\">A1 – A2</p>\r\n      <p class=\"cefr-group-title\">Elementare Verwendung</p>\r\n      <p class=\"cefr-group-sub\">Grundlegende Kommunikationsfähigkeit für den Alltag</p>\r\n    </div>\r\n    <div class=\"cefr-group independent\">\r\n      <p class=\"cefr-group-label\">B1 – B2</p>\r\n      <p class=\"cefr-group-title\">Selbstständige Verwendung</p>\r\n      <p class=\"cefr-group-sub\">Eigenständige Kommunikation in Beruf, Studium und Gesellschaft</p>\r\n    </div>\r\n    <div class=\"cefr-group proficient\">\r\n      <p class=\"cefr-group-label\">C1 – C2</p>\r\n      <p class=\"cefr-group-title\">Kompetente Verwendung</p>\r\n      <p class=\"cefr-group-sub\">Freies, präzises Sprachhandeln auf akademischem und beruflichem Spitzenniveau</p>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"progress-track\">\r\n    <div class=\"progress-bar\">\r\n      <div class=\"pb-seg pb-a0\"></div>\r\n      <div class=\"pb-seg pb-a1\"></div>\r\n      <div class=\"pb-seg pb-a2\"></div>\r\n      <div class=\"pb-seg pb-b1\"></div>\r\n      <div class=\"pb-seg pb-b2\"></div>\r\n      <div class=\"pb-seg pb-c1\"></div>\r\n      <div class=\"pb-seg pb-c2\"></div>\r\n    </div>\r\n    <div class=\"progress-labels\">\r\n      <span>A0</span><span>A1</span><span>A2</span><span>B1</span><span>B2</span><span>C1</span><span>C2</span>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<!-- ════════════════════ LEVEL CARDS ════════════════════ -->\r\n<div class=\"container\">\r\n\r\n  <div class=\"section-header\"><h2>Niveaustufen im Detail</h2></div>\r\n\r\n  <!-- ─── A0 ─── -->\r\n  <div class=\"level-card lv-a0\" id=\"lv-a0\">\r\n    <div class=\"card-header\" onclick=\"toggleCard('lv-a0')\">\r\n      <div class=\"level-badge\">A0</div>\r\n      <div>\r\n        <p class=\"card-title\">Vorstufe / Einstieg</p>\r\n        <p class=\"card-subtitle\">Pre-A1 · „Ich bin neu\" · Erste Wörter und Phrasen</p>\r\n      </div>\r\n      <div class=\"card-toggle\">▾</div>\r\n    </div>\r\n    <div class=\"card-body\">\r\n      <p class=\"card-description lv-a0\">\r\n        <strong>A0</strong> ist keine offizielle Bezeichnung des GER/CEFR. Diese Seite verwendet A0 als leicht verständliche Kurzform für <strong>Pre-A1</strong>, eine Kompetenzstufe, die der GER-Begleitband unterhalb von A1 beschreibt. Lernende arbeiten hier vor allem mit einzelnen Wörtern und festen Wendungen; eine selbstständige Sprachproduktion ist noch kaum möglich.\r\n      </p>\r\n      <div class=\"card-grid\">\r\n        <div class=\"card-block\">\r\n          <h4>Was du bereits kannst</h4>\r\n          <ul>\r\n            <li>Sehr einfache Wörter verstehen: Hallo, Danke, Ja, Nein, Bitte</li>\r\n            <li>Sich mit wenigen Wörtern vorstellen: Name, Herkunftsland</li>\r\n            <li>Das Alphabet buchstabieren: M-A-X</li>\r\n            <li>Zahlen von 1 bis 20 nennen</li>\r\n            <li>Grundlegende Farben und Wochentage kennen</li>\r\n            <li>Einfache Schilder und Aufschriften lesen (Eingang, Ausgang, WC)</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"card-block\">\r\n          <h4>Typische Themen</h4>\r\n          <ul>\r\n            <li>Begrüßung und Verabschiedung</li>\r\n            <li>Name, Alter, Herkunftsland</li>\r\n            <li>Zahlen 1–100, Farben</li>\r\n            <li>Wochentage und Monate</li>\r\n            <li>Einfache Orte: Bahnhof, Schule, Café, Supermarkt</li>\r\n            <li>Höfliche Grundformeln: Entschuldigung, Wie bitte?</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"card-block card-block-full\">\r\n          <h4>Erste Grammatikbausteine</h4>\r\n          <div class=\"grammar-tags\">\r\n            <span class=\"grammar-tag\">Artikel: der / die / das</span>\r\n            <span class=\"grammar-tag\">Personalpronomen: ich, du, er, sie, es</span>\r\n            <span class=\"grammar-tag\">Präsens von sein und haben</span>\r\n            <span class=\"grammar-tag\">Basisverben: heißen, kommen, wohnen</span>\r\n            <span class=\"grammar-tag\">W-Fragen: Wie? Woher? Was?</span>\r\n            <span class=\"grammar-tag\">Zahlen 1–100</span>\r\n          </div>\r\n        </div>\r\n        <div class=\"card-block\">\r\n          <h4>Kleiner Selbsttest</h4>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich kann meinen Namen auf Deutsch buchstabieren.</span></div>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich kann sagen: „Ich heiße … / Ich komme aus …\"</span></div>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich kenne die Zahlen von 1 bis 20.</span></div>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich verstehe einfache Begrüßungen und kann sie erwidern.</span></div>\r\n        </div>\r\n        <div class=\"card-block\">\r\n          <h4>Beispielsätze</h4>\r\n          <div class=\"example-item lv-a0\">„Hallo! Ich heiße Lina. Ich komme aus der Ukraine.\"</div>\r\n          <div class=\"example-item lv-a0\">„Mein Name ist Max. Ich bin zwanzig Jahre alt.\"</div>\r\n          <div class=\"example-item lv-a0\">„Entschuldigung! Wie bitte?\"</div>\r\n        </div>\r\n      </div>\r\n      <div class=\"time-badge\">⏱ Pre-A1: keine einheitliche Stundenvorgabe</div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- ─── A1 ─── -->\r\n  <div class=\"level-card lv-a1\" id=\"lv-a1\">\r\n    <div class=\"card-header\" onclick=\"toggleCard('lv-a1')\">\r\n      <div class=\"level-badge\">A1</div>\r\n      <div>\r\n        <p class=\"card-title\">Elementare Sprachverwendung</p>\r\n        <p class=\"card-subtitle\">„Überleben im Alltag\" · Erste offizielle GER/CEFR-Stufe</p>\r\n      </div>\r\n      <div class=\"card-toggle\">▾</div>\r\n    </div>\r\n    <div class=\"card-body\">\r\n      <p class=\"card-description lv-a1\">\r\n        Auf A1 kannst du dich in <strong>einfachen, vertrauten Alltagssituationen</strong> verständigen, sofern dein Gesprächspartner langsam und deutlich spricht und bereit ist, zu helfen. Du verstehst und benutzt sehr geläufige Ausdrücke und ganz einfache Sätze. Das Ziel ist nicht Perfektion, sondern funktionale Kommunikation: im Café bestellen, nach dem Weg fragen, dich vorstellen. Auf A1 lernst du, Deutsch als Überlebensinstrument im Alltag einzusetzen.\r\n      </p>\r\n      <div class=\"card-grid\">\r\n        <div class=\"card-block\">\r\n          <h4>Was du kannst</h4>\r\n          <ul>\r\n            <li>Sich vorstellen und einfache persönliche Fragen stellen und beantworten</li>\r\n            <li>Im Café oder Restaurant bestellen und bezahlen</li>\r\n            <li>Nach dem Weg fragen und einfache Wegbeschreibungen verstehen</li>\r\n            <li>Einfache Formulare ausfüllen (Name, Adresse, Geburtsdatum)</li>\r\n            <li>Kurze Ansagen verstehen, wenn langsam und deutlich gesprochen wird</li>\r\n            <li>Über Familie, Beruf und Wohnort sprechen</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"card-block\">\r\n          <h4>Typische Themen</h4>\r\n          <ul>\r\n            <li>Familie und Freunde</li>\r\n            <li>Wohnung, Haus, Zimmer</li>\r\n            <li>Essen, Trinken, Einkaufen</li>\r\n            <li>Uhrzeit, Tagesablauf, Wochentage</li>\r\n            <li>Berufe und Hobbys</li>\r\n            <li>Stadtteile, Verkehrsmittel</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"card-block card-block-full\">\r\n          <h4>Grammatik auf diesem Niveau</h4>\r\n          <div class=\"grammar-tags\">\r\n            <span class=\"grammar-tag\">Präsens – regelmäßige Verben</span>\r\n            <span class=\"grammar-tag\">Modalverben: können, müssen, wollen, möchten</span>\r\n            <span class=\"grammar-tag\">Negation: nicht / kein</span>\r\n            <span class=\"grammar-tag\">Nominativ &amp; Akkusativ</span>\r\n            <span class=\"grammar-tag\">Trennbare Verben (erste)</span>\r\n            <span class=\"grammar-tag\">W-Fragen + Ja-/Nein-Fragen</span>\r\n            <span class=\"grammar-tag\">Possessivpronomen: mein, dein, sein</span>\r\n            <span class=\"grammar-tag\">Plural der Nomen (häufigste Formen)</span>\r\n          </div>\r\n        </div>\r\n        <div class=\"card-block\">\r\n          <h4>Kleiner Selbsttest</h4>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich kann im Café einen Kaffee und die Rechnung bestellen.</span></div>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich kann nach dem Weg zur U-Bahn fragen.</span></div>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich verstehe, wenn jemand langsam und deutlich mit mir spricht.</span></div>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich kann einfache Angaben zu meiner Person machen.</span></div>\r\n        </div>\r\n        <div class=\"card-block\">\r\n          <h4>Beispielsätze</h4>\r\n          <div class=\"example-item lv-a1\">„Ich hätte gern einen Kaffee und ein Croissant, bitte. Und die Rechnung, bitte.\"</div>\r\n          <div class=\"example-item lv-a1\">„Entschuldigung, wo ist die nächste U-Bahn-Station?\"</div>\r\n          <div class=\"example-item lv-a1\">„Ich wohne in Wien. Ich arbeite als Lehrerin. Ich habe zwei Kinder.\"</div>\r\n        </div>\r\n      </div>\r\n      <div class=\"time-badge\">⏱ Orientierung: 80–200 UE à 45 Min. (ab Null)</div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- ─── A2 ─── -->\r\n  <div class=\"level-card lv-a2\" id=\"lv-a2\">\r\n    <div class=\"card-header\" onclick=\"toggleCard('lv-a2')\">\r\n      <div class=\"level-badge\">A2</div>\r\n      <div>\r\n        <p class=\"card-title\">Sicherer Alltag</p>\r\n        <p class=\"card-subtitle\">„Alltag sicher erklären\" · Routinesituationen ohne Stress</p>\r\n      </div>\r\n      <div class=\"card-toggle\">▾</div>\r\n    </div>\r\n    <div class=\"card-body\">\r\n      <p class=\"card-description lv-a2\">\r\n        Auf A2 kannst du dich in <strong>routinemäßigen Alltagssituationen</strong> verständigen und über vertraute Themen sprechen oder schreiben. Du bist in der Lage, einfache Informationen über dich und deine Umgebung auszutauschen. Anders als auf A1 kannst du jetzt auch über <strong>Vergangenes berichten</strong>, Termine vereinbaren und einfache Gründe nennen. A2 ist der erste Schritt zur sprachlichen Selbstständigkeit im deutschsprachigen Alltag.\r\n      </p>\r\n      <div class=\"card-grid\">\r\n        <div class=\"card-block\">\r\n          <h4>Was du kannst</h4>\r\n          <ul>\r\n            <li>Alltagssituationen bewältigen: Arzttermin, Bank, Supermarkt, Behörden (einfach)</li>\r\n            <li>Kurz erzählen, was gestern oder letzte Woche passiert ist</li>\r\n            <li>Einen Termin telefonisch vereinbaren oder absagen</li>\r\n            <li>Einfache SMS, Notizen oder kurze E-Mails schreiben</li>\r\n            <li>Einfache Gründe nennen und verknüpfen: „weil …\", „deshalb …\"</li>\r\n            <li>Kurze Ankündigungen, Schilder und Menüs verstehen</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"card-block\">\r\n          <h4>Typische Themen</h4>\r\n          <ul>\r\n            <li>Gesundheit, Arztbesuch, Apotheke</li>\r\n            <li>Arbeit, Kollegen, Büro</li>\r\n            <li>Feste, Traditionen, Jahreszeiten</li>\r\n            <li>Wochenendpläne und Freizeitaktivitäten</li>\r\n            <li>Einfache Beschwerden und Bitten</li>\r\n            <li>Reisen, Unterkunft, Ausflüge</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"card-block card-block-full\">\r\n          <h4>Grammatik auf diesem Niveau</h4>\r\n          <div class=\"grammar-tags\">\r\n            <span class=\"grammar-tag\">Perfekt (Hauptvergangenheit)</span>\r\n            <span class=\"grammar-tag\">Akkusativ &amp; Dativ (sicher)</span>\r\n            <span class=\"grammar-tag\">Trennbare und untrennbare Verben</span>\r\n            <span class=\"grammar-tag\">Nebensätze: weil, dass, wenn</span>\r\n            <span class=\"grammar-tag\">Vergleiche: größer als / am besten</span>\r\n            <span class=\"grammar-tag\">Präpositionen mit Dativ und Akkusativ</span>\r\n            <span class=\"grammar-tag\">Imperativ (Aufforderungen)</span>\r\n            <span class=\"grammar-tag\">Zeitangaben: damals, gestern, nächste Woche</span>\r\n          </div>\r\n        </div>\r\n        <div class=\"card-block\">\r\n          <h4>Kleiner Selbsttest</h4>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich kann beim Arzt einen Termin telefonisch vereinbaren.</span></div>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich kann erzählen, was ich gestern gemacht habe.</span></div>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich verstehe einfache Briefe und Aushänge.</span></div>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich kann einen Termin verschieben oder absagen.</span></div>\r\n        </div>\r\n        <div class=\"card-block\">\r\n          <h4>Beispielsätze</h4>\r\n          <div class=\"example-item lv-a2\">„Ich habe gestern beim Arzt angerufen, weil ich Halsschmerzen habe.\"</div>\r\n          <div class=\"example-item lv-a2\">„Können wir den Termin auf Donnerstagnachmittag verschieben?\"</div>\r\n          <div class=\"example-item lv-a2\">„Ich stehe um sieben Uhr auf und fahre mit der U-Bahn zur Arbeit.\"</div>\r\n        </div>\r\n      </div>\r\n      <div class=\"time-badge\">⏱ Orientierung: 200–350 UE à 45 Min. (ab Null)</div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- ─── B1 ─── -->\r\n  <div class=\"level-card lv-b1\" id=\"lv-b1\">\r\n    <div class=\"card-header\" onclick=\"toggleCard('lv-b1')\">\r\n      <div class=\"level-badge\">B1</div>\r\n      <div>\r\n        <p class=\"card-title\">Selbstständiges Sprechen</p>\r\n        <p class=\"card-subtitle\">„Zusammenhängend sprechen\" · Häufig relevant für Integration und Aufenthalt</p>\r\n      </div>\r\n      <div class=\"card-toggle\">▾</div>\r\n    </div>\r\n    <div class=\"card-body\">\r\n      <div class=\"notice\"><strong>Wichtig:</strong> B1 ist in mehreren Verfahren relevant, aber nicht pauschal für jeden Aufenthaltstitel. Beispiele: In Deutschland wird B1 grundsätzlich bei der allgemeinen Niederlassungserlaubnis verlangt; in Österreich entspricht Modul 2 der Integrationsvereinbarung B1 und ist Voraussetzung für „Daueraufenthalt – EU“. Für die Einbürgerung in der Schweiz gelten mindestens B1 mündlich und A2 schriftlich. Ausnahmen und weitere Voraussetzungen hängen vom konkreten Verfahren ab.</div>\r\n      <p class=\"card-description lv-b1\">\r\n        Auf B1 verstehst du die <strong>Hauptaussagen klarer Standardsprache</strong> zu vertrauten Themen aus Alltag, Schule und Beruf. Du kannst die meisten Situationen bewältigen, die beim Reisen in einem deutschsprachigen Land entstehen. Du kannst dich einfach und zusammenhängend zu vertrauten Themen äußern, über Erfahrungen, Ereignisse, Träume und Ziele berichten und kurze Begründungen oder Erklärungen geben. B1 bedeutet: Du kommunizierst nicht mehr nur reaktiv – du <em>gestaltest</em> Gespräche aktiv.\r\n      </p>\r\n      <div class=\"card-grid\">\r\n        <div class=\"card-block\">\r\n          <h4>Was du kannst</h4>\r\n          <ul>\r\n            <li>Über Erfahrungen, Pläne und Wünsche zusammenhängend sprechen</li>\r\n            <li>Eine einfache Meinung äußern und kurz begründen</li>\r\n            <li>Längere Alltagsgespräche führen – nicht perfekt, aber stabil</li>\r\n            <li>E-Mails, Beschwerden und kurze Bewerbungen schreiben</li>\r\n            <li>Den Inhalt von Radionachrichten und einfachen Podcasts verstehen</li>\r\n            <li>Texte zu vertrauten Themen lesen und den Hauptgedanken erfassen</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"card-block\">\r\n          <h4>Typische Themen</h4>\r\n          <ul>\r\n            <li>Ausbildung, Studium, Berufseinstieg</li>\r\n            <li>Gesellschaft, Umwelt, Medien</li>\r\n            <li>Kultur, Reisen, Sport, Freizeit</li>\r\n            <li>Probleme und Lösungen im Alltag</li>\r\n            <li>Offizielle Briefe und Anträge</li>\r\n            <li>Persönliche Träume und Lebenspläne</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"card-block card-block-full\">\r\n          <h4>Grammatik auf diesem Niveau</h4>\r\n          <div class=\"grammar-tags\">\r\n            <span class=\"grammar-tag\">Präteritum (sein, haben, Modalverben)</span>\r\n            <span class=\"grammar-tag\">Nebensätze: obwohl, damit, während, als, bevor</span>\r\n            <span class=\"grammar-tag\">Infinitiv mit zu</span>\r\n            <span class=\"grammar-tag\">Konjunktiv II (hätte, wäre, würde) – Grundlagen</span>\r\n            <span class=\"grammar-tag\">Relativsätze (Nominativ / Akkusativ)</span>\r\n            <span class=\"grammar-tag\">Passiv Präsens – erste Einführung</span>\r\n            <span class=\"grammar-tag\">Erste feste Redewendungen</span>\r\n            <span class=\"grammar-tag\">Indirekte Fragen: Ich weiß nicht, ob …</span>\r\n          </div>\r\n        </div>\r\n        <div class=\"card-block\">\r\n          <h4>Kleiner Selbsttest</h4>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich kann 2–3 Minuten frei über ein Thema sprechen.</span></div>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich kann eine E-Mail schreiben, in der ich um Hilfe bitte.</span></div>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich verstehe den Kern von Radionachrichten zu vertrauten Themen.</span></div>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich kann meine Meinung äußern und einfach begründen.</span></div>\r\n        </div>\r\n        <div class=\"card-block\">\r\n          <h4>Beispielsätze</h4>\r\n          <div class=\"example-item lv-b1\">„Ich war letzten Sommer in München. Es hat mir sehr gut gefallen, obwohl es ziemlich teuer war.\"</div>\r\n          <div class=\"example-item lv-b1\">„Ich denke, dass Deutschkenntnisse wichtig sind, weil ich hier langfristig arbeiten möchte.\"</div>\r\n          <div class=\"example-item lv-b1\">„Ich möchte einen Termin vereinbaren, um das Problem persönlich zu besprechen.\"</div>\r\n        </div>\r\n      </div>\r\n      <div class=\"time-badge\">⏱ Orientierung: 350–650 UE à 45 Min. (ab Null)</div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- ─── B2 ─── -->\r\n  <div class=\"level-card lv-b2\" id=\"lv-b2\">\r\n    <div class=\"card-header\" onclick=\"toggleCard('lv-b2')\">\r\n      <div class=\"level-badge\">B2</div>\r\n      <div>\r\n        <p class=\"card-title\">Fließend und flexibel</p>\r\n        <p class=\"card-subtitle\">„Flüssig und flexibel\" · Fortgeschritten in Beruf und Studium</p>\r\n      </div>\r\n      <div class=\"card-toggle\">▾</div>\r\n    </div>\r\n    <div class=\"card-body\">\r\n      <div class=\"notice\"><strong>Wichtig:</strong> B2 wird von einigen Hochschulen und in manchen Studiengängen akzeptiert; für die uneingeschränkte Hochschulzulassung in Deutschland sind häufig Nachweise auf höherem Niveau vorgesehen, etwa TestDaF mit TDN 4 in allen vier Teilen oder DSH-2. Auch in reglementierten Gesundheitsberufen unterscheiden sich allgemein- und fachsprachliche Anforderungen nach Beruf und zuständiger Stelle. Prüfe deshalb immer die konkrete Zulassungs- oder Anerkennungsordnung.</div>\r\n      <p class=\"card-description lv-b2\">\r\n        Auf B2 verstehst du die Hauptinhalte <strong>komplexer Texte zu konkreten und abstrakten Themen</strong>, einschließlich Fachdiskussionen in deinem Spezialgebiet. Du kannst dich so spontan und fließend verständigen, dass ein normales Gespräch mit einem Muttersprachler ohne größere Anstrengung möglich ist. Du kannst dich zu einem breiten Themenspektrum klar und detailliert ausdrücken, einen Standpunkt zu einer aktuellen Frage erläutern sowie Vor- und Nachteile verschiedener Möglichkeiten angeben.\r\n      </p>\r\n      <div class=\"card-grid\">\r\n        <div class=\"card-block\">\r\n          <h4>Was du kannst</h4>\r\n          <ul>\r\n            <li>An Diskussionen teilnehmen und Argumente strukturiert darlegen</li>\r\n            <li>Berufliche Verhandlungen und Besprechungen sicher führen</li>\r\n            <li>Klare, detaillierte Texte schreiben: Berichte, Stellungnahmen, Zusammenfassungen</li>\r\n            <li>Authentische Texte und Rundfunksendungen verstehen</li>\r\n            <li>Spontan reagieren, ohne sichtbar nach Worten suchen zu müssen</li>\r\n            <li>Stil und Ton je nach Situation anpassen (formell / informell)</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"card-block\">\r\n          <h4>Typische Themen</h4>\r\n          <ul>\r\n            <li>Wirtschaft, Gesellschaft, aktuelle Politik</li>\r\n            <li>Wissenschaft und Technologie (zugänglich)</li>\r\n            <li>Kunst, Film, Literatur, Musik</li>\r\n            <li>Geschäftskorrespondenz und Berichte</li>\r\n            <li>Abstrakte Konzepte und Ideen</li>\r\n            <li>Interkulturelle Fragen und Lebensstile</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"card-block card-block-full\">\r\n          <h4>Grammatik auf diesem Niveau</h4>\r\n          <div class=\"grammar-tags\">\r\n            <span class=\"grammar-tag\">Konjunktiv II (erweitert und sicher)</span>\r\n            <span class=\"grammar-tag\">Passiv (Präteritum, Perfekt, mit Modalverben)</span>\r\n            <span class=\"grammar-tag\">Nominalisierung (Verb → Nomen)</span>\r\n            <span class=\"grammar-tag\">Partizipialkonstruktionen</span>\r\n            <span class=\"grammar-tag\">Zweiteilige Konnektoren: sowohl … als auch, entweder … oder</span>\r\n            <span class=\"grammar-tag\">Konjunktiv I (indirekte Rede)</span>\r\n            <span class=\"grammar-tag\">Stilistische Register: neutral, formell, umgangssprachlich</span>\r\n            <span class=\"grammar-tag\">Erweiterte Relativsätze (alle Fälle)</span>\r\n          </div>\r\n        </div>\r\n        <div class=\"card-block\">\r\n          <h4>Kleiner Selbsttest</h4>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich kann spontan argumentieren, ohne lange nach Worten zu suchen.</span></div>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich kann einen logisch aufgebauten Bericht oder eine Stellungnahme schreiben.</span></div>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich verstehe die meisten Fernsehsendungen und Zeitungsartikel.</span></div>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich kann Vor- und Nachteile eines Themas differenziert darstellen.</span></div>\r\n        </div>\r\n        <div class=\"card-block\">\r\n          <h4>Beispielsätze</h4>\r\n          <div class=\"example-item lv-b2\">„Meiner Meinung nach hat diese Maßnahme zwei wesentliche Vorteile, allerdings auch einen erheblichen Nachteil, der nicht unterschätzt werden sollte.\"</div>\r\n          <div class=\"example-item lv-b2\">„Wenn ich mehr Zeit hätte, würde ich einen intensiveren Kurs belegen und täglich üben.\"</div>\r\n          <div class=\"example-item lv-b2\">„Das Problem wird in der öffentlichen Diskussion häufig vereinfacht dargestellt.\"</div>\r\n        </div>\r\n      </div>\r\n      <div class=\"time-badge\">⏱ Orientierung: 600–800 UE à 45 Min. (ab Null)</div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- ─── C1 ─── -->\r\n  <div class=\"level-card lv-c1\" id=\"lv-c1\">\r\n    <div class=\"card-header\" onclick=\"toggleCard('lv-c1')\">\r\n      <div class=\"level-badge\">C1</div>\r\n      <div>\r\n        <p class=\"card-title\">Akademische und berufliche Kompetenz</p>\r\n        <p class=\"card-subtitle\">„Sehr sicher im Studium und Beruf\" · Flexibel und treffsicher</p>\r\n      </div>\r\n      <div class=\"card-toggle\">▾</div>\r\n    </div>\r\n    <div class=\"card-body\">\r\n      <p class=\"card-description lv-c1\">\r\n        Auf C1 kannst du ein <strong>breites Spektrum anspruchsvoller, längerer Texte verstehen</strong> und auch implizite Bedeutungen erfassen. Du drückst dich fließend und spontan aus, ohne öfter merklich nach Worten suchen zu müssen. Du verwendest die Sprache im gesellschaftlichen und beruflichen Leben oder in Ausbildung und Studium wirksam und flexibel. Du kannst dich klar, strukturiert und ausführlich zu komplexen Sachverhalten äußern und dabei verschiedene Mittel zur Textverknüpfung angemessen verwenden. C1 ist das Niveau der <strong>echten sprachlichen Freiheit</strong>: Du meisterst hitzige Diskussionen, schwierige Verhandlungen und anspruchsvolle akademische Texte.\r\n      </p>\r\n      <div class=\"card-grid\">\r\n        <div class=\"card-block\">\r\n          <h4>Was du kannst</h4>\r\n          <ul>\r\n            <li>Implizite Bedeutungen und Zwischentöne verstehen</li>\r\n            <li>Präsentationen halten und Meetings moderieren</li>\r\n            <li>Anspruchsvolle Texte strukturieren: Analysen, Essays, Konzepte</li>\r\n            <li>Stil flexibel anpassen: formal, sachlich, überzeugend, diplomatisch</li>\r\n            <li>Komplexe akademische Vorlesungen und Fachdiskussionen folgen</li>\r\n            <li>Literarische und journalistische Texte verstehen und analysieren</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"card-block\">\r\n          <h4>Typische Themen</h4>\r\n          <ul>\r\n            <li>Akademische Texte und Fachartikel</li>\r\n            <li>Komplexe gesellschaftliche Fragen</li>\r\n            <li>Juristische und geschäftliche Sprache</li>\r\n            <li>Öffentliche Debatten und Reden</li>\r\n            <li>Literarische Prosa und wissenschaftliche Abhandlungen</li>\r\n            <li>Interkulturelle Kommunikation auf hohem Niveau</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"card-block card-block-full\">\r\n          <h4>Sprache und Stilmittel auf diesem Niveau</h4>\r\n          <div class=\"grammar-tags\">\r\n            <span class=\"grammar-tag\">Nuancierte Konnektoren: nichtsdestotrotz, insofern, währenddessen</span>\r\n            <span class=\"grammar-tag\">Erweiterte Partizipialkonstruktionen</span>\r\n            <span class=\"grammar-tag\">Breite stilistische Variation</span>\r\n            <span class=\"grammar-tag\">Idiomatik und feste Wendungen</span>\r\n            <span class=\"grammar-tag\">Präzise, differenzierte Wortwahl</span>\r\n            <span class=\"grammar-tag\">Kohäsionsmittel im Text (Referenz, Substitution, Ellipse)</span>\r\n            <span class=\"grammar-tag\">Rhetorik: Ironie, Understatement, Litotes</span>\r\n          </div>\r\n        </div>\r\n        <div class=\"card-block\">\r\n          <h4>Kleiner Selbsttest</h4>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich kann ein komplexes Thema 5–10 Minuten frei und strukturiert präsentieren.</span></div>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Meine Texte wirken auf Muttersprachler professionell und gepflegt.</span></div>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich erkenne Ironie, Andeutungen und Subtext im Gespräch.</span></div>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich folge akademischen Vorlesungen ohne größere Schwierigkeiten.</span></div>\r\n        </div>\r\n        <div class=\"card-block\">\r\n          <h4>Beispielsätze</h4>\r\n          <div class=\"example-item lv-c1\">„Zusammenfassend lässt sich feststellen, dass die Maßnahme durchaus wirksam ist, sofern die strukturellen Rahmenbedingungen entsprechend angepasst werden.\"</div>\r\n          <div class=\"example-item lv-c1\">„Ich schlage vor, das weitere Vorgehen in drei klar definierte Phasen zu gliedern, um Transparenz und Effizienz sicherzustellen.\"</div>\r\n        </div>\r\n      </div>\r\n      <div class=\"time-badge\">⏱ Orientierung: 800–1.000 UE à 45 Min. (ab Null)</div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- ─── C2 ─── -->\r\n  <div class=\"level-card lv-c2\" id=\"lv-c2\">\r\n    <div class=\"card-header\" onclick=\"toggleCard('lv-c2')\">\r\n      <div class=\"level-badge\">C2</div>\r\n      <div>\r\n        <p class=\"card-title\">Meisterliche Sprachbeherrschung</p>\r\n        <p class=\"card-subtitle\">„Nahezu wie ein Muttersprachler\" · Funktionale Perfektion</p>\r\n      </div>\r\n      <div class=\"card-toggle\">▾</div>\r\n    </div>\r\n    <div class=\"card-body\">\r\n      <p class=\"card-description lv-c2\">\r\n        C2 ist die höchste Stufe des GER/CEFR. Du kannst auf diesem Niveau <strong>praktisch alles, was du hörst oder liest, mühelos verstehen</strong>. Du kannst Informationen aus verschiedenen schriftlichen und mündlichen Quellen zusammenfassen und dabei Begründungen und Erklärungen in einer zusammenhängenden Darstellung wiedergeben. Du kannst dich spontan, sehr flüssig und genau ausdrücken und dabei auch bei komplexeren Sachverhalten feinere Bedeutungsnuancen deutlich machen. C2 ist nicht gleichbedeutend mit Muttersprachlichkeit und garantiert kein Fachwissen; es beschreibt sehr hohe kommunikative Kompetenz.\r\n      </p>\r\n      <div class=\"card-grid\">\r\n        <div class=\"card-block\">\r\n          <h4>Was du kannst</h4>\r\n          <ul>\r\n            <li>Praktisch jeden Text und jede Rede verstehen und zusammenfassen</li>\r\n            <li>Spontan, flüssig, präzise und stilistisch sehr sicher sprechen</li>\r\n            <li>Komplexe Inhalte präzise und komprimiert wiedergeben</li>\r\n            <li>Missverständnisse elegant vermeiden – diplomatisch und präzise</li>\r\n            <li>Ironie, Wortspiele, Humor und kulturelle Anspielungen erkennen und einsetzen</li>\r\n            <li>Sich je nach Zielgruppe flexibel ausdrücken (von umgangssprachlich bis hochformell)</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"card-block\">\r\n          <h4>Typische Themen</h4>\r\n          <ul>\r\n            <li>Ein sehr breites Themenspektrum – von Alltag bis Wissenschaft</li>\r\n            <li>Feine gesellschaftliche und kulturelle Phänomene</li>\r\n            <li>Fachterminologie im eigenen Wissens- und Arbeitsbereich</li>\r\n            <li>Rhetorik, Überzeugung, Verhandlung auf höchstem Niveau</li>\r\n            <li>Literatur, Philosophie, Kunst</li>\r\n          </ul>\r\n        </div>\r\n        <div class=\"card-block card-block-full\">\r\n          <h4>Merkmale der Sprachkompetenz</h4>\r\n          <div class=\"grammar-tags\">\r\n            <span class=\"grammar-tag\">Höchste stilistische Präzision</span>\r\n            <span class=\"grammar-tag\">Sehr breites idiomatisches Repertoire</span>\r\n            <span class=\"grammar-tag\">Flexible Anpassung an jede Zielgruppe</span>\r\n            <span class=\"grammar-tag\">Nuancierte, differenzierte Argumentation</span>\r\n            <span class=\"grammar-tag\">Ironie und Humor (Verständnis &amp; Einsatz)</span>\r\n            <span class=\"grammar-tag\">Durchgehend hohe grammatische Kontrolle</span>\r\n            <span class=\"grammar-tag\">Souveräner Umgang mit Tabuthemen und heiklen Situationen</span>\r\n          </div>\r\n        </div>\r\n        <div class=\"card-block\">\r\n          <h4>Kleiner Selbsttest</h4>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich kann einen schwierigen Text präzise zusammenfassen, ohne Nuancen zu verlieren.</span></div>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich finde auch in heiklen Gesprächen die genau passende Formulierung.</span></div>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich kann Register und Ton sehr genau an Situation und Zielgruppe anpassen.</span></div>\r\n          <div class=\"selftest-item\"><div class=\"selftest-check\"></div><span>Ich erkenne Ironie, Stil und kulturelle Referenzen ohne Probleme.</span></div>\r\n        </div>\r\n        <div class=\"card-block\">\r\n          <h4>Beispielsätze</h4>\r\n          <div class=\"example-item lv-c2\">„Der Kernpunkt ist weniger die Maßnahme selbst als die Art und Weise, wie sie kommuniziert, wahrgenommen und letztlich in der öffentlichen Debatte verankert wird.\"</div>\r\n          <div class=\"example-item lv-c2\">„Gestatten Sie mir, das zu präzisieren: Es geht nicht um X per se, sondern um die systemischen Implikationen, die Y langfristig nach sich zieht.\"</div>\r\n        </div>\r\n      </div>\r\n      <div class=\"time-badge\">⏱ Orientierung: mindestens 1.000 UE à 45 Min. (ab Null)</div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- ════════════════════ SELF-ASSESSMENT ════════════════════ -->\r\n  <div class=\"section-header\"><h2>Wie du dein Niveau einschätzt</h2></div>\r\n\r\n  <p style=\"color:var(--muted); margin-bottom:24px; font-size:0.96rem; line-height:1.75;\">\r\n    Bewerte dich <strong style=\"color:var(--text)\">getrennt in vier Kompetenzbereichen</strong>. Sprachprofile sind oft ungleichmäßig: Eine Person kann zum Beispiel auf B2 lesen und auf B1 sprechen. Es gibt keine allgemeine GER-Regel, nach der drei von vier Fertigkeiten automatisch ein Gesamtniveau ergeben. Für Kurs- oder Prüfungsentscheidungen gelten die Einstufungs- und Bewertungsregeln des jeweiligen Anbieters.\r\n  </p>\r\n\r\n  <div class=\"assessment-grid\">\r\n    <div class=\"ag-cell\">\r\n      <div class=\"ag-icon\">🎧</div>\r\n      <div class=\"ag-label\">Hören</div>\r\n      <div class=\"ag-desc\">Verstehst du gesprochene Sprache, Nachrichten, Podcasts und Filme?</div>\r\n    </div>\r\n    <div class=\"ag-cell\">\r\n      <div class=\"ag-icon\">📖</div>\r\n      <div class=\"ag-label\">Lesen</div>\r\n      <div class=\"ag-desc\">Verstehst du Briefe, Artikel, Verträge und Anleitungen?</div>\r\n    </div>\r\n    <div class=\"ag-cell\">\r\n      <div class=\"ag-icon\">🗣</div>\r\n      <div class=\"ag-label\">Sprechen</div>\r\n      <div class=\"ag-desc\">Kannst du spontan reagieren, erzählen und argumentieren?</div>\r\n    </div>\r\n    <div class=\"ag-cell\">\r\n      <div class=\"ag-icon\">✍️</div>\r\n      <div class=\"ag-label\">Schreiben</div>\r\n      <div class=\"ag-desc\">Kannst du klare, korrekte und situationsgerechte Texte verfassen?</div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- ════════════════════ PRÜFUNGEN ════════════════════ -->\r\n  <div class=\"section-header\"><h2>Offizielle Prüfungen und Zertifikate</h2></div>\r\n\r\n  <p style=\"color:var(--muted); margin-bottom:20px; font-size:0.95rem; line-height:1.75;\">\r\n    Die folgende Tabelle ordnet verbreitete Deutschprüfungen nach GER-Niveau ein. Ob ein Zertifikat für Visum, Aufenthalt, Einbürgerung, Studium oder Beruf anerkannt wird, entscheidet immer die zuständige Stelle; Niveau und Prüfungsanbieter sind nicht automatisch austauschbar.\r\n  </p>\r\n\r\n  <table class=\"exams-table\">\r\n    <thead>\r\n      <tr>\r\n        <th>Niveau</th>\r\n        <th>Goethe-Institut</th>\r\n        <th>ÖSD (Österreich)</th>\r\n        <th>telc</th>\r\n        <th>Wozu wird es benötigt?</th>\r\n      </tr>\r\n    </thead>\r\n    <tbody>\r\n      <tr>\r\n        <td><strong style=\"color:var(--a1)\">A1</strong></td>\r\n        <td>Goethe-Zertifikat A1</td>\r\n        <td>ÖSD Zertifikat A1</td>\r\n        <td>telc Deutsch A1</td>\r\n        <td>Kann je nach Verfahren als Sprachnachweis dienen, z. B. beim Ehegattennachzug; anerkannte Prüfung vorher prüfen</td>\r\n      </tr>\r\n      <tr>\r\n        <td><strong style=\"color:var(--a2)\">A2</strong></td>\r\n        <td>Goethe-Zertifikat A2</td>\r\n        <td>ÖSD Zertifikat A2</td>\r\n        <td>telc Deutsch A2</td>\r\n        <td>Elementare Alltags- und Berufskommunikation; in einzelnen Aufenthalts- oder Ausbildungsverfahren relevant</td>\r\n      </tr>\r\n      <tr>\r\n        <td><strong style=\"color:var(--b1)\">B1</strong></td>\r\n        <td>Goethe-Zertifikat B1</td>\r\n        <td>ÖSD Zertifikat B1</td>\r\n        <td>telc Deutsch B1</td>\r\n        <td>U. a. allgemeine Niederlassungserlaubnis DE, Modul 2 für Daueraufenthalt–EU AT; Schweiz: Einbürgerung mindestens B1 mündlich/A2 schriftlich</td>\r\n      </tr>\r\n      <tr>\r\n        <td><strong style=\"color:var(--b2)\">B2</strong></td>\r\n        <td>Goethe-Zertifikat B2</td>\r\n        <td>ÖSD Zertifikat B2</td>\r\n        <td>telc Deutsch B2</td>\r\n        <td>Von einigen Hochschulen akzeptiert; bei reglementierten Berufen gelten berufs- und behördenspezifische Anforderungen</td>\r\n      </tr>\r\n      <tr>\r\n        <td><strong style=\"color:var(--c1)\">C1</strong></td>\r\n        <td>Goethe-Zertifikat C1</td>\r\n        <td>ÖSD Zertifikat C1</td>\r\n        <td>telc Deutsch C1 Hochschule</td>\r\n        <td>Häufiges Zielniveau für deutschsprachige Studiengänge; akzeptierte Zertifikate unterscheiden sich je Hochschule</td>\r\n      </tr>\r\n      <tr>\r\n        <td><strong style=\"color:var(--c2)\">C2</strong></td>\r\n        <td>Goethe-Zertifikat C2 (GDS)</td>\r\n        <td>ÖSD Zertifikat C2</td>\r\n        <td>telc Deutsch C2</td>\r\n        <td>Höchste GER-Stufe; konkrete berufliche oder akademische Anerkennung bei der zuständigen Stelle prüfen</td>\r\n      </tr>\r\n    </tbody>\r\n  </table>\r\n\r\n  <!-- ════════════════════ LERNTIPPS ════════════════════ -->\r\n  <div class=\"section-header\"><h2>Tipps für effektives Lernen</h2></div>\r\n\r\n  <div class=\"tips-grid\">\r\n    <div class=\"tip-card\">\r\n      <div class=\"tip-icon\">🎯</div>\r\n      <div class=\"tip-title\">Täglich lernen – auch nur 15 Minuten</div>\r\n      <div class=\"tip-desc\">Kurze, regelmäßige Lernphasen erleichtern Wiederholung und Routine. Entscheidend ist, dass du aktiv abrufst, anwendest und genügend Pausen einplanst.</div>\r\n    </div>\r\n    <div class=\"tip-card\">\r\n      <div class=\"tip-icon\">📻</div>\r\n      <div class=\"tip-title\">Echte Sprache hören</div>\r\n      <div class=\"tip-desc\">Ab A2 regelmäßig Podcasts, „Slow German\", Deutsche Welle oder Radionachrichten hören. Das schult das Hörverständnis für echte Sprechsituationen – nicht nur für den Unterricht.</div>\r\n    </div>\r\n    <div class=\"tip-card\">\r\n      <div class=\"tip-icon\">📝</div>\r\n      <div class=\"tip-title\">Vokabelheft mit Kontext führen</div>\r\n      <div class=\"tip-desc\">Notiere neue Wörter mit einem passenden Beispielsatz, typischen Wortverbindungen und – bei Nomen – Artikel und Plural. So lernst du Bedeutung und Gebrauch zusammen.</div>\r\n    </div>\r\n    <div class=\"tip-card\">\r\n      <div class=\"tip-icon\">💬</div>\r\n      <div class=\"tip-title\">Vom ersten Tag an sprechen</div>\r\n      <div class=\"tip-desc\">Warte nicht auf das „richtige Niveau\". Fehler sind kein Zeichen von Schwäche – sie sind Lernmaterial. Nur wer spricht, lernt wirklich sprechen. Mut zahlt sich aus.</div>\r\n    </div>\r\n    <div class=\"tip-card\">\r\n      <div class=\"tip-icon\">🎮</div>\r\n      <div class=\"tip-title\">Im Kontext eintauchen</div>\r\n      <div class=\"tip-desc\">Serien mit deutschen Untertiteln schauen, auf Deutsch spielen, Bücher lesen – alles ist Sprachkontakt. Je natürlicher der Kontext, desto tiefer verankert sich die Sprache.</div>\r\n    </div>\r\n    <div class=\"tip-card\">\r\n      <div class=\"tip-icon\">🗂</div>\r\n      <div class=\"tip-title\">Ein Niveau – ein Fokus</div>\r\n      <div class=\"tip-desc\">Setze einen Schwerpunkt auf Aufgaben deines aktuellen Niveaus. Anspruchsvollere Inhalte dürfen vorkommen, sollten aber das systematische Üben der nächsten Lernziele nicht verdrängen.</div>\r\n    </div>\r\n    <div class=\"tip-card\">\r\n      <div class=\"tip-icon\">🔁</div>\r\n      <div class=\"tip-title\">Wiederholen mit System (Spaced Repetition)</div>\r\n      <div class=\"tip-desc\">Verteilte Wiederholung und aktives Abrufen können das langfristige Behalten unterstützen. Karteikarten-Apps sind dafür ein mögliches Werkzeug, wenn du Beispiele und Anwendung mitlernst.</div>\r\n    </div>\r\n    <div class=\"tip-card\">\r\n      <div class=\"tip-icon\">🧑‍🤝‍🧑</div>\r\n      <div class=\"tip-title\">Tandempartner suchen</div>\r\n      <div class=\"tip-desc\">Ein Sprachpartner, der Deutsch als Muttersprache spricht und deine Sprache lernen möchte, ist unbezahlbar. Plattformen wie Tandem, HelloTalk oder lokale Sprachcafés helfen.</div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"notice\" style=\"margin-top:4px;\">\r\n    <strong>Hinweis zu den Zeitangaben:</strong> Die Werte sind kumulative Orientierungsbereiche des Goethe-Instituts in Unterrichtseinheiten à 45 Minuten, keine Vorgaben des Europarats. Die Bereiche überlappen und hängen unter anderem von Vorkenntnissen, Lernzielen, Unterrichtsqualität, Übungszeit und individueller Lernerfahrung ab. Der GER beschreibt Kompetenzen, nicht eine feste Zahl an Lernstunden.\r\n  </div>\r\n\r\n</div>\r\n\r\n<!-- ════════════════════ FOOTER ════════════════════ -->\r\n<footer>\r\n  <p>Quellen: <a href=\"https://www.coe.int/en/web/common-european-framework-reference-languages\" target=\"_blank\" rel=\"noopener noreferrer\">Europarat – GER/CEFR</a> · <a href=\"https://www.goethe.de/de/spr/prf.html\" target=\"_blank\" rel=\"noopener noreferrer\">Goethe-Institut – Prüfungen A1–C2</a> · <a href=\"https://www.osd.at/die-pruefungen/osd-prufungen/\" target=\"_blank\" rel=\"noopener noreferrer\">ÖSD-Prüfungen</a> · <a href=\"https://www.telc.net/sprachpruefungen/zertifikatspruefung/deutsch/\" target=\"_blank\" rel=\"noopener noreferrer\">telc Deutsch-Prüfungen</a></p>\r\n  <p style=\"margin-top:6px;\">Inhalt redaktionell geprüft: 13. August 2026 · Anerkennungsregeln können sich ändern</p>\n  <p style=\"margin-top:6px;\"><a href=\"/impressum\">Impressum</a> · <a href=\"/privacy\">Datenschutz</a> · <a href=\"/contact\">Kontakt</a></p>\r\n</footer>\r\n\r\n<script>\r\n  function toggleCard(id) {\r\n    const card = document.getElementById(id);\r\n    card.classList.toggle('open');\r\n  }\r\n  document.getElementById('lv-a1').classList.add('open');\r\n</script>\r\n\r\n",
    "styles": "\r\n  .dq-article-document {\r\n    --bg: #0b1220;\r\n    --surface: rgba(15, 23, 42, 0.72);\r\n    --surface-strong: rgba(8, 15, 31, 0.86);\r\n    --surface-soft: rgba(15, 23, 42, 0.52);\r\n    --border: rgba(148, 163, 184, 0.18);\r\n    --text: #eaf2ff;\r\n    --muted: #a9b7c9;\r\n    --accent: #facc15;\r\n    --shadow: 0 24px 60px rgba(2, 6, 23, 0.26);\r\n\r\n    --a0: #9b9b9b;\r\n    --a1: #6ec6e0;\r\n    --a2: #4db8a8;\r\n    --b1: #7ec86e;\r\n    --b2: #c8b84e;\r\n    --c1: #e07848;\r\n    --c2: #d04870;\r\n\r\n    --a0-bg: rgba(155,155,155,0.08);\r\n    --a1-bg: rgba(110,198,224,0.08);\r\n    --a2-bg: rgba(77,184,168,0.08);\r\n    --b1-bg: rgba(126,200,110,0.08);\r\n    --b2-bg: rgba(200,184,78,0.08);\r\n    --c1-bg: rgba(224,120,72,0.08);\r\n    --c2-bg: rgba(208,72,112,0.08);\r\n  }\r\n\r\n  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\r\n\r\n  .dq-article-document {\r\n    background:\r\n      radial-gradient(circle at top, rgba(250,204,21,0.12), transparent 28%),\r\n      radial-gradient(circle at 85% 18%, rgba(110,198,224,0.08), transparent 24%),\r\n      linear-gradient(180deg, #07111f 0%, var(--bg) 100%);\r\n    color: var(--text);\r\n    font-family: 'Source Sans 3', sans-serif;\r\n    font-weight: 400;\r\n    line-height: 1.78;\r\n    min-height: 100vh;\r\n  }\r\n\r\n  /* ── HERO ── */\r\n  .hero {\r\n    position: relative;\r\n    padding: 88px 24px 64px;\r\n    text-align: center;\r\n    overflow: hidden;\r\n  }\r\n  .hero::before {\r\n    content: '';\r\n    position: absolute;\r\n    inset: 0;\r\n    background:\r\n      radial-gradient(ellipse 80% 60% at 50% 0%, rgba(250,204,21,0.15) 0%, transparent 70%),\r\n      radial-gradient(ellipse 50% 40% at 80% 80%, rgba(208,72,112,0.08) 0%, transparent 60%);\r\n    pointer-events: none;\r\n  }\r\n  .hero-eyebrow {\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 12px;\r\n    letter-spacing: 0.22em;\r\n    text-transform: uppercase;\r\n    color: var(--accent);\r\n    margin-bottom: 18px;\r\n    opacity: 0;\r\n    animation: fadeUp 0.6s ease 0.1s forwards;\r\n  }\r\n  .hero h1 {\r\n    font-family: 'Playfair Display', serif;\r\n    font-size: clamp(2.4rem, 6vw, 4.8rem);\r\n    font-weight: 900;\r\n    line-height: 1.1;\r\n    margin-bottom: 22px;\r\n    opacity: 0;\r\n    animation: fadeUp 0.6s ease 0.25s forwards;\r\n  }\r\n  .hero h1 em { font-style: normal; color: var(--accent); }\r\n  .hero-sub {\r\n    max-width: 660px;\r\n    margin: 0 auto 44px;\r\n    color: var(--muted);\r\n    font-size: 1.08rem;\r\n    line-height: 1.8;\r\n    opacity: 0;\r\n    animation: fadeUp 0.6s ease 0.4s forwards;\r\n  }\r\n\r\n  /* ── LEVEL STRIP ── */\r\n  .level-strip {\r\n    display: flex;\r\n    justify-content: center;\r\n    flex-wrap: wrap;\r\n    gap: 7px;\r\n    margin-bottom: 10px;\r\n    opacity: 0;\r\n    animation: fadeUp 0.6s ease 0.55s forwards;\r\n  }\r\n  .level-pill {\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 13px;\r\n    font-weight: 600;\r\n    padding: 5px 16px;\r\n    border-radius: 20px;\r\n    border: 1.5px solid currentColor;\r\n  }\r\n  .pill-a0 { color: var(--a0); }\r\n  .pill-a1 { color: var(--a1); }\r\n  .pill-a2 { color: var(--a2); }\r\n  .pill-b1 { color: var(--b1); }\r\n  .pill-b2 { color: var(--b2); }\r\n  .pill-c1 { color: var(--c1); }\r\n  .pill-c2 { color: var(--c2); }\r\n\r\n  .group-label {\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 10px;\r\n    letter-spacing: 0.18em;\r\n    color: var(--muted);\r\n    text-align: center;\r\n    margin-bottom: 36px;\r\n    opacity: 0;\r\n    animation: fadeUp 0.6s ease 0.65s forwards;\r\n  }\r\n\r\n  /* ── CEFR SUMMARY BAR ── */\r\n  .cefr-bar {\r\n    max-width: 860px;\r\n    margin: 0 auto 0;\r\n    display: grid;\r\n    grid-template-columns: 1fr 1fr 1fr;\r\n    border: 1px solid var(--border);\r\n    border-radius: 14px;\r\n    overflow: hidden;\r\n    background: rgba(2, 6, 23, 0.32);\r\n    box-shadow: var(--shadow);\r\n    opacity: 0;\r\n    animation: fadeUp 0.6s ease 0.75s forwards;\r\n  }\r\n  @media (max-width: 600px) { .cefr-bar { grid-template-columns: 1fr; } }\r\n  .cefr-group {\r\n    background: var(--surface-soft);\r\n    padding: 22px 26px;\r\n    border-right: 1px solid var(--border);\r\n    text-align: center;\r\n  }\r\n  .cefr-group:last-child { border-right: none; }\r\n  .cefr-group-label {\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 11px;\r\n    letter-spacing: 0.15em;\r\n    text-transform: uppercase;\r\n    color: var(--muted);\r\n    margin-bottom: 7px;\r\n  }\r\n  .cefr-group-title {\r\n    font-family: 'Playfair Display', serif;\r\n    font-size: 1.12rem;\r\n    font-weight: 700;\r\n    margin-bottom: 5px;\r\n  }\r\n  .cefr-group-sub { font-size: 0.82rem; color: var(--muted); }\r\n  .cefr-group.elementary .cefr-group-title { color: var(--a1); }\r\n  .cefr-group.independent .cefr-group-title { color: var(--b1); }\r\n  .cefr-group.proficient .cefr-group-title { color: var(--c1); }\r\n\r\n  /* ── MAIN CONTAINER ── */\r\n  .container {\r\n    max-width: 880px;\r\n    margin: 0 auto;\r\n    padding: 0 24px 88px;\r\n  }\r\n\r\n  /* ── SECTION HEADER ── */\r\n  .section-header {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 16px;\r\n    margin: 60px 0 32px;\r\n  }\r\n  .section-header::after {\r\n    content: '';\r\n    flex: 1;\r\n    height: 1px;\r\n    background: var(--border);\r\n  }\r\n  .section-header h2 {\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 11px;\r\n    letter-spacing: 0.2em;\r\n    text-transform: uppercase;\r\n    color: var(--muted);\r\n    white-space: nowrap;\r\n  }\r\n\r\n  /* ── LEVEL CARD ── */\r\n  .level-card {\r\n    background: linear-gradient(180deg, rgba(15, 23, 42, 0.72), rgba(8, 15, 31, 0.78));\r\n    border: 1px solid var(--border);\r\n    border-radius: 16px;\r\n    overflow: hidden;\r\n    margin-bottom: 28px;\r\n    box-shadow: var(--shadow);\r\n    backdrop-filter: blur(14px);\r\n    opacity: 0;\r\n    animation: fadeUp 0.5s ease forwards;\r\n    transition: border-color 0.25s;\r\n  }\r\n  .level-card:nth-child(1) { animation-delay: 0.05s; }\r\n  .level-card:nth-child(2) { animation-delay: 0.12s; }\r\n  .level-card:nth-child(3) { animation-delay: 0.19s; }\r\n  .level-card:nth-child(4) { animation-delay: 0.26s; }\r\n  .level-card:nth-child(5) { animation-delay: 0.33s; }\r\n  .level-card:nth-child(6) { animation-delay: 0.40s; }\r\n  .level-card:nth-child(7) { animation-delay: 0.47s; }\r\n\r\n  .card-header {\r\n    display: grid;\r\n    grid-template-columns: auto 1fr auto;\r\n    align-items: center;\r\n    gap: 20px;\r\n    padding: 26px 30px 22px;\r\n    cursor: pointer;\r\n    user-select: none;\r\n  }\r\n  .level-badge {\r\n    font-family: 'Playfair Display', serif;\r\n    font-size: 2.4rem;\r\n    font-weight: 900;\r\n    line-height: 1;\r\n    width: 68px;\r\n    text-align: center;\r\n  }\r\n  .card-title {\r\n    font-family: 'Playfair Display', serif;\r\n    font-size: 1.35rem;\r\n    font-weight: 700;\r\n    line-height: 1.2;\r\n    margin-bottom: 5px;\r\n  }\r\n  .card-subtitle { font-size: 0.86rem; color: var(--muted); }\r\n  .card-toggle {\r\n    font-size: 22px;\r\n    color: var(--muted);\r\n    transition: transform 0.3s;\r\n    line-height: 1;\r\n  }\r\n  .level-card.open .card-toggle { transform: rotate(180deg); }\r\n\r\n  .card-body {\r\n    padding: 0 30px;\r\n    max-height: 0;\r\n    overflow: hidden;\r\n    transition: max-height 0.5s ease, padding 0.3s ease;\r\n  }\r\n  .level-card.open .card-body {\r\n    max-height: 3000px;\r\n    padding-bottom: 30px;\r\n  }\r\n\r\n  /* ── DESCRIPTION PARAGRAPH ── */\r\n  .card-description {\r\n    font-size: 0.97rem;\r\n    color: var(--text);\r\n    margin-bottom: 24px;\r\n    line-height: 1.8;\r\n    padding: 16px 20px;\r\n    background: rgba(8, 15, 31, 0.76);\r\n    border-radius: 10px;\r\n    border: 1px solid var(--border);\r\n    border-left: 3px solid currentColor;\r\n  }\r\n\r\n  .card-grid {\r\n    display: grid;\r\n    grid-template-columns: 1fr 1fr;\r\n    gap: 20px;\r\n    margin-bottom: 20px;\r\n  }\r\n  @media (max-width: 640px) {\r\n    .card-grid { grid-template-columns: 1fr; }\r\n    .card-header { gap: 12px; padding: 20px 20px 18px; }\r\n    .card-body { padding: 0 20px; }\r\n    .level-card.open .card-body { padding-bottom: 20px; }\r\n  }\r\n\r\n  .card-block {\r\n    background: var(--surface-strong);\r\n    border: 1px solid var(--border);\r\n    border-radius: 10px;\r\n    padding: 18px 20px;\r\n  }\r\n  .card-block h4 {\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 10px;\r\n    letter-spacing: 0.18em;\r\n    text-transform: uppercase;\r\n    color: #cbd5e1;\r\n    margin-bottom: 13px;\r\n  }\r\n  .card-block ul {\r\n    list-style: none;\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 8px;\r\n  }\r\n  .card-block ul li {\r\n    font-size: 0.91rem;\r\n    padding-left: 20px;\r\n    position: relative;\r\n    color: var(--text);\r\n    line-height: 1.72;\r\n  }\r\n  .card-block ul li::before {\r\n    content: '→';\r\n    position: absolute;\r\n    left: 0;\r\n    font-size: 0.75rem;\r\n    top: 2px;\r\n  }\r\n  .card-block-full { grid-column: 1 / -1; }\r\n\r\n  .grammar-tags {\r\n    display: flex;\r\n    flex-wrap: wrap;\r\n    gap: 8px;\r\n  }\r\n  .grammar-tag {\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 11px;\r\n    padding: 4px 11px;\r\n    border-radius: 6px;\r\n    background: rgba(15, 23, 42, 0.84);\r\n    border: 1px solid var(--border);\r\n    color: #dbe7f5;\r\n  }\r\n\r\n  .example-item {\r\n    font-family: 'Playfair Display', serif;\r\n    font-size: 0.97rem;\r\n    font-style: italic;\r\n    color: var(--text);\r\n    padding: 9px 15px;\r\n    border-left: 2.5px solid currentColor;\r\n    margin-bottom: 9px;\r\n    background: rgba(8, 15, 31, 0.82);\r\n    border: 1px solid var(--border);\r\n    border-radius: 0 7px 7px 0;\r\n    line-height: 1.6;\r\n  }\r\n  .example-item .translation {\r\n    display: block;\r\n    font-family: 'Source Sans 3', sans-serif;\r\n    font-style: normal;\r\n    font-size: 0.8rem;\r\n    color: #c8d5e7;\r\n    margin-top: 3px;\r\n  }\r\n\r\n  .selftest-item {\r\n    display: flex;\r\n    align-items: flex-start;\r\n    gap: 10px;\r\n    font-size: 0.91rem;\r\n    margin-bottom: 9px;\r\n    line-height: 1.7;\r\n    color: var(--text);\r\n  }\r\n  .selftest-check {\r\n    width: 20px;\r\n    height: 20px;\r\n    border: 1.5px solid var(--border);\r\n    border-radius: 5px;\r\n    flex-shrink: 0;\r\n    margin-top: 2px;\r\n  }\r\n\r\n  .time-badge {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    gap: 7px;\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 11px;\r\n    color: #dbe7f5;\r\n    background: rgba(8, 15, 31, 0.88);\r\n    border: 1px solid var(--border);\r\n    border-radius: 7px;\r\n    padding: 5px 12px;\r\n    margin-top: 14px;\r\n  }\r\n\r\n  /* ── LEVEL COLORS ── */\r\n  .lv-a0 { color: var(--a0); border-color: rgba(155,155,155,0.2); }\r\n  .lv-a1 { color: var(--a1); border-color: rgba(110,198,224,0.2); }\r\n  .lv-a2 { color: var(--a2); border-color: rgba(77,184,168,0.2); }\r\n  .lv-b1 { color: var(--b1); border-color: rgba(126,200,110,0.2); }\r\n  .lv-b2 { color: var(--b2); border-color: rgba(200,184,78,0.2); }\r\n  .lv-c1 { color: var(--c1); border-color: rgba(224,120,72,0.2); }\r\n  .lv-c2 { color: var(--c2); border-color: rgba(208,72,112,0.2); }\r\n\r\n  .level-card.lv-a0:hover { border-color: var(--a0); }\r\n  .level-card.lv-a1:hover { border-color: var(--a1); }\r\n  .level-card.lv-a2:hover { border-color: var(--a2); }\r\n  .level-card.lv-b1:hover { border-color: var(--b1); }\r\n  .level-card.lv-b2:hover { border-color: var(--b2); }\r\n  .level-card.lv-c1:hover { border-color: var(--c1); }\r\n  .level-card.lv-c2:hover { border-color: var(--c2); }\r\n\r\n  .example-item.lv-a0 { border-color: var(--a0); }\r\n  .example-item.lv-a1 { border-color: var(--a1); }\r\n  .example-item.lv-a2 { border-color: var(--a2); }\r\n  .example-item.lv-b1 { border-color: var(--b1); }\r\n  .example-item.lv-b2 { border-color: var(--b2); }\r\n  .example-item.lv-c1 { border-color: var(--c1); }\r\n  .example-item.lv-c2 { border-color: var(--c2); }\r\n\r\n  .card-description.lv-a0 { border-color: var(--a0); }\r\n  .card-description.lv-a1 { border-color: var(--a1); }\r\n  .card-description.lv-a2 { border-color: var(--a2); }\r\n  .card-description.lv-b1 { border-color: var(--b1); }\r\n  .card-description.lv-b2 { border-color: var(--b2); }\r\n  .card-description.lv-c1 { border-color: var(--c1); }\r\n  .card-description.lv-c2 { border-color: var(--c2); }\r\n\r\n  /* ── PROGRESS BAR ── */\r\n  .progress-track {\r\n    max-width: 860px;\r\n    margin: 0 auto 68px;\r\n    padding: 28px 24px 0;\r\n    opacity: 0;\r\n    animation: fadeUp 0.6s ease 0.85s forwards;\r\n  }\r\n  .progress-bar {\r\n    display: flex;\r\n    height: 8px;\r\n    border-radius: 4px;\r\n    overflow: hidden;\r\n    margin-bottom: 10px;\r\n  }\r\n  .pb-seg { height: 100%; }\r\n  .pb-a0 { flex: 1; background: var(--a0); }\r\n  .pb-a1 { flex: 1.2; background: var(--a1); }\r\n  .pb-a2 { flex: 1.4; background: var(--a2); }\r\n  .pb-b1 { flex: 1.6; background: var(--b1); }\r\n  .pb-b2 { flex: 1.8; background: var(--b2); }\r\n  .pb-c1 { flex: 2; background: var(--c1); }\r\n  .pb-c2 { flex: 2.2; background: var(--c2); }\r\n  .progress-labels {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 10px;\r\n    color: var(--muted);\r\n  }\r\n\r\n  /* ── ASSESSMENT GRID ── */\r\n  .assessment-grid {\r\n    display: grid;\r\n    grid-template-columns: repeat(4, 1fr);\r\n    gap: 1px;\r\n    background: var(--border);\r\n    border: 1px solid var(--border);\r\n    border-radius: 12px;\r\n    overflow: hidden;\r\n    margin-bottom: 28px;\r\n  }\r\n  @media (max-width: 600px) { .assessment-grid { grid-template-columns: 1fr 1fr; } }\r\n  .ag-cell {\r\n    background: var(--surface-strong);\r\n    padding: 22px 16px;\r\n    text-align: center;\r\n  }\r\n  .ag-icon { font-size: 30px; margin-bottom: 10px; }\r\n  .ag-label {\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 10px;\r\n    letter-spacing: 0.15em;\r\n    text-transform: uppercase;\r\n    color: var(--accent);\r\n    margin-bottom: 7px;\r\n  }\r\n  .ag-desc { font-size: 0.83rem; color: #cfdbeb; line-height: 1.65; }\r\n\r\n  /* ── EXAMS TABLE ── */\r\n  .exams-table {\r\n    width: 100%;\r\n    border-collapse: separate;\r\n    border-spacing: 0;\r\n    margin-bottom: 28px;\r\n    font-size: 0.88rem;\r\n    border: 1px solid var(--border);\r\n    border-radius: 12px;\r\n    overflow: hidden;\r\n    background: rgba(8, 15, 31, 0.56);\r\n  }\r\n  .exams-table th {\r\n    font-family: 'JetBrains Mono', monospace;\r\n    font-size: 10px;\r\n    letter-spacing: 0.15em;\r\n    text-transform: uppercase;\r\n    color: #dbe7f5;\r\n    text-align: left;\r\n    padding: 13px 16px;\r\n    border-bottom: 1px solid var(--border);\r\n    background: rgba(15, 23, 42, 0.9);\r\n  }\r\n  .exams-table td {\r\n    padding: 13px 16px;\r\n    border-bottom: 1px solid var(--border);\r\n    vertical-align: top;\r\n    line-height: 1.65;\r\n    color: #d7e4f4;\r\n    background: rgba(8, 15, 31, 0.72);\r\n  }\r\n  .exams-table tr:last-child td { border-bottom: none; }\r\n  .exams-table tr:hover td { background: rgba(255,255,255,0.04); }\r\n\r\n  /* ── TIPS GRID ── */\r\n  .tips-grid {\r\n    display: grid;\r\n    grid-template-columns: 1fr 1fr;\r\n    gap: 16px;\r\n    margin-bottom: 28px;\r\n  }\r\n  @media (max-width: 600px) { .tips-grid { grid-template-columns: 1fr; } }\r\n  .tip-card {\r\n    background: var(--surface-strong);\r\n    border: 1px solid var(--border);\r\n    border-radius: 12px;\r\n    padding: 22px;\r\n    box-shadow: var(--shadow);\r\n  }\r\n  .tip-icon { font-size: 26px; margin-bottom: 12px; }\r\n  .tip-title {\r\n    font-family: 'Source Sans 3', sans-serif;\r\n    font-weight: 600;\r\n    font-size: 0.97rem;\r\n    margin-bottom: 7px;\r\n  }\r\n  .tip-desc { font-size: 0.86rem; color: #cfdbeb; line-height: 1.72; }\r\n\r\n  /* ── NOTICE BOX ── */\r\n  .notice {\r\n    background: rgba(250,204,21,0.1);\r\n    border: 1px solid rgba(250,204,21,0.2);\r\n    border-radius: 10px;\r\n    padding: 18px 22px;\r\n    font-size: 0.89rem;\r\n    color: #e6edf8;\r\n    margin-bottom: 28px;\r\n    line-height: 1.75;\r\n  }\r\n  .notice strong { color: var(--accent); }\n\n  /* ── QUICK ANSWER ── */\n  .quick-answer {\n    max-width: 880px;\n    margin: 0 auto 52px;\n    padding: 30px;\n    border: 1px solid rgba(77,184,168,0.3);\n    border-radius: 18px;\n    background: linear-gradient(145deg, rgba(77,184,168,0.12), rgba(15,15,19,0.96));\n    box-shadow: 0 22px 55px rgba(0,0,0,0.22);\n  }\n  .quick-answer-label {\n    margin-bottom: 8px;\n    font-family: 'JetBrains Mono', monospace;\n    font-size: 10px;\n    font-weight: 700;\n    letter-spacing: 0.18em;\n    text-transform: uppercase;\n    color: var(--accent);\n  }\n  .quick-answer h2 {\n    margin-bottom: 12px;\n    font-family: 'Playfair Display', serif;\n    font-size: clamp(1.65rem, 4vw, 2.35rem);\n    line-height: 1.2;\n  }\n  .quick-answer-lead { color: var(--text); font-size: 1rem; line-height: 1.75; }\n  .quick-answer-table-wrap { margin-top: 22px; overflow-x: auto; }\n  .quick-answer-table { width: 100%; border-collapse: collapse; font-size: 0.9rem; }\n  .quick-answer-table th,\n  .quick-answer-table td { padding: 12px 14px; border-bottom: 1px solid var(--border); text-align: left; vertical-align: top; }\n  .quick-answer-table th { color: var(--accent); font-size: 0.78rem; letter-spacing: 0.05em; text-transform: uppercase; }\n  .quick-answer-table td { color: var(--muted); line-height: 1.55; }\n  .quick-answer-question { margin-top: 20px; }\n  .quick-answer-question h3 { margin-bottom: 6px; font-size: 1.05rem; }\n  .quick-answer-question p { color: var(--muted); font-size: 0.92rem; line-height: 1.65; }\n  .quick-answer-cta {\n    display: inline-flex;\n    min-height: 44px;\n    align-items: center;\n    justify-content: center;\n    margin-top: 22px;\n    padding: 11px 20px;\n    border-radius: 999px;\n    background: #2aabee;\n    color: #fff;\n    font-weight: 700;\n    text-decoration: none;\n  }\n  .quick-answer-cta:hover { background: #169bdc; }\n  .quick-answer-note { margin-top: 10px; color: var(--muted); font-size: 0.78rem; }\n  @media (max-width: 640px) {\n    .quick-answer { margin-inline: 16px; padding: 22px 18px; }\n  }\n\n  /* ── FOOTER ── */\n  footer {\r\n    border-top: 1px solid var(--border);\r\n    padding: 36px 24px;\r\n    text-align: center;\r\n    color: var(--muted);\r\n    font-size: 0.83rem;\r\n    line-height: 1.8;\r\n  }\r\n  footer a { color: var(--accent); text-decoration: none; }\r\n  footer a:hover { text-decoration: underline; }\r\n\r\n  /* ── ANIMATIONS ── */\r\n  @keyframes fadeUp {\r\n    from { opacity: 0; transform: translateY(18px); }\r\n    to   { opacity: 1; transform: translateY(0); }\r\n  }\r\n"
  }
};
